                    if not k.startswith("_")}

    # Determine the key order for indexing. If the instance has a
    # `_keys` attribute that lists the field names in order, use it;
    # otherwise fall back to the keys of the constructed map.
    if hasattr(self, "_keys") and isinstance(getattr(self, "_keys"), (list, tuple)):
        key_order = list(getattr(self, "_keys"))
    else:
        key_order = list(data_map.keys())

    if not keys:
        # Return a shallow copy of the map to avoid accidental mutation.
        return dict(data_map)

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(key_order):
                raise IndexError(f"Index {key} out of range")
            field_name = key_order[key]
            result[field_name] = data_map.get(field_name)
        else:
            # Store the key as is; missing keys map to None.
            result[key] = data_map.get(key)
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys are supplied, return the whole record
    if not keys:
        return dict(self._by_keys) if hasattr(self, "_by_keys") else {}
    # Determine the index order; use provided attribute or default list of keys
    index_order = getattr(self, "_idx_order", list(getattr(self, "_by_keys", {}).keys()))
    result = {}
    for key in keys:
        # Handle numeric index
        if isinstance(key, int):
            try:
                field = index_order[key]
            except IndexError as exc:
                raise IndexError(f"Index {key} out of bounds") from exc
            # Retrieve value if present, else None
            result[field] = getattr(self, "_by_keys", {}).get(field, None)
        else:
            # Treat as a key name
            result[key] = getattr(self, "_by_keys", {}).get(key, None)
    return result

def data(self, *keys):
        """ Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        # Build a mapping of field names to values for the record.
        if hasattr(self, "_data") and isinstance(self._data, dict):
            data_dict = self._data
        elif hasattr(self, "_values") and isinstance(self._values, list):
            # Try to infer keys from a _keys attribute if present.
            if hasattr(self, "_keys") and (isinstance(self._keys, list) or isinstance(self._keys, tuple)):
                data_dict = dict(zip(self._keys, self._values))
            else:
                # No explicit keys, use positional numbers as keys.
                data_dict = {f"_{i}": v for i, v in enumerate(self._values)}
        else:
            # Fall back to the instance __dict__ while ignoring private attributes.
            data_dict = {k: v for k, v in self.__dict__.items() if not k.startswith("_")}

        # If no keys specified, return all data.
        if not keys:
            return dict(data_dict)

        result = {}
        all_keys = list(data_dict.keys())
        for k in keys:
            if isinstance(k, int):
                idx = k
                # Allow negative indexing as Python would, but still check bounds.
                if idx < 0 or idx >= len(all_keys):
                    raise IndexError(f"index out of bounds: {idx}")
                key_name = all_keys[idx]
                result[key_name] = data_dict[key_name]
            else:
                key_name = str(k)
                result[key_name] = data_dict.get(key_name, None)
        return result

def pop_u16(self):
        """ Remove the last two bytes of data, returning them as a big-endian
        16-bit unsigned integer.
        """
        if len(self.data) < 2:
            raise ValueError("Not enough data to pop 2 bytes")
        value_bytes = self.data[-2:]
        del self.data[-2:]
        return self.unpack('>H', 2)

def pop_u16(self):
        """
        Remove the last two bytes of data, returning them as a big-endian
        16-bit unsigned integer.
        """
        # Ensure the instance has a data attribute
        if not hasattr(self, 'data'):
            raise AttributeError("Instance has no 'data' attribute")

        # Verify that enough data is present
        if len(self.data) < 2:
            raise ValueError("Not enough data to pop 2 bytes")

        # Extract the last two bytes
        try:
            # Handles bytes, bytearray, and list of ints
            last_two = bytes(self.data[-2:])
        except (TypeError, ValueError):
            raise TypeError("Data must be sliceable into bytes-like or list of ints")

        # Remove the last two bytes from the original data
        if isinstance(self.data, list):
            # If data is a list, slice returns a list
            self.data = self.data[:-2]
        else:
            # For bytes or bytearray, slicing returns similar type
            self.data = self.data[:-2]

        # Convert big-endian bytes to unsigned 16-bit integer
        return int.from_bytes(last_two, byteorder='big', signed=False)

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate numeric arguments
    if not isinstance(n, int):
        raise TypeError("Argument 'n' must be an integer")
    if not isinstance(qid, int):
        raise TypeError("Argument 'qid' must be an integer")

    # Normalise hooks
    dehydration_hooks = dehydration_hooks or {}
    hydration_hooks = hydration_hooks or {}

    # Build the DISCARD message payload
    msg = {
        "type": "DISCARD",
        "n": n,
        "qid": qid
    }

    # Apply dehydration hooks to any values that need it
    for key, func in dehydration_hooks.items():
        # Only apply to values that are instances of the expected type
        if key in msg and isinstance(msg[key], key):
            try:
                msg[key] = func(msg[key])
            except Exception as exc:
                raise ValueError(f"Dehydration hook for {key} raised an exception: {exc}") from exc

    # Append to the outbound queue; fall back to a generic send method
    if hasattr(self, "_out_queue"):
        try:
            self._out_queue.append(msg)
        except Exception as exc:
            raise RuntimeError(f"Failed to append message to _out_queue: {exc}") from exc
    elif hasattr(self, "_send"):
        try:
            self._send(msg)
        except Exception as exc:
            raise RuntimeError(f"Failed to send message via _send: {exc}") from exc
    else:
        raise AttributeError("No mechanism found to send the DISCARD message (neither _out_queue nor _send exists)")

    # Create and return the Response object
    # The Response class is assumed to accept a target (self) and handlers
    # along with any hooks needed for later hydration.
    try:
        return Response(
            connection=self,
            handlers=handlers,
            dehydration_hooks=dehydration_hooks,
            hydration_hooks=hydration_hooks
        )
    except Exception as exc:
        # Provide a more helpful error if Response is not defined or mis‑used
        raise RuntimeError(f"Failed to instantiate Response: {exc}") from exc

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError(f"Invalid mode {mode!r}. Must be 'READ' or 'WRITE'.")
    resolved_mode = mode or "WRITE"

    # Normalise bookmarks
    if bookmarks is None:
        resolved_bookmarks = ()
    else:
        # Ensure bookmarks is an iterable of strings, not a single string
        if isinstance(bookmarks, (str, bytes)):
            resolved_bookmarks = (bookmarks,)
        else:
            resolved_bookmarks = tuple(bookmarks)

    # Validate metadata
    resolved_metadata = {} if metadata is None else dict(metadata)

    # Apply dehydration hooks to the metadata values
    if dehydration_hooks:
        for key, val in list(resolved_metadata.items()):
            hook = dehydration_hooks.get(type(val))
            if hook:
                try:
                    resolved_metadata[key] = hook(val)
                except Exception as exc:
                    raise ValueError(
                        f"Error in dehydration hook for type {type(val).__name__}"
                    ) from exc

    # Construct the BEGIN message payload
    begin_msg = {
        "message_type": "BEGIN",
        "mode": resolved_mode,
        "bookmarks": list(resolved_bookmarks),
        "metadata": resolved_metadata,
    }
    if timeout is not None:
        begin_msg["timeout"] = timeout
    if db is not None:
        begin_msg["database"] = db
    if imp_user is not None:
        begin_msg["impersonated_user"] = imp_user

    # Append to output queue.  The queue attribute name may differ in the
    # actual implementation – we use a common placeholder here.
    if hasattr(self, "_output_queue"):
        self._output_queue.append(begin_msg)
    elif hasattr(self, "_queue"):
        self._queue.append(begin_msg)
    else:
        # Fallback: try to use a generic send method if available
        send_method = getattr(self, "send_message", None)
        if callable(send_method):
            send_method(begin_msg)
        else:
            raise AttributeError(
                "Cannot find an output queue or message sender on this session."
            )

    # Create and return a Response object, passing along any handler
    # callbacks supplied by the caller.
    if handlers:
        return Response(**handlers)
    return Response()

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
