        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode if provided
    if mode is not None:
        mode_str = str(mode).upper()
        if mode_str not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")
        mode_val = mode_str
    else:
        mode_val = None

    # Convert bookmarks to list if provided
    if bookmarks is not None:
        try:
            bookmark_list = list(bookmarks)
        except Exception as exc:
            raise ValueError("bookmarks must be an iterable") from exc
    else:
        bookmark_list = None

    # Validate dehydration_hooks and hydration_hooks if provided
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise ValueError("dehydration_hooks must be a dict")
        for key, func in dehydration_hooks.items():
            if not callable(func):
                raise ValueError(f"dehydration hook for {key} is not callable")
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise ValueError("hydration_hooks must be a dict")
        for key, func in hydration_hooks.items():
            if not callable(func):
                raise ValueError(f"hydration hook for {key} is not callable")

    # Build options dictionary for the BEGIN message
    options = {}
    if mode_val is not None:
        options["mode"] = mode_val
    if bookmark_list is not None:
        options["bookmarks"] = bookmark_list
    if metadata is not None:
        if not isinstance(metadata, dict):
            raise ValueError("metadata must be a dict")
        options["metadata"] = metadata
    if timeout is not None:
        try:
            timeout_val = float(timeout)
        except Exception as exc:
            raise ValueError("timeout must be a number") from exc
        options["timeout"] = timeout_val
    if db is not None:
        options["db"] = db
    if imp_user is not None:
        options["imp_user"] = imp_user
    if dehydration_hooks is not None:
        options["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        options["hydration_hooks"] = hydration_hooks

    # Prepare the BEGIN message
    begin_msg = {"type": "BEGIN", "options": options}

    # Append to the output queue; create if it does not exist
    queue = getattr(self, "_output_queue", None)
    if queue is None:
        queue = []
        setattr(self, "_output_queue", queue)
    queue.append(begin_msg)

    # Return a Response object; assume Response takes the transaction instance
    # and handlers dictionary. If Response signature differs, adjust accordingly.
    try:
        return Response(self, handlers)
    except NameError:
        # Fallback: return the message for debugging
        return begin_msg

