def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Basic validation of the input arguments
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"name must be a valid identifier, got {name!r}")

    if not (isinstance(fields, (list, tuple))):
        raise TypeError(f"fields must be a list or tuple, got {type(fields).__name__}")

    seen = set()
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"field names must be strings, got {f!r}")
        if not f.isidentifier():
            raise TypeError(f"field name {f!r} is not a valid identifier")
        if f in seen:
            raise TypeError(f"duplicate field name: {f!r}")
        seen.add(f)

    # Prepare the namespace for the new class
    namespace = {"__slots__": fields}
    # The class will inherit from Point if it exists, otherwise fall back to object
    Base = globals().get("Point", object)

    def __init__(self, *args, **kwargs):
        total_needed = len(fields)
        if len(args) + len(kwargs) != total_needed:
            raise TypeError(f"{name} expected {total_needed} values, got {len(args)} args + {len(kwargs)} kwargs")
        # Positional assignments
        for field_name, value in zip(fields, args):
            setattr(self, field_name, value)
        # Keyword assignments
        for key, value in kwargs.items():
            if key not in fields:
                raise TypeError(f"unexpected keyword argument {key!r}")
            setattr(self, key, value)

    def __repr__(self):
        parts = [f"{fname}={getattr(self, fname)!r}" for fname in fields]
        return f"{name}({', '.join(parts)})"

    namespace["__init__"] = __init__
    namespace["__repr__"] = __repr__
    # Attach the SRID map as a class attribute for later use
    namespace["srid_map"] = srid_map

    # Dynamically create and return the new subclass
    return type(name, (Base,), namespace)

def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass with user‑defined attributes."""
    # Imports are performed lazily to keep the function self‑contained.
    try:
        from shapely.geometry import Point
    except Exception:
        # Fallback for environments without shapely.
        Point = object

    from typing import Any
    import keyword

    # Prepare class namespace.
    namespace = {}

    # Collect annotations for the user‑defined fields.
    annotations = {}
    for item in fields:
        if isinstance(item, str):
            fname = item
            ftype = Any
        else:
            try:
                fname, ftype = item
            except Exception:
                # Treat single‑element iterators as field name only.
                if isinstance(item, (tuple, list)):
                    if len(item) == 1:
                        fname = item[0]
                        ftype = Any
                    else:
                        raise TypeError(f"Invalid field specification: {item!r}")
                else:
                    raise TypeError(f"Invalid field specification: {item!r}")

        if not isinstance(fname, str) or not fname.isidentifier():
            raise TypeError(f"Field names must be valid identifiers: {fname!r}")
        if keyword.iskeyword(fname):
            raise TypeError(f"Field names must not be keywords: {fname!r}")
        annotations[fname] = ftype
        # Default value of None for user fields.
        namespace[fname] = None

    namespace['__annotations__'] = annotations
    namespace['SRID_MAP'] = srid_map

    # Define an __init__ that forwards x/y/z to the base class and accepts
    # arbitrary keyword arguments that correspond to the user fields.
    def _init(self, x, y, z=None, **kwargs):
        super(Point, self).__init__(x, y, z)
        for key, value in kwargs.items():
            if key in annotations:
                setattr(self, key, value)
            else:
                raise TypeError(f"Unexpected keyword argument: {key!r}")

    namespace['__init__'] = _init

    # Create and return the dynamically constructed subclass.
    return type(name, (Point,), namespace)

def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass.

    The created class will have positional arguments ``x`` and ``y`` (the
    coordinates), an optional keyword argument ``srid`` which must be a key in
    ``srid_map`` if provided, and any number of keyword arguments matching
    the names given in ``fields``.  The field specifications can be either
    strings (the type will be ``object``) or 2-tuples ``(name, type)``; only
    the name is used for attribute creation but the type is stored as an
    annotation.  The resulting class uses ``__slots__`` so that instances
    are lightweight and memory efficient.

    Args:
        name: Class name as a string.
        fields: Iterable of field specifications.  Each element is either
            a string ``field_name`` or a 2-tuple ``(field_name, type)``.
        srid_map: Mapping from SRID integer to any description.  The mapping
            is stored on the class as ``_srid_map`` and the ``srid`` keyword
            passed to ``__init__`` must be a key in this dictionary.

    Returns:
        A new class object with the given name and behavior.
    """
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {name!r}")
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {srid_map!r}")

    # Prepare storage for annotations and default values
    annotations = {}
    default_values = {}
    slot_names = ["x", "y", "srid"]
    # Validate and process each field
    seen = set()
    for item in fields:
        if isinstance(item, str):
            field_name, field_type = item, object
        elif isinstance(item, tuple) and len(item) == 2:
            field_name, field_type = item
        else:
            raise TypeError(f"Field definition must be a string or (name, type): {item!r}")

        if not isinstance(field_name, str) or not field_name.isidentifier():
            raise TypeError(f"Invalid field name: {field_name!r}")
        if field_name in seen:
            raise TypeError(f"Duplicate field name: {field_name!r}")
        seen.add(field_name)

        annotations[field_name] = field_type
        default_values[field_name] = None
        slot_names.append(field_name)

    # Build class namespace
    namespace = {
        "__doc__": f"Dynamic point class {name}",
        "__slots__": tuple(slot_names),
        "_srid_map": srid_map,
        "__annotations__": annotations,
    }
    # Add default values for fields
    namespace.update(default_values)

    def __init__(self, x, y, srid=None, **kwargs):
        self.x = x
        self.y = y
        if srid is not None:
            if srid not in srid_map:
                raise ValueError(f"Unsupported SRID {srid!r}")
            self.srid = srid
        else:
            self.srid = None
        # Set optional fields
        for key, value in kwargs.items():
            if key not in annotations:
                raise TypeError(f"Unexpected field {key!r}")
            setattr(self, key, value)

        # Ensure all defined fields are present (even if default None)
        for key in annotations:
            if not hasattr(self, key):
                setattr(self, key, None)

    namespace["__init__"] = __init__

    # Create and return the new type
    return type(name, (object,), namespace)

def deprecated(message):
    """Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """

    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper

    return decorator

