def extostr(cls, e, max_level=30, max_path_level=5):
    # type: (Any, Exception, int, int) -> str
    """
    Format an exception into a readable string.
    """
    try:
        # Handle None or non‑exception inputs gracefully
        if e is None:
            return ''
        # Ensure we have the exception instance
        if not isinstance(e, BaseException):
            return str(e)

        ex_type = e.__class__.__name__
        ex_msg = str(e)

        # Attempt to obtain the traceback
        tb = getattr(e, "__traceback__", None)
        frames = []
        if tb is not None:
            import traceback
            import os
            frames = traceback.extract_tb(tb)
        else:
            # Fallback: try to use the current sys.exc_info()
            import sys
            exc_type, exc_value, exc_tb = sys.exc_info()
            if exc_value is e and exc_tb is not None:
                import traceback
                frames = traceback.extract_tb(exc_tb)

        # Truncate the stack to the most recent frames (limited by max_level)
        if len(frames) > max_level:
            frames = frames[-max_level:]

        # Helper to shorten file paths
        def _short_path(path, level):
            parts = path.split(os.sep)
            return os.sep.join(parts[-level:]) if len(parts) > level else path

        # Build formatted lines
        if frames:
            lines = ["Traceback (most recent call last):"]
            for fr in frames:
                short_file = _short_path(fr.filename, max_path_level)
                lines.append(f'  File "{short_file}", line {fr.lineno}, in {fr.name}')
                if fr.line is not None:
                    # Indent source code line for readability
                    src = fr.line.strip()
                    if src:
                        lines.append(f'    {src}')
            lines.append(f"{ex_type}: {ex_msg}")
            return "\n".join(lines)
        else:
            return f"{ex_type}: {ex_msg}"
    except Exception as format_err:
        # Fallback in case formatting itself fails
        return f"Exception formatting failed: {format_err}"

def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        import traceback, os

        def _short_path(path):
            try:
                parts = path.split(os.sep)
            except Exception:
                return path
            if len(parts) > max_path_level:
                return os.sep.join(parts[-max_path_level:])
            return path

        def _format_exc(exc, level=0, seen=None):
            if seen is None:
                seen = set()
            if exc is None or id(exc) in seen:
                return ""
            seen.add(id(exc))

            parts = []

            # Basic exception info
            parts.append(f"{exc.__class__.__name__}: {exc}")

            # Traceback information
            tb = exc.__traceback__
            if tb:
                tb_items = traceback.extract_tb(tb)
                # limit to max_level
                tb_items = tb_items[:max_level]
                for frame in tb_items:
                    file_path = _short_path(frame.filename)
                    parts.append(
                        f'  File "{file_path}", line {frame.lineno}, in {frame.name}'
                    )
                    if frame.line:
                        parts.append(f"    {frame.line.strip()}")
            else:
                parts.append("  No __traceback__ available")

            # Context or cause
            child_exc = None
            if exc.__cause__:
                child_exc = exc.__cause__
                sep = "Caused by: "
            elif exc.__context__ and not exc.__suppress_context__:
                child_exc = exc.__context__
                sep = "During handling of the above exception, another exception occurred: "
            else:
                sep = None

            if child_exc and sep:
                parts.append(sep)
                parts.append(_format_exc(child_exc, level + 1, seen))

            return "\n".join(parts)

        try:
            return _format_exc(e)
        except Exception as gen_exc:
            return f"Failed to format exception: {gen_exc}"

