def _legacy_mergeOrderings(orderings):
    """
    Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ...     ['x', 'y', 'z'],
    ...     ['q', 'z'],
    ...     [1, 3, 5],
    ...     ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']
    """
    # Validate input
    if not isinstance(orderings, list):
        raise TypeError("orderings must be a list of lists")
    # Build graph of precedence constraints
    graph = {}
    indegree = {}
    priority = {}
    prio_counter = 0
    # Record nodes and edges
    for ordering in orderings:
        if not isinstance(ordering, list):
            raise TypeError("Each ordering must be a list")
        for i, node in enumerate(ordering):
            if node not in graph:
                graph[node] = []
            if node not in indegree:
                indegree[node] = 0
            if node not in priority:
                priority[node] = prio_counter
                prio_counter += 1
            if i < len(ordering) - 1:
                nxt = ordering[i + 1]
                if nxt not in graph:
                    graph[nxt] = []
                if nxt not in indegree:
                    indegree[nxt] = 0
                if nxt not in priority:
                    priority[nxt] = prio_counter
                    prio_counter += 1
                # avoid duplicate edges
                if nxt not in graph[node]:
                    graph[node].append(nxt)
                    indegree[nxt] += 1
    # Topological sort with deterministic priority
    result = []
    zero_nodes = [node for node, deg in indegree.items() if deg == 0]
    while zero_nodes:
        # Choose node with smallest priority (first appearance)
        zero_nodes.sort(key=lambda x: priority[x])
        node = zero_nodes.pop(0)
        result.append(node)
        for neigh in graph.get(node, []):
            indegree[neigh] -= 1
            if indegree[neigh] == 0:
                zero_nodes.append(neigh)
    if len(result) != len(indegree):
        raise ValueError("Cyclic dependency detected among orderings")
    return result

