    while zero_in:
        # pick the node with the smallest first occurrence value
        node = min(zero_in, key=lambda n: first_occurrence.get(n, float('inf')))
        zero_in.remove(node)
        result.append(node)

        for succ in graph.get(node, []):
            indegree[succ] -= 1
            if indegree[succ] == 0:
                zero_in.append(succ)

    if len(result) != len(graph):
        # A cycle exists; according to constraints this should not happen
        raise ValueError("Orderings contain a cycle and cannot be merged")

    return result

def directlyProvidedBy(obj):  # pylint:disable=redefined-builtin
    """
    Return the interfaces directly provided by the given object.

    The value returned is an ``~zope.interface.interfaces.IDeclaration``.
    """
    # First, try the instance attribute.  Zope 3 uses ``__provides__`` to
    # store an instance ``Declaration``.
    if hasattr(obj, "__provides__"):
        return getattr(obj, "__provides__")

    # For classes (including metaclasses) the same attribute may live on the
    # class object itself.
    cls = getattr(obj, "__class__", None)
    if cls and hasattr(cls, "__provides__"):
        return getattr(cls, "__provides__")

    # If the object itself is a class, inspect it directly.
    if isinstance(obj, type) and hasattr(obj, "__provides__"):
        return getattr(obj, "__provides__")

    # If no declaration was found, return an empty ``IDeclaration``.
    # ``zope.interface.Declaration``([]) is a common way to represent an empty
    # set of interfaces.  Importing lazily to avoid circular dependencies.
    try:
        from zope.interface import Declaration
        return Declaration([])
    except Exception:  # pragma: no cover
        # As a last resort return an empty tuple which can be interpreted as
        # an empty declaration by callers that do simple truthiness checks.
        return ()

