def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        provides = getattr(object, "__provides__")
    except AttributeError:
        # No explicit provides declaration; return an empty one
        return zope.interface.declarations.Declaration()
    else:
        # If it's already a Declaration instance, return it as is
        if isinstance(provides, zope.interface.declarations.Declaration):
            return provides
        # Otherwise, assume it's a tuple/list of interfaces and wrap it
        try:
            return zope.interface.declarations.Declaration(*provides)
        except TypeError:
            # Fallback: return as empty declaration if provisioning information is invalid
            return zope.interface.declarations.Declaration()

