    try:
        from zope.interface import directlyProvidedBy as _directlyProvidedBy
    except Exception as exc:
        # zope.interface is not available; cannot determine interfaces
        raise RuntimeError("zope.interface is required to determine provided interfaces: %s" % exc) from exc

    try:
        return _directlyProvidedBy(object)
    except Exception:
        # If the object does not provide any interfaces directly, return an empty tuple
        return ()

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []
    try:
        classes = list(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of classes")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"{cls!r} is not a class")
        # Skip duplicate classes
        if cls in result:
            continue
        # Remove any existing superclasses of cls
        result = [c for c in result if not issubclass(cls, c)]  # cls is subclass of c -> c is super, remove
        # If any existing subclass of cls, then cls is a super class; skip adding
        if any(issubclass(c, cls) and c is not cls for c in result):
            continue
        result.append(cls)
    return result

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    The result is a list with the same order as the first appearance of
    each minimal base.  A base is considered minimal if it is not a
    superclass of any other base in the input list.
    """
    # Convert to list if not already and validate type
    try:
        bases = list(classes)
    except Exception as exc:
        raise TypeError("classes must be an iterable of types") from exc

    # Ensure each element is a type
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"element {b!r} is not a type")

    # Identify minimal bases (i.e. not superclasses of any later base)
    minimal = []
    for i, b in enumerate(bases):
        redundant = False
        for later in bases[i + 1 :]:
            if later is b:
                continue
            try:
                if issubclass(later, b):
                    redundant = True
                    break
            except TypeError:
                # If for some reason issubclass fails, ignore this pair
                continue
        if not redundant:
            minimal.append(b)

    # Remove duplicates while preserving order
    seen = set()
    result = []
    for b in minimal:
        if b not in seen:
            seen.add(b)
            result.append(b)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent.

    The result contains the smallest set of classes such that each original
    class is either included or a subclass of one of the returned classes.
    The order preserves the first occurrence of each minimal base in the
    input list.
    """
    if classes is None:
        raise TypeError("classes must be an iterable of class objects")
    minimal = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected class, got {type(cls).__name__}")
        # Skip if cls is a subclass of an already kept class, or if an
        # already kept class is a subclass of cls (which would make cls
        # redundant).
        redundant = False
        for base in minimal:
            try:
                if issubclass(cls, base) or issubclass(base, cls):
                    redundant = True
                    break
            except TypeError:
                # If for some reason issubclass fails, treat as not related
                continue
        if not redundant:
            minimal.append(cls)
    return minimal

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    Each class in the result is not a subclass of any other class in the result.
    The original order of appearance is preserved for the selected classes.
    """
    # Convert to a list to allow multiple passes and support any iterable
    try:
        all_classes = list(classes)
    except TypeError:
        raise TypeError("'classes' must be an iterable of types")

    # Validate that every item is a class
    for idx, cls in enumerate(all_classes):
        if not isinstance(cls, type):
            raise TypeError(f"item at index {idx} is not a class (got {type(cls)!r})")

    # Preserve the order of first appearance
    seen = set()
    ordered = []
    for cls in all_classes:
        if cls not in seen:
            seen.add(cls)
            ordered.append(cls)

    # Determine the minimal set: classes that are not subclasses of any other
    minimal = []
    for cls in ordered:
        # Skip if cls is a subclass of another class in the ordered list
        if any(issubclass(cls, other) and other is not cls for other in ordered):
            continue
        minimal.append(cls)

    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Validate the optional flag parameter
    if not isinstance(all, bool):
        raise TypeError("'all' must be a bool, not {!r}".format(type(all).__name__))

    # Start with any explicitly defined interface dictionary.
    # It may be present as a class or instance attribute named '_INTERFACE'.
    interface = getattr(self, "_INTERFACE", None)
    if isinstance(interface, dict):
        descriptions = dict(interface)  # copy to avoid mutation
    else:
        descriptions = {}

    if all:
        # Include additional attributes on the instance that are not private.
        # For each attribute, try to obtain a string description from its
        # __doc__ property (or default to an empty string).  Respect any
        # existing entry from the explicit interface.
        for name, value in vars(self).items():
            if name.startswith("_"):
                continue
            if name in descriptions:
                continue
            desc = getattr(value, "__doc__", "")
            if not isinstance(desc, str):
                desc = ""
            descriptions[name] = desc

    return descriptions

