def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    results = {}
    # Collect attributes from the class and the instance, but prefer class attributes
    class_attrs = getattr(self.__class__, "__dict__", {})
    instance_attrs = getattr(self, "__dict__", {})
    # Merge attribute names; class attributes take precedence over instance attributes
    all_names = set(class_attrs.keys()) | set(instance_attrs.keys())

    for name in all_names:
        # Skip special and private attributes unless all=True
        if not all and (name.startswith("_") or name in ("__dict__", "__weakref__", "__module__", "__doc__")):
            continue

        # Retrieve the attribute value: prefer class attribute, otherwise instance
        value = class_attrs.get(name, instance_attrs.get(name))

        # Skip methods or other callables
        if callable(value):
            continue

        # Attempt to obtain a description
        desc = None
        try:
            desc = getattr(value, "description", None)
        except Exception:
            desc = None
        if desc is None:
            try:
                desc = getattr(value, "__doc__", None)
            except Exception:
                desc = None
        if desc is None:
            desc = ""

        results[name] = desc
    return results

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    import inspect
    # Collect names from instance dict
    names = set(self.__dict__.keys())
    # Add class-level attributes
    cls = type(self)
    for name, val in cls.__dict__.items():
        if name.startswith('_'):
            continue
        if isinstance(val, property):
            names.add(name)
