        names = [n for n, v in self.__class__.__dict__.items() if not n.startswith("_")]
    return sorted(names)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    # Do not treat strings or bytes as iterables to be expanded
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return output

    # Prepare names that may be defined in the caller's namespace
    InterfaceClass = None
    Implements = None
    try:
        InterfaceClass = zope.interface.interface.InterfaceClass
    except Exception:
        pass
    try:
        Implements = zope.interface.declarations.Implements
    except Exception:
        pass

    # If the sequence is a class that is an interface or Implements spec, append it
    if isinstance(sequence, type):
        if InterfaceClass is not None and isinstance(sequence, InterfaceClass):
            output.append(sequence)
            return output

    if Implements is not None and isinstance(sequence, Implements):
        output.append(sequence)
        return output

    # If the sequence is an iterable (but not a string/bytes), recurse into its items
    if hasattr(sequence, "__iter__"):
        for item in sequence:
            _normalizeargs(item, output)
        return output

    # Fallback: append the sequence as an individual element
    output.append(sequence)
    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle special case of a "Broken" declaration if available
    try:
        if Broken in getattr(sequence, "__bases__", ()):
            return [sequence]
    except NameError:
        pass

    # Determine if sequence is an interface or implements spec
    try:
        cls = sequence.__class__
        if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
            output.append(sequence)
            return output
    except NameError:
        # If InterfaceClass or Implements is not defined, skip the check
        pass

    # Try to iterate over the sequence; if not iterable, just append it
    try:
        for v in sequence:
            _normalizeargs(v, output)
    except TypeError:
        output.append(sequence)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle the special Broken interface sentinel
    try:
        if Broken in getattr(sequence, "__bases__", ()):
            output.append(sequence)
            return output
    except Exception:
        pass

    # If the object is an interface class or an implements specification,
    # add it directly to the output list.
    cls = getattr(sequence, "__class__", None)
    if cls is not None:
        mro = getattr(cls, "__mro__", ())
        for parent in mro:
            name = getattr(parent, "__name__", "")
            if name in ("InterfaceClass", "Implements"):
                output.append(sequence)
                return output

    # If the sequence is an iterable (but not a string or bytes), recurse.
    if isinstance(sequence, (list, tuple)):
        for item in sequence:
            _normalizeargs(item, output)
    elif hasattr(sequence, "__iter__") and not isinstance(sequence, (str, bytes)):
        try:
            for item in sequence:
                _normalizeargs(item, output)
        except TypeError:
            output.append(sequence)
    else:
        output.append(sequence)

    return output

def _normalizeargs(sequence, output=None):
