    """
    if output is None:
        output = []

    # If sequence is an iterable (list, tuple, set) treat it as a collection
    # and recursively flatten it; otherwise consider it an individual interface.
    try:
        # Strings and bytes are iterable, but should be treated as indivisible
        if isinstance(sequence, (list, tuple, set)):
            for element in sequence:
                _normalizeargs(element, output)
        else:
            output.append(sequence)
    except TypeError:
        # Non-iterable objects
        output.append(sequence)

    return output

