def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset current context
    if hasattr(self, "current_context"):
        self.current_context = {}
    elif hasattr(self, "context"):
        self.context = {}

    # Reinitialize bins
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # If bins already exist, preserve size
        if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
            try:
                size = len(self.bins)
            except Exception:
                size = 1
            # If initial_value is iterable, attempt to match size
            if isinstance(self.initial_value, (list, tuple)) and len(self.initial_value) == size:
                self.bins = list(self.initial_value)
            else:
                self.bins = [self.initial_value] * size
        else:
            # No bins yet – create a single bin
            self.bins = [self.initial_value]
    elif hasattr(self, "make_bins") and callable(self.make_bins):
        try:
            self.bins = self.make_bins()
        except Exception:
            # Fallback if make_bins fails
            self.bins = []
    else:
        # No strategy available – set to empty list
        self.bins = []

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    try:
        self.context = {}
    except AttributeError:
        # If the histogram has no context attribute, silently ignore
        pass

    # Reinitialize bins
    bins_reset = False
    # Prefer explicit `initial_value` if it exists and is not None
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # If the initial_value is iterable, use a copy; otherwise replicate
        try:
            # Attempt to convert to a list; this will succeed for strings which are iterable,
            # but we want to treat strings as a single value in this context.
            if isinstance(self.initial_value, (bytes, bytearray)):
                # Bytes/bytearray are treated as a single value
                init_bins = [self.initial_value]
            else:
                # Try to copy iterable values
                init_bins = list(self.initial_value)
            # Ensure that we have at least one bin – if the iterable was empty,
            # fall back to make_bins().
            if len(init_bins) == 0 and hasattr(self, "make_bins"):
                init_bins = self.make_bins()
            self.bins = init_bins
            bins_reset = True
        except TypeError:
            # initial_value is a scalar – replicate across existing bins
            if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                n_bins = len(self.bins)
            else:
                n_bins = 0
            self.bins = [self.initial_value] * n_bins
            bins_reset = True
    elif hasattr(self, "make_bins"):
        # Fall back to make_bins if no explicit initial_value
        try:
            self.bins = self.make_bins()
            bins_reset = True
        except Exception:
            # If make_bins fails, ignore and leave self.bins unchanged
            pass

    # If bins were not reset by the above logic, clear any existing bins
    if not bins_reset:
        try:
            # Attempt to clear the bins list if it exists
            if hasattr(self, "bins") and isinstance(self.bins, list):
                self.bins.clear()
        except Exception:
            pass

