        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Try to find the bins attribute (it may be named differently)
            bins_container = None
            for attr in ("bins", "data", "values"):
                if hasattr(self, attr):
                    bins_container = getattr(self, attr)
                    break
            # If a list-like container is found, replicate its size
            if isinstance(bins_container, (list, tuple)):
                self.bins = [self.initial_value] * len(bins_container)
            else:
                # Fall back to a single bin
                self.bins = [self.initial_value]
        # Otherwise, fallback to a factory method if available
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
