def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to locate a dedicated error attribute following common naming patterns
    potential_keys = [f"{coord_name}_err", f"{coord_name}_errors", f"errors_{coord_name}"]
    for key in potential_keys:
        # Check if the attribute exists directly on the instance
        if hasattr(self, key):
            val = getattr(self, key)
            # Return directly if the value appears to be an index sequence
            if isinstance(val, (list, tuple)):
                return val
        # Check if the attribute is stored in the Data dictionary
        data_dict = getattr(self, "Data", None)
        if isinstance(data_dict, dict) and key in data_dict:
            val = data_dict[key]
            if isinstance(val, (list, tuple)):
                return val
    # If the instance maintains a map of variables (e.g., self._variables),
    # attempt to pull the error indices from there
    if hasattr(self, "_variables") and isinstance(self._variables, dict):
        for key in potential_keys:
            if key in self._variables:
                var = self._variables[key]
                if hasattr(var, "indexes"):
                    return var.indexes
                if hasattr(var, "index"):
                    return var.index
    # If none of the above paths yielded an index sequence, raise an informative error
    raise KeyError(f"Could not find error indices for coordinate '{coord_name}'.")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate.

    The method attempts to locate the error array or index mapping
    associated with *coord_name* in common attribute names
    (``err_indexer``, ``err_indices`` or ``errors``).  If a suitable
    mapping or array is found the indices are returned as a
    :class:`~numpy.ndarray`.  If no error information is available
    an empty array is returned.

    Parameters
    ----------
    coord_name : str
        Name of the coordinate whose error indices are requested.

    Returns
    -------
    numpy.ndarray
        Array of indices corresponding to the error array of the
        coordinate.  Empty if not found.
    """
    import numpy as np

    # 1. Direct mapping dictionaries holding NumPy arrays or lists
    err_map_names = ["err_indexer", "err_indices"]
    for map_name in err_map_names:
        if hasattr(self, map_name):
            mapping = getattr(self, map_name)
            if isinstance(mapping, dict):
                idx = mapping.get(coord_name)
                if idx is not None:
                    return np.asarray(idx)

    # 2. ``errors`` attribute may hold either an array or an object
    #    with an ``indices`` attribute.
    if hasattr(self, "errors"):
        errors = getattr(self, "errors")
        if isinstance(errors, dict) and coord_name in errors:
            err_obj = errors[coord_name]
            # If the object provides indices directly
            if hasattr(err_obj, "indices"):
                return np.asarray(err_obj.indices)
            # Fallback: treat the object as an array-like
            try:
                arr = np.asarray(err_obj)
            except Exception:
                pass
            else:
                if arr.ndim == 0:
                    return np.array([0]) if ~np.isnan(arr) else np.array([])
                # Return all valid indices (non-NaN)
                return np.where(~np.isnan(arr))[0]

    # 3. No error information found; return empty array.
    return np.array([])

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Preferred: use a dedicated mapping if it exists
    if hasattr(self, "_err_indices"):
        return list(self._err_indices.get(coord_name, []))
    # Fallback: if errors are stored in a list, try to match by coordinate name
    if hasattr(self, "errors"):
        return [i for i, e in enumerate(self.errors) if getattr(e, "coord", None) == coord_name]
    # Safe default: return empty list if nothing is found
    return []

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    """
    import numpy as np

    try:
        bins_arr = np.asarray(bins, dtype=float).ravel()
        edges_arr = np.asarray(edges, dtype=float).ravel()
    except Exception as exc:
        raise ValueError("bins and edges must be array-like") from exc

    if bins_arr.ndim != 1:
        raise ValueError("bins must be one-dimensional")
    if edges_arr.ndim != 1:
        raise ValueError("edges must be one-dimensional")
    if edges_arr.size != bins_arr.size + 1:
        raise ValueError("edges must have length bins+1")
    if not np.all(np.diff(edges_arr) > 0):
        raise ValueError("edges must be strictly increasing")

    widths = np.diff(edges_arr)
    return float(np.sum(bins_arr * widths))

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    try:
        bins_arr = np.asarray(bins, dtype=float)
    except Exception:
        raise TypeError("`bins` must be array-like or convertible to an array")

    # Determine if edges correspond to 1D or ND histogram
    # If edges is a sequence of arrays (histogramdd), otherwise
    # it is a single array of bin edges
    if isinstance(edges, (list, tuple)):
        # For multiple dimensions
        try:
            edges_list = [np.asarray(e, dtype=float) for e in edges]
        except Exception:
            raise TypeError("'edges' must be array-like")
        if len(edges_list) != bins_arr.ndim:
            raise ValueError("Number of edge lists must match number of dimensions of bins")
        try:
            widths = [np.diff(e) for e in edges_list]
        except Exception:
            raise ValueError("Failed to compute differences of edges")
        # Compute volume (product of widths) per bin
        try:
            bin_volumes = np.multiply.reduce([np.asarray(w) for w in widths])
        except Exception as e:
            raise RuntimeError(f"Error computing bin volumes: {e}")
    else:
        # 1D histogram
        try:
            edges_arr = np.asarray(edges, dtype=float)
        except Exception:
            raise TypeError("'edges' must be array-like")
        if len(edges_arr) != bins_arr.size + 1:
            raise ValueError(
                "len(edges) must equal len(bins)+1 for 1D histograms"
            )
        try:
            bin_volumes = np.diff(edges_arr)
        except Exception:
            raise RuntimeError("Failed to compute differences of edges")

    # Ensure shapes match
    try:
        bin_volumes = np.asarray(bin_volumes, dtype=float)
    except Exception:
        raise RuntimeError("Failed to cast bin_volumes to float array")
    if bin_volumes.shape != bins_arr.shape:
        raise ValueError(
            f"Shape mismatch: bins {bins_arr.shape} vs bin volumes {bin_volumes.shape}"
        )

    # Compute integral
    try:
        result = np.sum(bins_arr * bin_volumes)
    except Exception as e:
        raise RuntimeError(f"Error computing integral: {e}")

    return float(result)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to numpy arrays if they aren't already
    bins = np.asarray(bins)
    # Determine whether edges is a single array (1‑D case) or a sequence of arrays (N‑D case)
    if np.ndim(edges) == 1:
        # 1‑D case
        if bins.ndim != 1:
            raise ValueError("For 1‑D edges, bins must be a 1‑D array.")
        if edges.shape[0] - 1 != bins.shape[0]:
            raise ValueError("Number of bins must be one less than the number of edges.")
        widths = np.diff(edges)
        return float(np.sum(bins * widths))
    else:
        # N‑D case: edges is an iterable of 1‑D arrays
        edge_list = list(edges)
        if len(edge_list) != bins.ndim:
            raise ValueError(
                f"Number of edges arrays ({len(edge_list)}) must match bins dimensionality ({bins.ndim})."
            )
        # Compute width for each dimension
        widths = []
        for i, e in enumerate(edge_list):
            e = np.asarray(e)
            if e.ndim != 1:
                raise ValueError(f"Edge array at position {i} must be 1‑D.")
            if e.shape[0] - 1 != bins.shape[i]:
                raise ValueError(
                    f"Edge array at position {i} has length {e.shape[0]}, "
                    f"which does not match the size {bins.shape[i]} of bins in that dimension "
                    f"(needs one more edge than bins)."
                )
            widths.append(np.diff(e))
        # Reshape widths to broadcast across bins
        for i, w in enumerate(widths):
            shape = [1] * bins.ndim
            shape[i] = w.shape[0]
            widths[i] = w.reshape(shape)
        # Compute cell volumes by multiplying widths across all dimensions
        volume = widths[0]
        for w in widths[1:]:
            volume = volume * w
        # Compute integral
        return float(np.sum(bins * volume))

