def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    import numpy as np

    # Ensure histogram has the required attributes
    if not hasattr(self, "edges"):
        raise AttributeError("Histogram instance must have an 'edges' attribute.")
    if not hasattr(self, "data"):
        raise AttributeError("Histogram instance must have a 'data' attribute.")

    # Convert weight to a numeric scalar
    try:
        weight = float(weight)
    except Exception:
        raise ValueError("weight must be convertible to a float.")

    # Normalize coordinate input to a list (or tuple) of coordinates
    # for multi‑dimensional histograms, or to a single value for 1‑D
    try:
        coord_list = list(coord)
    except TypeError:
        coord_list = [coord]

    edges = self.edges
    # If the histogram is one‑dimensional and edges is a 1‑D array,
    # we interpret it directly; otherwise we expect a sequence of 1‑D
    # arrays (one per dimension).
    if np.ndim(edges) == 1:
        edges = [edges]

    if len(edges) != len(coord_list):
        raise ValueError(
            f"Number of coordinates ({len(coord_list)}) must match the "
            f"number of histogram dimensions ({len(edges)})."
        )

    # Find the bin index for each dimension
    bin_indices = []
    for c, e in zip(coord_list, edges):
        if c < e[0] or c >= e[-1]:
            # Coordinate is outside the histogram bounds; ignore it
            return
        # Searchsorted returns the insertion point which is the index of the
        # right edge. Subtract one to get the bin index.
        idx = np.searchsorted(e, c, side="right") - 1
        # Guard against numerical rounding errors that might give idx == len(e)-1
        if idx < 0 or idx >= len(e) - 1:
            return
        bin_indices.append(idx)

    # Update the histogram count
    try:
        self.data[tuple(bin_indices)] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram data: {exc}") from exc

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Convert coord to array and validate dimensionality
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise ValueError(f"coord must be array-like, got {type(coord)}") from exc

    if coord_arr.ndim != 1 or coord_arr.size != len(self.edges):
        raise ValueError(
            f"coord must be a 1‑D iterable of length {len(self.edges)}, "
            f"got shape {coord_arr.shape}"
        )

