    if not np.isscalar(weight):
        raise ValueError(f"weight must be a scalar, got {type(weight)}")

    try:
        self.data[tuple(idx)] += weight
    except Exception as exc:
        raise RuntimeError(
            f"Failed to update histogram bin at indices {tuple(idx)}"
        ) from exc
    return None

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    from django.core.exceptions import ValidationError

    msg_pattern = r"^[A-Za-z0-9_.-]+$"
    key_regex = re.compile(msg_pattern)
    value_regex = re.compile(msg_pattern)

    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            try:
                key_str = key.decode() if isinstance(key, bytes) else key
            except Exception:
                errors.append({key: "expected string or bytes-like object"})
                key_str = None
            else:
                if key_str is not None and not key_regex.match(key_str):
                    errors.append(
                        {key_str: f"Label key '{key_str}' does not match the regex [{msg_pattern}]"}
                    )

        # Validate value
        # Value must be string or bytes-like
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            try:
                val_str = value.decode() if isinstance(value, bytes) else value
            except Exception:
                errors.append({value: "expected string or bytes-like object"})
            else:
                if val_str is not None and not value_regex.match(val_str):
                    errors.append(
                        {val_str: f"Label value '{val_str}' does not match the regex [{msg_pattern}]"}
                    )

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    if not isinstance(labels, dict):
        raise ValidationError({"labels": "Expected a dictionary of labels"})

    # Regular expressions for valid keys and values (example patterns)
    key_pattern = re.compile(r'^[A-Za-z0-9._-]+$')
    value_pattern = re.compile(r'^[A-Za-z0-9._-]+$')
    errors = []

    for key, value in labels.items():
        # Check key type
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): 'expected string or bytes-like object'})
        else:
            # Check key regex
            if not key_pattern.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [{key_pattern.pattern}]"})

        # Check value type
        if isinstance(value, (list, tuple)):
            # A list/tuple is considered invalid for a single label value
            errors.append({repr(value): 'expected string or bytes-like object'})
        elif not isinstance(value, (str, bytes)):
            errors.append({repr(value): 'expected string or bytes-like object'})

        # If value is a string/bytes, check its regex
        if isinstance(value, (str, bytes)):
            if not value_pattern.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex [{value_pattern.pattern}]"})

        # If value is a list/tuple, optionally validate each element
        # (not required by original specification but illustrated here)
        if isinstance(value, (list, tuple)):
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    errors.append({repr(elem): 'expected string or bytes-like object'})
                elif not value_pattern.match(elem):
                    errors.append({elem: f"Label value '{elem}' does not match the regex [{value_pattern.pattern}]"})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
