        if isinstance(value, (list, tuple)):
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    _add_value_error(elem, "expected string or bytes-like object")
                else:
                    elem_str = elem.decode() if isinstance(elem, bytes) else elem
                    if val_regex and not val_regex.match(elem_str):
