                if val_regex and not val_regex.match(val_str):
                    _add_value_error(val_str,
                                     f"Label value '{val_str}' does not match the regex {val_regex.pattern}")

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
