def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    The function iterates over the ``observer_schema`` and ensures that
    ``last_applied_manifest`` contains an entry for every schema item.  When
    a nested dictionary or list is encountered, the function calls the
    appropriate helper (``update_last_applied_manifest_dict_from_resp`` for
    dicts and calls itself for lists).  If a value is missing in the
    response, ``None`` is inserted as a placeholder.  The updates are
    performed in place and the updated ``last_applied_manifest`` is returned.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): partial ``observer_schema`` describing the
            expected structure.
        response (list): partial response from the Kubernetes API.

    Returns:
        list: The updated ``last_applied_manifest``.
    """
    # Defensive handling of None inputs
    if last_applied_manifest is None:
        last_applied_manifest = []
    if observer_schema is None:
        observer_schema = []
    if response is None:
        response = []

    # Ensure the list is long enough
    max_len = max(len(observer_schema), len(last_applied_manifest))
    while len(last_applied_manifest) < max_len:
        last_applied_manifest.append(None)

    for i, schema_item in enumerate(observer_schema):
        # Get current item from manifest and corresponding response
        manifest_item = last_applied_manifest[i] if i < len(last_applied_manifest) else None
        resp_item = response[i] if i < len(response) else None

        # If the schema item indicates a nested structure, recurse accordingly
        if isinstance(schema_item, dict):
            # Nested dict
            if isinstance(resp_item, dict):
                if manifest_item is None:
                    manifest_item = {}
                    last_applied_manifest[i] = manifest_item
                nested_schema = schema_item.get('schema')
                if nested_schema is not None:
                    # Use the helper for dicts
                    try:
                        from .helpers import update_last_applied_manifest_dict_from_resp
                    except Exception:
                        # If import fails, fall back to a simple assignment
                        manifest_item.update(resp_item)
                    else:
                        update_last_applied_manifest_dict_from_resp(
                            manifest_item, nested_schema, resp_item
                        )
                else:
                    # No explicit nested schema; perform a shallow merge
                    if isinstance(manifest_item, dict):
                        manifest_item.update(resp_item)
                    else:
                        last_applied_manifest[i] = resp_item
            # Nested list
            elif isinstance(resp_item, list) and schema_item.get('items') is not None:
                if manifest_item is None:
                    manifest_item = []
                    last_applied_manifest[i] = manifest_item
                nested_schema = schema_item.get('items')
                # Extend the list to match the response length
                while len(manifest_item) < len(resp_item):
                    manifest_item.append(None)
                for j, sub_resp in enumerate(resp_item):
                    update_last_applied_manifest_list_from_resp(
                        manifest_item, nested_schema, sub_resp
                    )
        # Primitive value: set if not already present
        else:
            if manifest_item is None and resp_item is not None:
                last_applied_manifest[i] = resp_item

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Defensive checks for required attributes
    if app is None:
        raise ValueError("app cannot be None")
    spec = getattr(app, "spec", None)
    if spec is None:
        raise AttributeError("app has no 'spec' attribute")
    manifest = getattr(spec, "manifest", None)
    if not isinstance(manifest, dict):
        # Nothing to process if manifest is missing or not a dict
        return

    # Ensure there is a place to store observer schemas
    observer_schema_map = getattr(spec, "observer_schema", None)
    if observer_schema_map is None:
        observer_schema_map = {}
        # If spec is a mutable object, set attribute back
        if hasattr(spec, "__dict__"):
            spec.observer_schema = observer_schema_map
    if not isinstance(observer_schema_map, dict):
        # If spec.observer_schema exists but is not a dict, raise to avoid silent bug
        raise TypeError("app.spec.observer_schema must be a dict")

    # Iterate over all resources in manifest
    for res_name, res_def in manifest.items():
        # Skip if a custom observer schema already exists
        if res_name in observer_schema_map:
            continue
        # Create a simple default schema
        # A minimal schema for a Kubernetes resource typically has at least the 'metadata' field
        default_schema = {
            "type": "object",
            "properties": {
                "metadata": {"type": "object"},
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "required": ["metadata"],
        }
        observer_schema_map[res_name] = default_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Guard against missing attributes
    try:
        manifestations = getattr(app.spec, "manifest", None)
    except Exception:
        return {}

    if not isinstance(manifestations, (list, tuple)):
        return {}

    default_schemas = {}

    def _placeholder(value):
        """Return a type placeholder based on the Python type of value."""
        if isinstance(value, dict):
            return {k: _placeholder(v) for k, v in value.items()}
        if isinstance(value, list):
            return [ _placeholder(v) for v in value ] or ["string"]
        if isinstance(value, str):
            return "string"
        if isinstance(value, bool):
            return "boolean"
        if isinstance(value, int):
            return "integer"
        if isinstance(value, float):
            return "float"
        # Fallback for unknown types
        return "string"

    for idx, res in enumerate(manifestations or []):
        if not isinstance(res, dict):
            continue

        # Skip resources that already define a custom observer schema
        custom_schema = res.get("spec", {}).get("observer_schema")
        if custom_schema:
            continue

        kind = res.get("kind", f"Unknown_{idx}")
        name = res.get("metadata", {}).get("name")
        identifier = f"{kind}:{name}" if name else kind

        default_schemas[identifier] = _placeholder(res)

    # If the application model has a dedicated attribute for default schemas,
    # store the result there for later use.
    if hasattr(app, "default_observer_schema"):
        setattr(app, "default_observer_schema", default_schemas)

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the manifest from the application's spec, handling missing attributes gracefully.
    try:
        manifest = app.spec.manifest
    except AttributeError as exc:
        raise ValueError("Provided application does not have a 'spec.manifest' attribute.") from exc

    # Ensure the manifest is an iterable of resources. It may be a list or a dict (mapping kind -> list of resources).
    resources = []
    if isinstance(manifest, dict):
        # Map values may be lists of resource dictionaries.
        for value in manifest.values():
            if isinstance(value, list):
                resources.extend(value)
            elif isinstance(value, dict):
                # Single resource per kind
                resources.append(value)
    elif isinstance(manifest, list):
        resources = manifest
    else:
        raise ValueError(f"Unsupported manifest type: {type(manifest).__name__}")

    for resource in resources:
        if not isinstance(resource, dict):
            # Skip non-dictionary entries
            continue

        # If a custom observer schema is already defined, skip generation.
        if "observer_schema" in resource:
            continue

        # Construct a minimal default observer schema. The schema will watch the resource's
        # name (if provided) and its status object. This is a placeholder and can be customized
        # later by the user or by other parts of the system.
        metadata = resource.get("metadata", {})
        name = metadata.get("name")
        default_schema = {}

        if name is not None:
            default_schema["metadata"] = {"name": name}
        else:
            default_schema["metadata"] = {}

        # Include a status field in the schema so that observers monitor changes to the
        # resource status. The exact structure of the status can be expanded later.
        default_schema["status"] = {}

        # Attach the generated schema to the resource dictionary.
        resource["observer_schema"] = default_schema

    # Return the modified application instance for chaining or further processing.
    return app

