def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False

        # Ensure the path exists and is a directory
        if not os.path.isdir(path):
            return False

        # Immutable component: the .ocfl-version file must exist
        version_file = os.path.join(path, ".ocfl-version")
        if not os.path.isfile(version_file):
            return False

        # Basic sanity check: the container should contain at least
        # one object directory with a last modification time file
        object_dirs = [d for d in os.listdir(path)
                       if os.path.isdir(os.path.join(path, d))
                       and d != ".metadata" and d != ".ocfl-version"]
        if not object_dirs:
            return False

        # Optional: check metadata directory presence
        mgmt_dir = os.path.join(path, ".metadata")
        if os.path.isdir(mgmt_dir):
            # metadata directory should contain at least a file
            if not any(os.path.isfile(os.path.join(mgmt_dir, f)) for f in os.listdir(mgmt_dir)):
                return False

        return True
    except Exception:
        return False

