            if logs is None:
                return f"{prefix}No validation log available."
            if not isinstance(logs, (list, tuple)):
                return f"{prefix}Invalid log data."
            lines = []
            for idx, entry in enumerate(logs, 1):
                if isinstance(entry, dict):
                    msg = entry.get('message', str(entry))
                else:
