        # Extract spec version if requested
        if extract_spec_version:
            spec_type = inventory.get('type')
            if spec_type is not None:
                try:
                    # _version_from_type should return the spec_version string
                    self.spec_version = self._version_from_type(spec_type)
                except Exception:
                    # Invalid type, keep current spec_version
                    pass

        # Prepare for validation
        errors = []

        # Example: check required fields (customizable via self.required_fields)
        required_fields = getattr(self, "required_fields", [])
        for field in required_fields:
            if field not in inventory:
                errors.append(f"Missing required field '{field}'")

        # Example: type checks (customizable via self.field_types)
        expected_types = getattr(self, "field_types", {})
        for field, expected_type in expected_types.items():
            if field in inventory:
                if isinstance(expected_type, tuple):
                    if not isinstance(inventory[field], expected_type):
                        types_str = ", ".join(t.__name__ for t in expected_type)
                        errors.append(f"Field '{field}' has wrong type. Expected one of {types_str}")
                else:
                    if not isinstance(inventory[field], expected_type):
                        errors.append(f"Field '{field}' has wrong type. Expected {expected_type.__name__}")

        if errors:
            raise ValueError("Inventory validation errors: " + "; ".join(errors))
        # If we reach here, validation succeeded
        return True

def validate(self, inventory, extract_spec_version=False):
