                # Prefer a helper if available.
                infer_method = getattr(self, "_determine_spec_version", None)
                if callable(infer_method):
                    spec_version = infer_method(type_value)
                else:
                    # Fallback: if the type is a simple string like "v1", "v2", etc.
                    if isinstance(type_value, str) and type_value.lower().startswith("v"):
                        spec_version = int(type_value[1:])
                    else:
                        raise ValueError("Cannot infer spec version from type")
            except Exception:
                # If we cannot determine a version, fall back to the default.
                spec_version = self.spec_version

    # Run the actual validation logic, which may involve schema checks,
    # custom predicates, or other tests that depend on `spec_version`.
    # The implementation below is generic and may be overridden by subclasses
    # to provide the specific validation behavior needed.

    # Example placeholder: if a schema validator is available.
    validator = getattr(self, "_schema_validator", None)
    if validator is None:
        # If no validator is defined, assume validation passes.
        return True

    try:
        validator.validate(inventory, spec_version=spec_version)
    except Exception as exc:
        # Wrap any validation error into a consistent exception type.
        raise ValueError(f"Inventory validation failed for spec version {spec_version}") from exc

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used.

    Raises:
        ValueError: If any digest declared in ``manifest_files`` is not present
        in ``digests_used`` or if any digest is missing from the internal
        record of known digests.
    """
    # Convert both parameters to sets for efficient set operations.
    try:
        manifest_set = set(manifest_files)
    except Exception:
        raise TypeError("manifest_files must be an iterable of digests")

    try:
        used_set = set(digests_used)
    except Exception:
        raise TypeError("digests_used must be an iterable of digests")

    # Digests that are required by the manifest but missing from the used set.
    missing = manifest_set - used_set

    if missing:
        raise ValueError(
            f"The following digests are required by the manifest "
            f"but were not used: {sorted(missing)}"
        )

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if prior is None:
        return
    if not isinstance(prior, self.__class__):
        raise TypeError(
            f'prior must be an instance of {self.__class__.__name__}, got {type(prior)}'
        )

    # Check that prior species and parameters are subsets of current inventory
    prior_species = set(prior.species)
    current_species = set(self.species)
    missing_species = prior_species - current_species
    if missing_species:
        raise ValueError(
            f'Current inventory is missing species from prior: {missing_species}'
        )

    prior_params = set(prior.parameters)
    current_params = set(self.parameters)
    missing_params = prior_params - current_params
    if missing_params:
        raise ValueError(
            f'Current inventory is missing parameters from prior: {missing_params}'
        )

    # Ensure current inventory contains at least the same number of reactions
    if len(self.propensities) < len(prior.propensities):
        raise ValueError(
            'Current inventory has fewer reactions than prior '
            f'({len(self.propensities)} vs {len(prior.propensities)})'
        )

    # Verify that each reaction in the prior matches the corresponding one
    # in the current inventory (by position).  Additional reactions are
    # permitted, but existing ones must remain unchanged.
    for idx, prior_prop in enumerate(prior.propensities):
        curr_prop = self.propensities[idx]
        if curr_prop != prior_prop:
            raise ValueError(
                f'Reaction at index {idx} changed from {prior_prop} to {curr_prop}'
            )

    # Basic checks on the stoichiometry matrices
    if self.stoichiometry_matrix.rows != len(self.species):
        raise ValueError(
            f'Stoichiometry matrix rows {self.stoichiometry_matrix.rows} '
            f'don\'t match number of species {len(self.species)}'
        )
    if prior.stoichiometry_matrix.rows != len(prior.species):
        raise ValueError(
            f'Prior stoichiometry matrix rows {prior.stoichiometry_matrix.rows} '
            f'don\'t match number of prior species {len(prior.species)}'
        )
    if self.stoichiometry_matrix.cols < prior.stoichiometry_matrix.cols:
        raise ValueError(
            'Current inventory has fewer reaction columns than prior: '
            f'{self.stoichiometry_matrix.cols} vs {prior.stoichiometry_matrix.cols}'
        )

    # Map species indices to compare stoichiometry values for common species
    current_index = {s: i for i, s in enumerate(self.species)}
    prior_index = {s: i for i, s in enumerate(prior.species)}

    # Compare every species that existed in the prior; reactions may be added.
    for p_spec, p_row in prior_index.items():
        c_row = current_index[p_spec]
        for j in range(prior.stoichiometry_matrix.cols):
            prior_val = prior.stoichiometry_matrix[p_row, j]
            # Missing columns in the current matrix are treated as zero
            curr_val = (
                self.stoichiometry_matrix[c_row, j]
                if j < self.stoichiometry_matrix.cols
                else 0
            )
            if prior_val != curr_val:
                raise ValueError(
                    f'Stoichiometry mismatch for species {p_spec} '
                    f'and reaction column {j}: {prior_val} vs {curr_val}'
                )

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same concrete type as self
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"Expected prior to be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # Both objects must expose a comparable 'version' attribute
    if not hasattr(self, "version"):
        raise AttributeError("Current inventory object lacks a 'version' attribute")
    if not hasattr(prior, "version"):
        raise AttributeError("Prior inventory object lacks a 'version' attribute")

    self_version = getattr(self, "version")
    prior_version = getattr(prior, "version")
    try:
        if prior_version >= self_version:
            raise ValueError(
                f"Prior version {prior_version!r} must be strictly less than "
                f"current version {self_version!r}"
            )
    except TypeError as exc:
        raise TypeError(
            f"Cannot compare version types (self: {type(self_version)}, prior: {type(prior_version)})"
        ) from exc

    # Optional consistency checks: ensure that any iterable attributes defined in prior
    # are subsets of those in self. This allows a prior to have fewer species, parameters,
    # propensities, etc., but not introduce new ones.
    iterable_attrs = ("species", "parameters", "propensities", "stoichiometry_matrix")
    for attr in iterable_attrs:
        if hasattr(self, attr) and hasattr(prior, attr):
            self_obj = getattr(self, attr)
            prior_obj = getattr(prior, attr)
            try:
                self_set = set(self_obj)
                prior_set = set(prior_obj)
            except TypeError:
                # non-iterable attributes are ignored
                continue
            if not prior_set.issubset(self_set):
                missing = prior_set - self_set
                raise ValueError(
                    f"Prior {attr} contains items not present in current inventory: {missing}"
                )

    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure the argument is an InventoryValidator (or at least has the right interface)
    if not hasattr(prior, "validate_as_prior_version"):
        raise TypeError("prior must be an InventoryValidator instance")

    # Version comparison: a prior must be older than the current
    self_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if self_version is None or prior_version is None:
        raise AttributeError("Both InventoryValidator objects must expose a 'version' attribute")

    if prior_version >= self_version:
        raise ValueError(f"Prior inventory version ({prior_version}) "
                         f"must be less than current inventory version ({self_version})")

    # Get inventory collections from both objects, trying common names
    def _get_inventory(obj):
        for name in ("inventory", "items", "data"):
            if hasattr(obj, name):
                return getattr(obj, name)
        raise AttributeError("InventoryValidator object lacks a recognised inventory attribute")

    curr_items = _get_inventory(self)
    prior_items = _get_inventory(prior)

    # Normalize to sets of keys (identifiers)
    def _to_key_set(collection):
        if isinstance(collection, dict):
            return set(collection.keys())
        try:
            return set(collection)
        except TypeError:
            # Fallback: use the string representation of each element
            return {str(item) for item in collection}

    curr_keys = _to_key_set(curr_items)
    prior_keys = _to_key_set(prior_items)

    # Prior items must be a subset of current items
    if not prior_keys.issubset(curr_keys):
        missing = prior_keys - curr_keys
        raise ValueError(f"Prior inventory contains items not present in the current inventory: {missing}")

    # On success, nothing is returned (None)
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type as self
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"Expected prior to be of type {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # Check that the inventories belong to the same underlying entity
    inventory_id_self = getattr(self, "inventory_id", None)
    inventory_id_prior = getattr(prior, "inventory_id", None)
    if inventory_id_self is None or inventory_id_prior is None:
        raise ValueError(
            "Both current and prior inventory objects must have an 'inventory_id' attribute"
        )
    if inventory_id_self != inventory_id_prior:
        raise ValueError(
            "Inventory IDs do not match; prior is not a prior version of this inventory"
        )

    # Check that the prior's version is older than the current inventory's version
    version_self = getattr(self, "version", None)
    version_prior = getattr(prior, "version", None)

    if version_self is None or version_prior is None:
        # Fallback: try to use timestamps if available
        timestamp_self = getattr(self, "created_at", None) or getattr(self, "timestamp", None)
        timestamp_prior = getattr(prior, "created_at", None) or getattr(prior, "timestamp", None)
        if timestamp_self is None or timestamp_prior is None:
            raise ValueError(
                "Unable to compare versions: missing 'version' or timestamp attributes on one or both inventories"
            )
        if timestamp_prior >= timestamp_self:
            raise ValueError(
                "Prior inventory's timestamp is not older than the current inventory's timestamp"
            )
        # If timestamps are comparable, consider the check passed
        return

    try:
        # If versions are not directly comparable, raise
        if not isinstance(version_self, (int, float)) or not isinstance(version_prior, (int, float)):
            raise TypeError
        if version_prior >= version_self:
            raise ValueError(
                f"Prior inventory has version {version_prior} which is not older than current inventory's version {version_self}"
            )
    except Exception as exc:
        # In case of unexpected types or comparison errors
        raise ValueError(
            f"Unable to compare inventory versions: {exc}"
        )
    # If we reach here, the prior version validation succeeded
    return

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping logical paths to version mappings")
    # Normalise the target version for comparison
    if isinstance(version, str) and version.lower() == "latest":
        target_version = None
    else:
        try:
            target_version = float(version) if isinstance(version, (int, float)) else float(version)
        except Exception:  # pragma: no cover
            raise ValueError("version must be convertible to a float or the string \"latest\"")
    result = {}
    # Pre‑compute the maximum version if needed
    if target_version is None:
        max_version = None
        for ver_map in inventory.values():
            if isinstance(ver_map, dict):
                for ver_key in ver_map:
                    try:
                        ver_num = float(ver_key) if isinstance(ver_key, (int, float)) else float(ver_key)
                    except Exception:
                        continue
                    if max_version is None or ver_num > max_version:
                        max_version = ver_num
            elif hasattr(ver_map, "__iter__"):
                for pair in ver_map:
                    try:
                        ver_key, _ = pair
                        ver_num = float(ver_key) if isinstance(ver_key, (int, float)) else float(ver_key)
                    except Exception:
                        continue
                    if max_version is None or ver_num > max_version:
                        max_version = ver_num
        target_version = max_version
    # Iterate over the logical paths
    for logical_path, ver_map in inventory.items():
        if not logical_path:
            continue
        fileset = set()
        if isinstance(ver_map, dict):
            items = ver_map.items()
        elif hasattr(ver_map, "__iter__"):
            items = ver_map
        else:
            continue
        for ver_key, content_file in items:
            try:
                ver_num = float(ver_key) if isinstance(ver_key, (int, float)) else float(ver_key)
            except Exception:
                continue
            # Include files that belong to the requested version or later
            if ver_num >= target_version:
                fileset.add(content_file)
        if fileset:
            result[logical_path] = fileset
    return result

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    result = {}
    for logical_path, entries in inventory.items():
        try:
            iterable = entries
            if not hasattr(iterable, "__iter__"):
                continue
        except Exception:
            continue
        content_files = set()
        for entry in iterable:
            # determine version and files for this entry
            entry_version = None
            entry_files = None
            if isinstance(entry, dict):
                entry_version = entry.get("version") or entry.get("ver")
                entry_files = (entry.get("content_files") or
                               entry.get("files") or
                               entry.get("file") or
                               entry.get("content"))
            elif isinstance(entry, (list, tuple)):
                if len(entry) == 2:
                    entry_version, entry_files = entry
                elif len(entry) == 3:
                    entry_version = entry[0]
                    entry_files = entry[2]
                else:
                    continue
            else:
                continue
            if entry_version != version:
                continue
            if isinstance(entry_files, str):
                entry_files = [entry_files]
            if isinstance(entry_files, (list, tuple)):
                for f in entry_files:
                    if f:
                        content_files.add(f)
            elif entry_files is not None:
                content_files.add(entry_files)
        if content_files:
            result[logical_path] = content_files
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("Inventory cannot be None")

    # Helper to decide if a top‑level key looks like a version number
    def _looks_like_version(key):
        if isinstance(key, (int, float)):
            return True
        if isinstance(key, str):
            try:
                float(key)
                return True
            except ValueError:
                pass
            if '.' in key:
                parts = key.split('.')
                return all(p.isdigit() for p in parts if p)
        return False

    # Determine the inventory structure
    top_is_version = any(_looks_like_version(k) for k in inventory.keys())

    result = {}

    if top_is_version:
        # inventory is {version: {logical_path: files}}
        for inv_ver, mapping in inventory.items():
            if not isinstance(mapping, dict):
                continue
            if str(inv_ver) == str(version) or str(inv_ver) > str(version):
                for logical_path, files in mapping.items():
                    files_set = result.setdefault(logical_path, set())
                    if isinstance(files, (list, set, tuple)):
                        files_set.update(files)
                    else:
                        files_set.add(files)
    else:
        # inventory is {logical_path: {version: files}}
        for logical_path, ver_map in inventory.items():
            if not isinstance(ver_map, dict):
                continue
            files_set = set()
            for ver, files in ver_map.items():
                if str(ver) == str(version) or str(ver) > str(version):
                    if isinstance(files, (list, set, tuple)):
                        files_set.update(files)
                    else:
                        files_set.add(files)
            result[logical_path] = files_set

    return result

