    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Algorithm key
    if "algorithm" not in fixity:
        raise ValueError("Missing 'algorithm' key in fixity block")
    if not isinstance(fixity["algorithm"], str) or not fixity["algorithm"].strip():
        raise ValueError("'algorithm' must be a non-empty string")

    # Values key
    if "values" not in fixity:
        raise ValueError("Missing 'values' key in fixity block")
    values = fixity["values"]
    if not isinstance(values, dict):
        raise ValueError("'values' must be a dictionary mapping file names to checksums")

    # Ensure files referenced in the fixity block are in the manifest
    manifest_set = set(manifest_files)
    for fname, checksum in values.items():
        if fname not in manifest_set:
            raise ValueError(f"Fixity block references unknown file: '{fname}'")
        if not isinstance(checksum, str) or not checksum.strip():
            raise ValueError(f"Invalid checksum for file: '{fname}'")

    # (Optional) Warn if any manifest file has no checksum entry
    missing = manifest_set - values.keys()
    if missing:
        # It's not strictly an error, but we can log a warning or raise a ValueError
        # depending on desired strictness. Here we just return True.
        pass

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be a list, tuple or set")

    manifest_set = set(manifest_files)

    missing_files = []
    for file_path, checks in fixity.items():
        # Ensure that the referenced file is present in the manifest
        if file_path not in manifest_set:
            missing_files.append(file_path)

        # The fixity entry for each file should be a dictionary of hash algo -> value
        if not isinstance(checks, dict):
            raise ValueError(f"Fixity entry for '{file_path}' must be a dictionary of hash algorithms")

        for algo, hash_val in checks.items():
            if not isinstance(algo, str):
                raise ValueError(f"Hash algorithm name for '{file_path}' must be a string, got {type(algo).__name__}")
            if not isinstance(hash_val, str):
                raise ValueError(f"Hash value for algorithm '{algo}' in '{file_path}' must be a string, got {type(hash_val).__name__}")

    if missing_files:
        raise ValueError(f"Fixity references files not in manifest: {', '.join(missing_files)}")

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
