        if not isinstance(fixity, dict):
            raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")
        # manifest_files can be any iterable of paths; derive a set for quick lookup
        if not hasattr(manifest_files, "__iter__"):
            raise ValueError(f"manifest_files must be iterable, got {type(manifest_files).__name__}")
        manifest_set = set(manifest_files)

        # Empty fixity is considered valid
        if not fixity:
            return True

        # Validate each entry
        for file_path, checksum in fixity.items():
            if file_path not in manifest_set:
                raise ValueError(f"File '{file_path}' in fixity block not present in manifest")
            if not isinstance(checksum, str) or not checksum:
                raise ValueError(f"Checksum for file '{file_path}' must be a non-empty string")
