def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic input type checks
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dict, got %r" % type(fixity).__name__)

    if not isinstance(manifest_files, (list, tuple, set)):
        raise ValueError("manifest_files must be an iterable of file identifiers")

    # Ensure required key exists
    if 'files' not in fixity:
        raise ValueError("fixity block missing required 'files' key")

    files = fixity['files']

    # The 'files' entry should be an iterable
    if not hasattr(files, '__iter__') or isinstance(files, (str, bytes)):
        raise ValueError("'files' entry must be an iterable of file identifiers, got %r" % type(files).__name__)

    # Convert manifest to a set for efficient lookup
    manifest_set = set(manifest_files)

    # Validate each referenced file
    for f in files:
        if not isinstance(f, (str, bytes)):
            raise ValueError("fixity file identifiers must be strings or bytes, got %r" % type(f).__name__)
        if f not in manifest_set:
            raise ValueError("File '%s' referenced in fixity is not present in the manifest" % f)

    # Optional: ensure no duplicate references
    if len(files) != len(set(files)):
        raise ValueError("Duplicate file references found in fixity block")

    # All checks passed
    return True

def files_list(path):
    """Return the files in `path`"""

    import os

    if not os.path.exists(path):
        raise FileNotFoundError(path)

    abs_path = os.path.abspath(path)

    if os.path.isfile(abs_path) or os.path.islink(abs_path):
        return [abs_path]

    if os.path.isdir(abs_path):
        files = []
        for root, _, filenames in os.walk(abs_path, topdown=True):
            for fname in filenames:
                files.append(os.path.join(root, fname))
        return files

    # In case the path is something else (e.g., a device), treat as a file
    return [abs_path]

