def files_list(path):
    """
    Return the files in `path`.

    If `path` is a file, returns a list containing its absolute path. If `path`
    is a directory, returns a list of absolute paths for all files contained
    within the directory, recursively. Raises :class:`FileNotFoundError` if
    `path` does not exist.
    """
    import os

    # Resolve to absolute path early
    try:
        abs_path = os.path.abspath(path)
    except (TypeError, OSError) as e:
        raise FileNotFoundError(f"Invalid path: {path}") from e

    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"Path does not exist: {abs_path}")

    if os.path.isfile(abs_path):
        return [abs_path]

    if os.path.isdir(abs_path):
        files = []
        for root, _dirs, filenames in os.walk(abs_path):
            for name in filenames:
