def select_filenames_by_prefix(prefix, files):
    """
    Get files which belongs to a document package.

    Retorna os arquivos da lista `files` cujos nomes iniciam com `prefix`

    Parameters
    ----------
    prefix : str
        Filename prefix
    files : str list
        Files paths

    Returns
    -------
    list
        files paths which basename files matches to prefix
    """
    # Ensure prefix is a string
    try:
        if not isinstance(prefix, str):
            prefix = str(prefix)
    except Exception:
        prefix = ''

    # Normalize files to an iterable list
    try:
        if isinstance(files, str):
            files_iter = [files]
        else:
            files_iter = list(files)
    except Exception:
        # If files is not iterable, return empty list
        return []

    matched = []
    for path in files_iter:
        try:
            base = os.path.basename(path)
            if base.startswith(prefix):
                matched.append(path)
        except Exception:
            # Skip entries that cause errors
            continue

    return matched

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")

    if not os.path.isdir(folder):
        raise ValueError(f"Provided path '{folder}' is not a directory or does not exist")

    packages = {}

    # First pass: locate all XML files to identify package basenames
    try:
        for root, _, files in os.walk(folder):
            for filename in files:
                if filename.lower().endswith('.xml'):
                    base = os.path.splitext(filename)[0]
                    xml_path = os.path.join(root, filename)
                    packages[base] = {'xml': xml_path, 'files': []}
    except OSError as e:
        raise RuntimeError(f"Error accessing files in '{folder}': {e}") from e

    # Second pass: gather all files that share the XML basename
    if not packages:
        return packages  # No XML files found

    try:
        xml_basenames = set(packages.keys())
        for root, _, files in os.walk(folder):
            for filename in files:
                base = os.path.splitext(filename)[0]
                if base in xml_basenames:
                    packages[base]['files'].append(os.path.join(root, filename))
    except OSError as e:
        raise RuntimeError(f"Error accessing files in '{folder}': {e}") from e

    return packages

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
