    return packages if packages else {}

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
        Mapping from the XML base name to a list of file paths that share that base.
    """
    import os

    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string path, got {type(folder)!r}")

    if not os.path.isdir(folder):
        raise ValueError(f"Provided folder path '{folder}' does not exist or is not a directory")

    packages = {}

    # Scan all entries in the directory and identify XML files
    try:
        entries = os.listdir(folder)
    except OSError as exc:
        raise RuntimeError(f"Unable to read directory '{folder}': {exc}") from exc

    # Find all XML files and map their base names to the full path
    xml_bases = {}
    for name in entries:
        path = os.path.join(folder, name)
        if not os.path.isfile(path):
            continue
        base, ext = os.path.splitext(name)
        if ext.lower() == ".xml":
            xml_bases[base] = path

    # For each XML base, group all files sharing that base
    for base, xml_path in xml_bases.items():
        files = []
        for name in entries:
            path = os.path.join(folder, name)
            if not os.path.isfile(path):
                continue
            file_base, _ = os.path.splitext(name)
            if file_base == base:
                files.append(path)
        packages[base] = files

    return packages

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo

    Returns
    -------
    dict
        Um dicionário contendo a chave `prefix` e um subdicionário com as
        chaves `type`, `address` e opcionalmente `missing`.
    """
    # Validação de tipos de entrada
    if not isinstance(prefix, str):
        raise TypeError("prefix deve ser uma string")
    if not isinstance(file_path, str):
        raise TypeError("file_path deve ser uma string")

    result = {}

    # Determina a extensão do arquivo
    try:
        _, ext = os.path.splitext(file_path)
    except Exception as e:
        raise ValueError(f"Erro ao extrair a extensão do arquivo '{file_path}': {e}")

    ext = ext.lower()
    asset_exts = {
        ".mp3", ".wav", ".mp4", ".mov", ".m4a", ".aac", ".flac",
        ".jpg", ".jpeg", ".png", ".gif", ".bmp", ".tiff",
    }
    rendition_exts = {".srt", ".ass", ".vtt", ".txt", ".xml", ".json"}

    # Algoritmo simples de heurística para determinar o tipo
    if ext in asset_exts:
        ftype = "asset"
    elif ext in rendition_exts or "rend" in prefix.lower():
        ftype = "rendition"
    else:
        # Quando não há informação suficiente, assumir asset
        ftype = "asset"

    # Checa existência do arquivo e marca como ausente se necessário
    try:
        if os.path.isfile(file_path):
            result[prefix] = {"type": ftype, "address": file_path}
        else:
            result[prefix] = {"type": ftype, "address": file_path, "missing": True}
    except Exception as e:
        # Caso ocorra exceção no caminho, sinaliza
        result[prefix] = {"type": ftype, "address": file_path, "error": str(e)}

    return result

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to another dict containing each file
        path (relative to the archive) as key and its content as bytes.
    """
    import os
    import zipfile

    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue
                # Read file content
                try:
                    data = zin.read(zinfo)
                except Exception as exc:
                    # Skip unreadable entries but allow processing to continue
                    continue

                # Determine XML basename (if present)
                base_name = None
                filename = os.path.basename(zinfo.filename)
                name_part, ext = os.path.splitext(filename)
                if ext.lower() == ".xml":
                    base_name = name_part

                if base_name is not None:
                    # Group under the base_name
                    if base_name not in packages:
                        packages[base_name] = {}
                    packages[base_name][zinfo.filename] = data
                else:
                    # Attempt to associate non-XML file with an existing package
                    # based on the directory structure: if the file shares the same
                    # directory prefix, assign it to the first matching package if any.
                    dir_prefix = os.path.dirname(zinfo.filename)
                    matched = None
                    for pkg in packages:
                        if dir_prefix.startswith(pkg):
                            matched = pkg
                            break
                    if matched:
                        packages[matched][zinfo.filename] = data

    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from exc
    except Exception as exc:
        # Catch any other runtime errors that might occur during processing
        raise RuntimeError(f"Error while exploring zip file '{zip_path}': {exc}") from exc

    return packages

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Find all XML basenames inside the archive
            xml_basenames = set()
            for entry in zf.infolist():
                if entry.is_dir():
                    continue
                name = os.path.basename(entry.filename)
                if name.lower().endswith(".xml"):
                    xml_basenames.add(os.path.splitext(name)[0])

            # Group files that share an XML basename
            for entry in zf.infolist():
                if entry.is_dir():
                    continue
                name = os.path.basename(entry.filename)
                basename = os.path.splitext(name)[0]
                if basename in xml_basenames:
                    # Initialize the group if necessary
                    if basename not in packages:
                        packages[basename] = {}
                    # Read the raw bytes of the file
                    try:
                        content = zf.read(entry)
                    except Exception:
                        content = None
                    # Store using the full relative filename to preserve directory info
                    packages[basename][entry.filename] = content
    except FileNotFoundError:
        # If the zip file does not exist, return an empty dict
        return {}
    except zipfile.BadZipFile:
        # If the file is not a valid zip archive, return an empty dict
        return {}
    except Exception:
        # Any other unexpected error results in an empty dict
        return {}

    return packages

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str) or not zip_path:
        return {}

    result = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Build a mapping of directory to all file entries in that directory
            dir_map = {}
            for entry in zf.infolist():
                if entry.is_dir():
                    continue
                dir_path = os.path.dirname(entry.filename)
                dir_map.setdefault(dir_path, []).append(entry)

            # For each directory, find XML files and group all files in that directory
            for dir_path, entries in dir_map.items():
                xml_entries = [e for e in entries if e.filename.lower().endswith('.xml')]
                for xml_entry in xml_entries:
                    base_name = os.path.splitext(os.path.basename(xml_entry.filename))[0]
                    group = {}
                    for e in entries:
                        file_name = os.path.basename(e.filename)
                        try:
                            data = zf.read(e)
                        except Exception:
                            # If reading a single file fails, continue with others
                            data = None
                        group[file_name] = data
                    result[base_name] = group
    except (FileNotFoundError, zipfile.BadZipFile, OSError) as exc:
        # For invalid paths or corrupted ZIP, return empty dict
        return {}
    return result

def files_list_from_zipfile(zip_path):
