    if not zip_path:
        return []
    try:
        import zipfile
        # If zip_path is already a ZipFile object, use it directly
        if isinstance(zip_path, zipfile.ZipFile):
            zf = zip_path
            close = False
        else:
            zf = zipfile.ZipFile(zip_path, "r")
            close = True
        try:
            # Get all names, excluding directories (those ending with '/')
            names = [name for name in zf.namelist() if not name.endswith('/')]
            return names
        finally:
            if close:
                zf.close()
    except Exception:
        # In case of any error (e.g., file not found, not a zip), return empty list
        return []

