            iter(pubdate_xpaths)
            xpaths = pubdate_xpaths
        except TypeError:
            xpaths = [pubdate_xpaths]
    for xpath in xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            continue
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extract from the content of an <issue> element the numeric part and the supplemental part.

    Parameters
    ----------
    issue : str or element-like
        Either a string containing the issue content or an object that exposes a `.text` attribute.

    Returns
    -------
    tuple
        A tuple `(number, supplement)` where each element is either a string or `None`.
        * `number` is the leading numeric portion (e.g., '5', '2-5').
        * `supplement` is the rest of the text after the number, cleaned of surrounding
          whitespace and trailing punctuation. It may contain words such as 'Suppl',
          'spe', or numbers like 'Suppl 1-2'.
    """
    # Get raw text value
    try:
        text = issue.text if hasattr(issue, "text") else str(issue)
    except Exception:
        # In case of unexpected object that does not provide .text or cannot be cast to str
        return (None, None)

    if not isinstance(text, str):
        # Unexpected type, cannot process
        return (None, None)

    text = text.strip()
    if not text:
        return (None, None)

    # Helper to clean trailing punctuation
    def _clean_section(s: str) -> str:
        return s.rstrip(".,") if isinstance(s, str) else ""

    # Regex to find leading number (digit or range like 2-5)
    try:
        import re

        match = re.match(r"^\s*(?P<number>\d+(?:-\d+)?)\s*(?P<rest>.*)$", text, re.IGNORECASE)
    except Exception:
        # If regex fails for some reason, treat entire string as supplement
        return (None, _clean_section(text))

    if match:
        number = match.group("number")
        rest = match.group("rest").strip()
        rest_clean = _clean_section(rest).strip()
        supplement = rest_clean if rest_clean else None
        return (number, supplement)
    else:
        # No leading number detected
        supplement = _clean_section(text).strip()
        return (None, supplement if supplement else None)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Validate indent argument
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")

    # Try to obtain a suitable string representation
    try:
        representation = str(self)
    except Exception:
        # Fallback to repr if str fails
        representation = repr(self)

    # Apply indentation to each line if requested
    if indent > 0:
        ind = " " * indent
        representation = "\n".join(ind + line for line in representation.splitlines())

    # If debug mode is requested, add type information
    if debug:
        try:
            type_info = f"<type: {type(self).__qualname__} at {hex(id(self))}>"
            representation = f"{representation}\n{type_info}"
        except Exception:
            # Ignore any errors while adding debug info
            pass

    return representation

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    try:
        from pprint import pformat
    except Exception:
        pformat = lambda obj, *args, **kwargs: str(obj)

    indent_str = " " * indent
    lines = []

    # Class name and optional debug info
    cls_name = getattr(self, "__class__", type(self)).__name__
    if debug:
        info = f" (id={id(self)}, hash={hash(self)})"
    else:
        info = ""
    lines.append(f"{indent_str}{cls_name}{info}")

    # Collect attributes
    attrs = {}
    try:
        if hasattr(self, "__dict__"):
            attrs = dict(self.__dict__)  # shallow copy
        else:
            # Fallback: gather public attributes
            for attr in dir(self):
                if attr.startswith("_"):
                    continue
                try:
                    attrs[attr] = getattr(self, attr)
                except Exception:
                    attrs[attr] = "<error>"
    except Exception:
        attrs = {}

    if attrs:
        try:
            formatted = pformat(attrs, indent=4, width=80)
        except Exception:
            formatted = str(attrs)
        # Align indentation for multiline dict
        formatted_lines = formatted.splitlines()
        indented_formatted = []
        for i, line in enumerate(formatted_lines):
            if i == 0:
                indented_formatted.append(line)
            else:
                indented_formatted.append(f"{indent_str}    {line}")
        attr_text = "\n".join(indented_formatted)
        lines.append(f"{indent_str}attributes:\n{attr_text}")
    else:
        lines.append(f"{indent_str}attributes: {{}}")

    return "\n".join(lines)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    import inspect
    visited = set()

    def _recurse(obj, depth):
        obj_id = id(obj)
        if obj_id in visited:
            return '<recursion>'
        visited.add(obj_id)

        prefix = ' ' * (indent * depth)

        if isinstance(obj, (list, tuple, set)):
            inner = ', '.join(_recurse(v, depth + 1) for v in obj)
            if isinstance(obj, set):
                rep = f'{{{inner}}}'
            else:
                rep = f'[{inner}]'
        elif isinstance(obj, dict):
            inner = ', '.join(f'{repr(k)}: {_recurse(v, depth + 1)}' for k, v in obj.items())
            rep = f'{{{inner}}}'
        elif hasattr(obj, '__dict__') and not inspect.isclass(obj):
            attrs = ', '.join(f'{k}={_recurse(v, depth + 1)}' for k, v in obj.__dict__.items())
            rep = f'{obj.__class__.__name__}({attrs})'
        else:
            rep = repr(obj)

        if debug:
            rep = f'{type(obj).__name__}({rep})'
        return prefix + rep

    return _recurse(self, 0)

