def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Keep track of already visited objects to avoid infinite recursion
    visited = set()

    def _recurse(obj, level):
        try:
            if id(obj) in visited:
                return f'<{type(obj).__name__} cyclic>'
            if isinstance(obj, (int, float, str, bool, type(None))):
                return repr(obj)
            visited.add(id(obj))
            indentation = '  ' * level
            if isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    items.append(f'{indentation}  {repr(k)}: {_recurse(v, level + 1)}')
                return '{\n' + ',\n'.join(items) + f'\n{indentation}}}'
            if isinstance(obj, (list, tuple, set)):
                if isinstance(obj, list):
                    open_sym, close_sym = '[', ']'
                elif isinstance(obj, tuple):
                    open_sym, close_sym = '(', ')'
                else:  # set
                    open_sym, close_sym = '{', '}'
                items = []
                for item in obj:
                    items.append(f'{indentation}  {_recurse(item, level + 1)}')
                return f'{open_sym}\n' + ',\n'.join(items) + f'\n{indentation}{close_sym}'
            if hasattr(obj, '__dict__'):
                cls_name = type(obj).__name__
                items = []
                for attr, val in vars(obj).items():
                    items.append(f'{indentation}  {attr}={_recurse(val, level + 1)}')
                return f'{cls_name}(\n' + ',\n'.join(items) + f'\n{indentation})'
            # Fallback for objects that don't have __dict__
            return repr(obj)
        except Exception as exc:
            return f'<{type(obj).__name__} error: {exc}>'

    repr_str = _recurse(self, indent)
    if debug:
        repr_str = f'# type: {type(self).__name__}\n' + repr_str
    return repr_str

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper to recursively apply the absorption laws to an expression.
    def _simplify(expr):
        # If the expression doesn't have a func attribute, just return it.
        func = getattr(expr, "func", None)
        if func is None:
            return expr

        # Recursively simplify subexpressions.
        if hasattr(expr, "args"):
            args_sub = tuple(_simplify(a) for a in expr.args)
            try:
                expr = func(*args_sub)
            except Exception:
                expr = func(*expr.args)  # fall back if arguments not accepted

        # Determine the type of expression by its function name.
        name = getattr(expr, "func", None).__name__ if hasattr(expr, "func") else None

        # Apply absorption and negative absorption if possible.
        if name == "And":
            # Look for patterns A & (A | B)
            for sub in expr.args:
                for other in expr.args:
                    if sub is other:
                        continue
                    if getattr(other, "func", None).__name__ == "Or" and sub in other.args:
                        return sub

            # Negative absorption: A & (~A | B)  ->  A & B
            for sub in expr.args:
                for other in expr.args:
                    if getattr(other, "func", None).__name__ == "Or" and getattr(sub, "func", None).__name__ == "Not" and getattr(sub, "args", ()).__len__():
                        # sub is of the form Not(A); find matching A in other.args
                        negated = getattr(sub, "args", ())[0]
                        if negated in other.args:
                            remaining = next(a for a in other.args if a != negated)
                            return __import__("sympy").And(sub, remaining)
        elif name == "Or":
            # Look for patterns A | (A & B)
            for sub in expr.args:
                for other in expr.args:
                    if sub is other:
                        continue
                    if getattr(other, "func", None).__name__ == "And" and sub in other.args:
                        return sub

            # Negative absorption: A | (~A & B)  ->  A | B
            for sub in expr.args:
                for other in expr.args:
                    if getattr(other, "func", None).__name__ == "And" and getattr(sub, "func", None).__name__ == "Not" and getattr(sub, "args", ()).__len__():
                        negated = getattr(sub, "args", ())[0]
                        if negated in other.args:
                            remaining = next(a for a in other.args if a != negated)
                            return __import__("sympy").Or(sub, remaining)
        return expr

    # Simplify each top‑level argument and return the new list.
    return [_simplify(arg) for arg in args]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Import sympy lazily to avoid unnecessary dependency
    try:
        from sympy import And, Or, Not, simplify, nsimplify
    except Exception:
        # If sympy is not available, just return the original list
        return list(args)

    def _apply_rules(expr):
        """
        Apply absorption and negative absorption rules to a single sympy expression.
        Return a new expression if a rule was applied, otherwise return None.
        """
        # Ensure we work with sympy expression
        if not hasattr(expr, 'is_And') and not hasattr(expr, 'is_Or'):
            return None

        # Handle absorption for And
        if expr.is_And:
            # Check for pattern A & (A | B)
            if len(expr.args) == 2:
                left, right = expr.args
                if right.is_Or and left in right.args:
                    return left
                # Negative absorption: A & (~A | B) -> A & B
                if right.is_Or:
                    not_terms = [arg for arg in right.args if isinstance(arg, Not) and arg.args[0] == left]
                    if not_terms:
                        # Get other terms besides Not(left)
                        other_terms = [arg for arg in right.args if arg != not_terms[0]]
                        if other_terms:
                            # Combine left with the others using And
                            new_args = (left, *other_terms)
                            return And(*new_args).simplify()
                        else:
                            # Exactly A & (~A) becomes False, but we may return LogicalFalse
                            return False
            # Handle nested patterns: e.g., (A & B) & (A | C) => (A & B) simplifies?
            # We can let sympy simplify
            simplified = expr.simplify()
            if simplified != expr:
                return simplified
        # Handle absorption for Or
        if expr.is_Or:
            if len(expr.args) == 2:
                left, right = expr.args
                if right.is_And and left in right.args:
                    return left
                # Negative absorption: A | (~A & B) -> A | B
                if right.is_And:
                    not_terms = [arg for arg in right.args if isinstance(arg, Not) and arg.args[0] == left]
                    if not_terms:
                        other_terms = [arg for arg in right.args if arg != not_terms[0]]
                        if other_terms:
                            new_args = (left, *other_terms)
                            return Or(*new_args).simplify()
                        else:
                            # A | (~A) => True
                            return True
            simplified = expr.simplify()
            if simplified != expr:
                return simplified
        return None

    # Convert args to list if not already
    new_args = list(args)
    changed = True
    while changed:
        changed = False
        updated = []
        for expr in new_args:
            reduced = _apply_rules(expr)
            if reduced is not None:
                updated.append(reduced)
                changed = True
            else:
                updated.append(expr)
        new_args = updated

    # Clean up: replace sympy True/False with Python bool
    cleaned = []
    for expr in new_args:
        if expr == True or expr == False:
            cleaned.append(bool(expr))
        else:
            cleaned.append(expr)

    return cleaned

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate the hook type
    try:
        from typing import TYPE_CHECKING
        if TYPE_CHECKING:
            from .hooks import HookType  # pragma: no cover
    except Exception:
        # If HookType cannot be imported, skip type check
        hook_type = None
    else:
        hook_type = HookType

    if hook_type is not None and not isinstance(hook, hook_type):
        raise TypeError("hook must be an instance of HookType")

    def decorator(func):
        if not callable(func):
            raise TypeError("handler must be a callable")
        try:
            # Register the function with the given hook
            self.register_hook(hook, func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for {hook}") from exc
        return func

    return decorator

