def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("The argument 'namefunc' must be callable")
    try:
        # If the 'unicode' type exists, we are running under Python 2
        unicode
        py2 = True
    except NameError:
        py2 = False

    def wrapped(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if py2:
            # In Python 2, strings are bytes; unicode strings need encoding
            if isinstance(result, str):
                return result
            else:
                return result.encode()
        else:
            return result

    return wrapped

