    default = "unknown"
    potential_paths = ["VERSION", "VERSION.txt", "version.py", "src/version.py", "src/VERSION"]
    for path in potential_paths:
        try:
            with open(path, "r", encoding="utf-8") as f:
                content = f.read().strip()
                if not content:
                    continue
                if path.lower().endswith(".py"):
                    # Find a variable named 'version' (case-insensitive) defined in the file
                    local_vars = {}
                    try:
                        exec(content, {}, local_vars)
                    except Exception:
                        # If exec fails, skip to next path
                        continue
                    for key in ("version", "VERSION", "ver", "Ver"):
                        if key in local_vars:
                            ver = local_vars[key]
