    default = "unknown"
    versions = {}
    try:
        # Python 3.8+: importlib.metadata
        import importlib.metadata as metadata
        for dist in metadata.distributions():
            name = dist.metadata.get("Name") or dist.metadata.get("Package")
            if name is None:
                # fallback: derive name from module path
                name = dist.locate_file("").parts[0] if dist.locate_file else "unknown"
            versions[name] = dist.version
        if versions:
            return versions
    except Exception:
        pass

    try:
        # Backward compatible pkg_resources
        import pkg_resources
        for dist in pkg_resources.working_set:
            versions[dist.project_name] = dist.version
        if versions:
            return versions
    except Exception:
        pass

    # If we reach here no version info was gathered
    return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate inputs
    if pieces is None:
        raise TypeError("`pieces` cannot be None")
    if style is None:
        style = "space"

    # Accept a custom callable for the style
    if callable(style):
        try:
            return style(pieces)
        except Exception as exc:  # pragma: no cover
            raise RuntimeError(f"Custom style callable failed: {exc}") from exc

    # Ensure pieces is iterable
    try:
        iterator = iter(pieces)
    except TypeError as exc:  # pragma: no cover
        raise TypeError("`pieces` must be an iterable") from exc

    pieces = list(iterator)
    if not pieces:
        return ""

    # Define common rendering strategies
    key = str(style).strip().lower()
    if key in {"full", "raw"}:
        separator = ""
    elif key in {"comma", "list"}:
        separator = ", "
    elif key in {"brackets", "bracket"}:
        inner = ", ".join(str(p) for p in pieces)
        return f"[{inner}]"
    elif key in {"space", "word"}:
        separator = " "
