        raise RuntimeError(f"Failed to render pieces: {exc}") from exc

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate input types
    if not isinstance(pieces, (list, tuple)):
        raise TypeError('pieces must be a list or tuple')
    if not isinstance(style, str):
        raise TypeError('style must be a string')
    # Normalise style name
    style = style.strip().lower()
    # Convert to list for repeated iteration
    try:
        pieces_list = list(pieces)
    except Exception as exc:
        raise ValueError('pieces must be an iterable') from exc
    # Render according to style
    if style == 'text':
        # Plain text joined by newlines
        return '\n'.join(str(p) for p in pieces_list)
    if style == 'compact':
        # Compact text joined by spaces
        return ' '.join(str(p) for p in pieces_list)
    if style == 'json':
        import json
        return json.dumps(pieces_list)
    if style == 'yaml':
        try:
            import yaml
            return yaml.safe_dump(pieces_list, default_flow_style=False)
        except Exception:
            # Fallback to JSON if PyYAML unavailable
            import json
            return json.dumps(pieces_list)
    raise ValueError(f'Unknown rendering style: {style}')

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    def _get_piece(index, key, default=''):
        """Retrieve a piece from a list/tuple or mapping."""
        if isinstance(pieces, (list, tuple)):
            return pieces[index] if index < len(pieces) else default
        try:
            return pieces[key]
        except (TypeError, KeyError):
            return getattr(pieces, key, default)

    try:
        major = _get_piece(0, 'major', '0')
        minor = _get_piece(1, 'minor', '0')
        patch = _get_piece(2, 'patch', '0')
        prerelease = _get_piece(3, 'prerelease', '')
        build = _get_piece(4, 'build', '')
    except Exception as exc:
        raise ValueError(f"Invalid pieces format: {exc}") from exc

    # Ensure all components are stringified
    major = str(major) if major is not None else '0'
    minor = str(minor) if minor is not None else '0'
    patch = str(patch) if patch is not None else '0'
    prerelease = str(prerelease) if prerelease is not None else ''
    build = str(build) if build is not None else ''

    if style in (None, 'semver'):
        result = f"{major}.{minor}.{patch}"
        if prerelease:
            result += f"-{prerelease}"
        if build:
            result += f"+{build}"
        return result
    elif style == 'compact':
        return f"{major}.{minor}.{patch}"
    elif style == 'full':
        parts = [f"major={major}", f"minor={minor}", f"patch={patch}"]
        if prerelease:
            parts.append(f"prerelease={prerelease}")
        if build:
            parts.append(f"build={build}")
        return ', '.join(parts)
    elif style == 'dict':
        return str({
            'major': major,
            'minor': minor,
            'patch': patch,
            'prerelease': prerelease,
            'build': build
        })
    elif style == 'tuple':
        return str((major, minor, patch, prerelease, build))
    else:
        raise ValueError(f"Unsupported style '{style}'.")

