def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os

    # Validate input types
    if not isinstance(commands, (str, list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string representing the working directory")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary of environment variables or None")

    # Normalize commands to a list
    if isinstance(commands, str):
        command_list = [commands]
    else:
        command_list = list(commands)

    # Append arguments
    command_list += list(args)

    if verbose:
        print("Running command:", " ".join(command_list))

    # Prepare environment
    env_to_use = os.environ.copy()
    if env:
        env_to_use.update(env)

    # Setup stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    try:
        process = subprocess.Popen(
            command_list,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            env=env_to_use,
            text=True,
        )
        stdout, _ = process.communicate()
        return_code = process.returncode
        if return_code != 0:
            raise subprocess.CalledProcessError(return_code, command_list, output=stdout)
        return stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Command '{' '.join(command_list)}' failed with return code {e.returncode}"
        ) from e
    except Exception as exc:
        raise RuntimeError(f"Failed to run command '{' '.join(command_list)}': {exc}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate and prepare command list
    if isinstance(commands, str):
        cmd_parts = [commands]
    else:
        try:
            cmd_parts = list(commands)
        except Exception as exc:
            raise TypeError("commands must be a string or an iterable of strings") from exc
    if args is None:
        arg_parts = []
    elif isinstance(args, str):
        arg_parts = [args]
    else:
        try:
            arg_parts = list(args)
        except Exception as exc:
            raise TypeError("args must be a string or an iterable of strings") from exc
    # Ensure all elements are strings
    for i, part in enumerate(cmd_parts + arg_parts):
        if not isinstance(part, str):
            raise TypeError(f"Command part at position {i} is not a string: {part!r}")
    full_cmd = cmd_parts + arg_parts
    if verbose:
        print("Running command:", " ".join(full_cmd))
    try:
        proc = subprocess.Popen(
            full_cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=env,
            shell=False
        )
        stdout, stderr = proc.communicate()
    except Exception as exc:
        raise RuntimeError(
            f"Failed to execute command '{' '.join(full_cmd)}': {exc}"
        ) from exc
    if proc.returncode != 0:
        err_msg = stderr.decode(errors="replace") if stderr else ""
        raise RuntimeError(
            f"Command '{' '.join(full_cmd)}' exited with code {proc.returncode}.\n"
            f"Error output:\n{err_msg}"
        )
    output = stdout.decode(errors="replace") if stdout else ""
    if not hide_stderr:
        # If stderr was not hidden, also return it appended
        err_output = stderr.decode(errors="replace") if stderr else ""
        if err_output:
            output += "\n" + err_output
    return output

