def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Basic type checks for parameters
    if not isinstance(validate_objects, bool):
        raise TypeError(f"'validate_objects' must be a bool, got {type(validate_objects).__name__}")
    if not isinstance(check_digests, bool):
        raise TypeError(f"'check_digests' must be a bool, got {type(check_digests).__name__}")
    if not isinstance(show_warnings, bool):
        raise TypeError(f"'show_warnings' must be a bool, got {type(show_warnings).__name__}")

    # Helper to recursively iterate over objects in the hierarchy
    def _iter_objects(root):
        stack = [root]
        visited = set()
        while stack:
            obj = stack.pop()
            obj_id = id(obj)
            if obj_id in visited:
                continue
            visited.add(obj_id)
            yield obj
            # Attempt to find sub-objects via common container attributes
            try:
                # If the object has a 'children' attribute, iterate over it
                children = getattr(obj, 'children', None)
                if isinstance(children, (list, tuple)):
                    stack.extend(children)
                elif isinstance(children, dict):
                    stack.extend(children.values())
            except Exception:
                pass
            # Inspect all attributes that might be objects
            for attr in getattr(obj, '__dict__', {}):
                try:
                    val = getattr(obj, attr)
                except Exception:
                    continue
                if isinstance(val, (list, tuple)):
                    for item in val:
                        if hasattr(item, '__dict__'):
                            stack.append(item)
                elif isinstance(val, dict):
                    for item in val.values():
                        if hasattr(item, '__dict__'):
                            stack.append(item)
                elif hasattr(val, '__dict__'):
                    stack.append(val)

    # Determine the root(s) of the hierarchy
    roots = []
    if hasattr(self, 'storage_root'):
        roots.append(self.storage_root)
    elif hasattr(self, 'root'):
        roots.append(self.root)
    else:
        # Fall back to the instance itself as root
        roots.append(self)

    num_objects = 0
    good_objects = 0

    for root in roots:
        for obj in _iter_objects(root):
            if obj is None:
                continue
            num_objects += 1
            # Skip objects that do not support validation or digest checks
            if not validate_objects and not check_digests:
                good_objects += 1
                continue
            obj_valid = True
            # Validate object if validate_objects
            if validate_objects and hasattr(obj, 'validate'):
                try:
                    result = obj.validate()
                    if result is False:
                        obj_valid = False
                except Exception as exc:
                    obj_valid = False
                    if show_warnings:
                        print(f"Warning: validation failed for {obj} (exception: {exc})")
            # Check digest if requested
            if check_digests and hasattr(obj, 'check_digest'):
                try:
                    digest_ok = obj.check_digest()
                    if not digest_ok:
                        obj_valid = False
                except Exception as exc:
                    obj_valid = False
                    if show_warnings:
                        print(f"Warning: digest check failed for {obj} (exception: {exc})")
            if obj_valid:
                good_objects += 1
            elif show_warnings:
                print(f"Warning: object {obj} failed validation checks.")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate argument types
    if not isinstance(validate_objects, bool):
        raise TypeError(f"validate_objects must be a bool, got {type(validate_objects).__name__}")
    if not isinstance(check_digests, bool):
        raise TypeError(f"check_digests must be a bool, got {type(check_digests).__name__}")
    if not isinstance(show_warnings, bool):
        raise TypeError(f"show_warnings must be a bool, got {type(show_warnings).__name__}")

    # Retrieve the collection of objects that represent the hierarchy
    try:
        # Common pattern: use 'objects', 'nodes', or '_objects' attribute if present
        if hasattr(self, 'objects'):
            obj_container = getattr(self, 'objects')
        elif hasattr(self, 'nodes'):
            obj_container = getattr(self, 'nodes')
        elif hasattr(self, '_objects'):
            obj_container = getattr(self, '_objects')
        else:
            obj_container = None
    except Exception:
        obj_container = None

    if obj_container is None:
        # Nothing to validate
        return 0, 0

    # Ensure we have an iterable container
    if isinstance(obj_container, dict):
        iterable = obj_container.values()
    else:
        iterable = obj_container

    num_objects = 0
    good_objects = 0

    for obj in iterable:
        num_objects += 1
        valid = True

        # Object validation logic
        try:
            if validate_objects:
                if hasattr(obj, 'validate') and callable(obj.validate):
                    # If the method returns a boolean or raises, we handle both
                    result = obj.validate()
                    if result is not None:
                        valid = bool(result)
                elif hasattr(obj, 'is_valid') and callable(obj.is_valid):
                    valid = bool(obj.is_valid())
                else:
                    # If no validation method, treat as invalid
                    valid = False

            if check_digests and valid:
                # Digest checking logic
                # Prefer calculate_digest if available
                digest_attr = None
                if hasattr(obj, 'calculate_digest') and callable(obj.calculate_digest):
                    calculated = obj.calculate_digest()
                    if hasattr(obj, 'digest'):
                        digest_attr = getattr(obj, 'digest')
                elif hasattr(obj, 'checksum') and callable(obj.checksum):
                    calculated = obj.checksum()
                    if hasattr(obj, 'digest'):
                        digest_attr = getattr(obj, 'digest')
                elif hasattr(obj, 'digest'):
                    # Assume digest is an attribute we can compare to something else
                    # Without an algorithm to calculate, skip
                    calculated = None

                if calculated is not None and digest_attr is not None:
                    # If digest_attr is a method, call it
                    if callable(digest_attr):
                        expected = digest_attr()
                    else:
                        expected = digest_attr
                    if calculated != expected:
                        valid = False
        except Exception as exc:
            valid = False
            if show_warnings:
                msg = f"Validation error for object {repr(obj)}: {exc}"
                try:
                    # Prefer the warnings module if available
                    import warnings
                    warnings.warn(msg)
                except Exception:
                    # Fall back to printing
                    print(msg)

        if valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    # Determine the root container to traverse. Prefer a method, else an attribute.
    if hasattr(self, "get_objects") and callable(self.get_objects):
        try:
            root_items = self.get_objects()
        except Exception as exc:
            raise RuntimeError(f"Failed to retrieve objects from self.get_objects: {exc}") from exc
    else:
        if hasattr(self, "objects"):
            root_items = self.objects
        elif hasattr(self, "root") and hasattr(self.root, "__iter__"):
            root_items = self.root
        else:
            raise AttributeError("Unable to locate root objects to validate")

    # Internal counters
    num_objects = 0
    good_objects = 0
    errors = []

    def _traverse(item):
        nonlocal num_objects, good_objects
        # Handle container types
        if isinstance(item, (list, tuple, set)):
            for sub in item:
                _traverse(sub)
        elif isinstance(item, dict):
            for sub in item.values():
                _traverse(sub)
        else:
            # Treat as leaf object
            num_objects += 1
            valid = True
            try:
                if validate_objects and hasattr(item, "validate") and callable(item.validate):
                    item.validate()
            except Exception as exc:
                valid = False
                if show_warnings:
                    warnings.warn(f"Validation failed for {item!r}: {exc}")
                errors.append((item, exc))
            try:
                if check_digests and hasattr(item, "check_digest") and callable(item.check_digest):
                    item.check_digest()
            except Exception as exc:
                valid = False
                if show_warnings:
                    warnings.warn(f"Digest check failed for {item!r}: {exc}")
                errors.append((item, exc))
            if valid:
                good_objects += 1

    try:
        _traverse(root_items)
    except Exception as exc:
        # If traversal itself fails, treat as a single error
        raise RuntimeError(f"Error during hierarchy traversal: {exc}") from exc

    # Optionally log summary of errors
    if show_warnings and errors:
        total_warnings = len(errors)
        if total_warnings > 0:
            warnings.warn(f"{total_warnings} object(s) failed validation or digest check in hierarchy.")

    return num_objects, good_objects

