                # we silently ignore missing validators.
                validate = getattr(obj, 'validate', None)
                if validate and callable(validate):
                    validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    warnings.append(f"Validation error for {obj!r}: {exc}")

        if check_digests:
            try:
                # Similar check for digest validation.
                check = getattr(obj, 'check_digest', None)
                if check and callable(check):
                    check()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    warnings.append(f"Digest error for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    if show_warnings and warnings:
        for w in warnings:
            print(w)

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json

    # Ensure we have a root path attribute
    try:
        root_path = self.root_path
    except AttributeError as exc:
        raise AttributeError("Instance must have a 'root_path' attribute") from exc

    # Create the root directory if it does not exist
    try:
        os.makedirs(root_path, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(
            f"Failed to create root directory {root_path!r}: {exc}"
        ) from exc

    # Create the OCFL application directory hierarchy
    ocfl_dir = os.path.join(root_path, ".ocfl")
    packages_dir = os.path.join(ocfl_dir, "packages")

    for d in (ocfl_dir, packages_dir):
        try:
            os.makedirs(d, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(f"Failed to create OCFL subdirectory {d!r}: {exc}") from exc

    # Ensure a manifest file exists
    manifest_file = os.path.join(ocfl_dir, "manifest.json")
    if not os.path.exists(manifest_file):
        try:
            with open(manifest_file, "w", encoding="utf-8") as f:
                json.dump({"packages": []}, f)
        except OSError as exc:
            raise RuntimeError(
                f"Failed to create manifest file {manifest_file!r}: {exc}"
            ) from exc

    # Store computed paths for later use
    self.ocfl_dir = ocfl_dir
    self.packages_dir = packages_dir
    self.manifest_file = manifest_file

    return True

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import pathlib, json, os

    # Ensure the instance has a root_path defined
    try:
        root_path = pathlib.Path(self.root_path)
    except AttributeError as exc:
        raise AttributeError("The instance must have a 'root_path' attribute.") from exc

    # If the root exists but is not a directory, raise an error
    if root_path.exists() and not root_path.is_dir():
        raise ValueError(f"Root path {root_path} exists and is not a directory.")

    # If it already exists and is not empty, consider this an error
    if root_path.exists() and any(root_path.iterdir()):
        raise ValueError(f"Root path {root_path} already exists and is not empty.")

    # Create the root directory if it does not exist
    if not root_path.exists():
        try:
            root_path.mkdir(parents=True, exist_ok=False)
        except OSError as exc:
            raise OSError(f"Failed to create root directory {root_path}: {exc}") from exc

    # Create common OCFL subdirectories
    subdirs = ["objects", "works", "manifest", "resources", "schemas"]
    for sub in subdirs:
        sub_path = root_path / sub
        try:
            sub_path.mkdir(exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create subdirectory {sub_path}: {exc}") from exc

    # Write the OCFL .ocfl_root configuration file
    ocfl_root_file = root_path / ".ocfl_root"
    root_config = {
        "version": "1.0",
        "index": "manifest",
        "manifest": "manifest.json",
    }
    try:
        with ocfl_root_file.open("w", encoding="utf-8") as f:
            json.dump(root_config, f, indent=2)
    except OSError as exc:
        raise OSError(f"Failed to write OCFL root config file {ocfl_root_file}: {exc}") from exc

    # Mark as initialized (attribute may not exist beforehand)
    setattr(self, "initialized", True)

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import pathlib

    root = pathlib.Path(self.path)
    # If the path already exists and has content, raise an error
    if root.exists():
        if any(root.iterdir()):
            raise FileExistsError(
                f"The directory {self.path} already exists and is not empty."
            )
    else:
        try:
            root.mkdir(parents=True, exist_ok=False)
        except OSError as exc:
            raise OSError(f"Could not create root directory {self.path!r}: {exc}") from exc

    # Base OCFL root directory
    ocfl_root = root / ".ocfl_root"
    try:
        ocfl_root.mkdir(exist_ok=False)
    except FileExistsError:
        raise FileExistsError(f"OCFL root '{ocfl_root}' already exists.")
    except OSError as exc:
        raise OSError(f"Could not create OCFL root directory {ocfl_root!r}: {exc}") from exc

    # Define required subdirectories per RFC for minimal operability
    dirs_to_create = [
        ocfl_root / "objects",  # where objects are stored
        ocfl_root / "objects" / "0000",  # placeholder for first object version
        ocfl_root / "objects" / "0000" / "1",  # first version of the first object
        ocfl_root / "objects" / "0000" / "1" / "files",  # files for that version
    ]

    for d in dirs_to_create:
        try:
            d.mkdir(parents=True, exist_ok=False)
        except FileExistsError:
            pass  # Already present due to previous run; ignore
        except OSError as exc:
            raise OSError(f"Could not create required subdirectory {d!r}: {exc}") from exc

    # Write the OCFL version information file
    try:
        (ocfl_root / ".ocfl_version.txt").write_text("1.0\n")
    except OSError as exc:
        raise OSError(f"Could not write OCFL version file: {exc}") from exc

    # Optionally initialize any metadata files or state here
    # For this minimal setup, nothing else is required.
    return None

def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version.strip():
        return ""
    stripped = version.strip()
    if not stripped.isdigit():
        return ""
    try:
        new_value = str(int(stripped) + 1)
    except Exception:
        return ""
    if stripped.startswith("0"):
        new_value = new_value.zfill(len(stripped))
    return new_value

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return ""
    version = version.strip()
    if not version:
        return ""

    parts = version.split('.')
    # Find the last numeric part to increment
    for idx in range(len(parts) - 1, -1, -1):
        part = parts[idx]
        if part.isdigit():
            break
    else:
        # No numeric part found, return the original string
        return version

    try:
        numeric_value = int(parts[idx])
    except ValueError:
        return version

    new_numeric = numeric_value + 1
    # Preserve leading zeros if present
    if parts[idx].startswith('0'):
        width = len(parts[idx])
        new_part = str(new_numeric).zfill(width)
    else:
        new_part = str(new_numeric)

    parts[idx] = new_part
    return ".".join(parts)

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic validation of input
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be an iterable list or tuple of directory names")
        if not all(isinstance(d, str) and d for d in version_dirs):
            raise ValueError("All items in version_dirs must be non-empty strings")

        # Prepare containers for root inventory and differences
        root_inventory = None
        # self.different_digests should be a dict mapping file -> set of version dirs where digest differs
        if not hasattr(self, "different_digests"):
            self.different_digests = {}

        for idx, vdir in enumerate(version_dirs):
            inv_path = os.path.join(vdir, "inventory.json")
            if not os.path.exists(inv_path):
                raise ValueError(f"Missing inventory file in version directory '{vdir}': expected '{inv_path}'")

            try:
                with open(inv_path, "r", encoding="utf-8") as fh:
                    inventory = json.load(fh)
            except Exception as exc:
                raise ValueError(f"Could not load inventory.json from '{vdir}': {exc}") from exc

            if not isinstance(inventory, dict):
                raise ValueError(f"Inventory in '{vdir}' must be a JSON object mapping files to digests")

            # Set the first inventory as the root if not already set
            if root_inventory is None:
                root_inventory = inventory
                continue

            # Compare current inventory against the root
            for file_path, digest in inventory.items():
                root_digest = root_inventory.get(file_path)
                if root_digest != digest:
                    self.different_digests.setdefault(file_path, set()).add(vdir)

            # Additionally, check for new files present only in the current inventory
            for file_path in set(inventory.keys()) - set(root_inventory.keys()):
                self.different_digests.setdefault(file_path, set()).add(vdir)

        # If we encountered any differences, we keep them in `self.different_digests`
        # Return self for potential chaining
        return self

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        def _load_inventory(dir_path):
            inv_path = os.path.join(dir_path, "inventory.json")
            try:
                with open(inv_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
            except FileNotFoundError as err:
                raise ValueError(f"Missing inventory file '{inv_path}': {err}") from err
            except json.JSONDecodeError as err:
                raise ValueError(f"Malformed JSON in inventory '{inv_path}': {err}") from err
            if not isinstance(data, dict):
                raise ValueError(f"Inventory '{inv_path}' must be a JSON object")
            return data

        # Determine root inventory path. Assume self.root_dir if available, else current dir.
        root_dir = getattr(self, "root_dir", os.getcwd())
        root_inventory = _load_inventory(root_dir)

        # Store differences relative to root inventory.
        digest_differences = {}

        for idx, ver_dir in enumerate(version_dirs, start=1):
            if not ver_dir:
                raise ValueError(f"Version directory name at position {idx} is empty.")
            inv = _load_inventory(ver_dir)

            # Ensure the inventory contains a 'files' section (assumed structure).
            files = inv.get("files")
            if files is None:
                raise ValueError(f"Inventory '{ver_dir}' missing 'files' section.")

            if not isinstance(files, dict):
                raise ValueError(f"'files' in inventory '{ver_dir}' must be a dict.")

            for filename, meta in files.items():
                # Each file meta is expected to contain a 'digest' key.
                try:
                    dig = meta["digest"]
                except KeyError as err:
                    raise ValueError(f"Missing 'digest' for file '{filename}' "
                                     f"in inventory '{ver_dir}'") from err

                root_meta = root_inventory.get("files", {}).get(filename)
                if root_meta is None:
                    # File exists in version but not in root; record as new.
                    digest_differences[os.path.join(ver_dir, filename)] = (None, dig)
                else:
                    root_dig = root_meta.get("digest")
                    if root_dig != dig:
                        digest_differences[os.path.join(ver_dir, filename)] = (root_dig, dig)

        # Attach the differences to the instance for later validation steps.
        self._inventory_differences = digest_differences
        return digest_differences

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        if not version_dirs:
            raise ValueError("no version directories supplied")

        # Keep track of all previous inventory items
        seen_items = set()
        # Store mappings where digests differ from root
        self._digests_differ = {}

        # Determine the root inventory path (assumed to be in self.base_dir)
        root_inventory_path = os.path.join(self.base_dir, "inventory.json")
        try:
            with open(root_inventory_path, "r", encoding="utf-8") as fh:
                root_inventory = json.load(fh)
                if not isinstance(root_inventory, dict):
                    raise ValueError("root inventory must be a JSON object")
        except FileNotFoundError:
            raise FileNotFoundError(f"root inventory not found at {root_inventory_path}")
        except json.JSONDecodeError as exc:
            raise ValueError(f"invalid JSON in root inventory: {exc}")

        # Verify inventories for each version directory
        # Ensure directories are processed in ascending order; if not, sort them
        sorted_dirs = sorted(version_dirs, key=lambda d: int(os.path.basename(d)))
        for idx, ver_dir in enumerate(sorted_dirs, start=1):
            ver_path = os.path.join(self.base_dir, ver_dir)
            inventory_path = os.path.join(ver_path, "inventory.json")

            if not os.path.isfile(inventory_path):
                raise FileNotFoundError(f"inventory not found for version '{ver_dir}' at {inventory_path}")

            try:
                with open(inventory_path, "r", encoding="utf-8") as fh:
                    inventory = json.load(fh)
                    if not isinstance(inventory, dict):
                        raise ValueError(f"inventory in {ver_dir} must be a JSON object")
            except json.JSONDecodeError as exc:
                raise ValueError(f"invalid JSON in inventory for version '{ver_dir}': {exc}")

            # Ensure inventory contains all previous items
            missing = seen_items - inventory.keys()
            if missing:
                raise ValueError(
                    f"inventory for version '{ver_dir}' is missing items from earlier versions: {sorted(missing)}")

            # Check for digest differences from the root inventory
            for path, digest in inventory.items():
                root_digest = root_inventory.get(path)
                if root_digest is not None and root_digest != digest:
                    self._digests_differ.setdefault(path, []).append(
                        {"version": ver_dir, "root_digest": root_digest, "inventory_digest": digest}
                    )

                # Add to seen set for next iterations
                seen_items.add(path)

        # After processing all inventories, ensure that no unmatched root items exist
        # (i.e., all root items should appear in at least the last inventory)
        missing_in_last = set(root_inventory.keys()) - seen_items
        if missing_in_last:
            raise ValueError(
                f"root inventory contains items not present in the last processed inventory: {sorted(missing_in_last)}")

        return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("No version directories to validate")

    # Helper to load an inventory JSON file
    def _load_inventory(path):
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file not found: {path}")
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSON in inventory {path}: {exc}")
        if not isinstance(data, dict):
            raise ValueError(f"Inventory {path} must be a JSON object")
        return data

    # Start with the root inventory (may be None)
    prev_inventory = getattr(self, "root_inventory", {}) or {}
    if prev_inventory is None:
        prev_inventory = {}

    # Record differences between version inventories and the root inventory
    self._inventory_differences = {}
    if not hasattr(self, "root_inventory"):
        # If root inventory is missing we treat it as empty
        self.root_inventory = {}

    for idx, vd in enumerate(version_dirs, start=1):
        inv_path = os.path.join(vd, "inventory")
        current_inventory = _load_inventory(inv_path)

        # Verify that all files from the previous inventory exist in current
        for file_path, digest in prev_inventory.items():
            if file_path not in current_inventory:
                raise ValueError(
                    f"File '{file_path}' is missing from inventory of version '{vd}'"
                )
            curr_digest = current_inventory[file_path]
            if curr_digest != digest:
                # Record the differing digest relative to root inventory
                diff_list = self._inventory_differences.setdefault(file_path, [])
                diff_list.append(
                    {"version": vd, "expected": digest, "found": curr_digest}
                )

        # Check for new files in the current inventory that were not in previous
        for file_path, digest in current_inventory.items():
            if file_path not in prev_inventory:
                # For new files we compare against the root inventory if present
                root_digest = getattr(self.root_inventory, "get", lambda k: None)(file_path)
                if root_digest is None:
                    # No entry in root inventory: nothing to compare
                    continue
                if digest != root_digest:
                    diff_list = self._inventory_differences.setdefault(
                        file_path, []
                    )
                    diff_list.append(
                        {
                            "version": vd,
                            "expected": root_digest,
                            "found": digest,
                        }
                    )

        # The current inventory becomes the previous for the next iteration
        prev_inventory = current_inventory

    # If no differences were found, clear the attribute to avoid stale data
    if not self._inventory_differences:
        self._inventory_differences = None
    return self

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at \"0=*\" Namaste files to determine the directory type.
    """
    import os
    if not path:
        return "error: empty path"

    if not os.path.exists(path):
        return "error: path does not exist"

    if os.path.isfile(path):
        return "file"

    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"error: cannot list directory ({e})"

        # Check for presence of files that start with '0=' (e.g., '0=xxxx')
        has_namaste = any(entry.startswith("0=") for entry in entries)
        if has_namaste:
            return "object"
        else:
            return "root"

    return "error: unknown path type"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params

    Add a list of bug IDs to the request parameters for a Bugzilla API call.
    Accepts an integer, string, or any iterable of integers/strings.
    Existing ``ids`` values are preserved and concatenated with the new ones.
    Raises :class:`TypeError` if the supplied ``bug_ids`` is not an int,
    string, or iterable of those types.
    """
    if params is None or not isinstance(params, dict):
        raise ValueError("params must be a dictionary")

    if bug_ids is None:
        return params

    # Convert bug_ids to a comma‑separated string
    if isinstance(bug_ids, (int, str)):
        ids_str = str(bug_ids)
    elif isinstance(bug_ids, (list, tuple, set)):
        try:
            ids_str = ",".join(str(i) for i in bug_ids)
        except Exception as e:
            raise TypeError("bug_ids must consist of ints or strings") from e
    else:
        raise TypeError("bug_ids must be an int, string, or iterable of those types")

    if not ids_str:
        return params  # nothing to add

    # Merge with any existing ids value
    existing = params.get("ids")
    if existing:
        if isinstance(existing, str):
            existing_ids = [part.strip() for part in existing.split(",") if part.strip()]
        else:
            existing_ids = [str(e) for e in existing]
        combined = ",".join(existing_ids + [ids_str])
        params["ids"] = combined
    else:
        params["ids"] = ids_str

    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not bug_ids:
        # Nothing to amend
        return params
    # Helper to extract id string from a value
    def _id_str(val):
        if hasattr(val, 'id'):
            return str(val.id)
        return str(val)
    # Normalize bug_ids to an iterable of id strings
    if isinstance(bug_ids, (int, str)):
        id_list = [_id_str(bug_ids)]
    elif isinstance(bug_ids, (list, tuple, set)):
        id_list = [_id_str(b) for b in bug_ids]
    else:
        # Attempt to treat as a single object with an id attribute
        try:
            id_list = [_id_str(bug_ids)]
        except Exception as e:
            raise TypeError("bug_ids must be an int, str, or iterable of ids") from e
    # Combine with any existing ids in params (if present)
    existing_ids = params.get('ids')
    if existing_ids:
        # Split on commas and strip whitespace
        existing_set = set(part.strip() for part in existing_ids.split(',') if part.strip())
        combined_set = existing_set.union(id_list)
        params['ids'] = ','.join(sorted(combined_set))
    else:
        params['ids'] = ','.join(id_list)
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if params is None or not isinstance(params, dict):
        params = {}
    if bug_ids is None:
        return params

    # Normalize bug_ids to an iterable of IDs
    if isinstance(bug_ids, (int, float)):
        bug_id_list = [bug_ids]
    elif isinstance(bug_ids, (str, bytes)):
        raise ValueError("'bug_ids' must be an iterable of IDs, not a string")
    else:
        try:
            bug_id_list = list(bug_ids)
        except TypeError:
            bug_id_list = [bug_ids]

    if not bug_id_list:
        return params

    id_strings = [str(bid) for bid in bug_id_list if bid is not None]
    if not id_strings:
        return params

    new_ids = ','.join(id_strings)

    existing = params.get('ids')
    if existing:
        merged_set = set(existing.split(',')) | set(id_strings)
        params['ids'] = ','.join(sorted(merged_set))
    else:
        params['ids'] = new_ids

    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def _is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def _merge_mapping(existing, new):
        """Recursively merge two MappingNode children."""
        existing_list = existing.value
        new_list = new.value
        # Build a key -> (key_node, value_node) mapping from existing
        merged_dict = {}
        key_order = []
        for k_node, v_node in existing_list:
            key = k_node.value
            merged_dict[key] = (k_node, v_node)
            key_order.append(key)
        # Merge new items
        for k_node, v_node in new_list:
            key = k_node.value
            if key in merged_dict:
                old_k, old_v = merged_dict[key]
                if _is_mapping(old_v) and _is_mapping(v_node):
                    merged_v = _merge_mapping(old_v, v_node)
                    merged_dict[key] = (old_k, merged_v)
                else:
                    merged_dict[key] = (old_k, v_node)
            else:
                merged_dict[key] = (k_node, v_node)
                key_order.append(key)
        # Preserve order: existing order first, then new keys appended
        merged_list = [merged_dict[key] for key in key_order]
        return type(existing)(tag=existing.tag, value=merged_list)

    result = []
    seen = {}
    order_keys = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key in seen:
            old_key_node, old_value_node = seen[key]
            if _is_mapping(old_value_node) and _is_mapping(value_node):
                merged_value = _merge_mapping(old_value_node, value_node)
                seen[key] = (old_key_node, merged_value)
            else:
                seen[key] = (old_key_node, value_node)
        else:
            seen[key] = (key_node, value_node)
            order_keys.append(key)

    for k in order_keys:
        result.append(seen[k])
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to identify mapping nodes
    def _is_mapping(node):
        try:
            return getattr(node, 'tag', '').endswith(':map')
        except Exception:
            return False

    # Helper to get key string from node
    def _key_str(node):
        try:
            return str(node.value)
        except Exception:
            return str(node)

    # Recursively merge two node values
    def _merge_values(v1, v2):
        if _is_mapping(v1) and _is_mapping(v2):
            # Build dictionaries for quick lookup
            try:
                map1_items = v1.value if isinstance(v1.value, list) else []
            except Exception:
                map1_items = []
            try:
                map2_items = v2.value if isinstance(v2.value, list) else []
            except Exception:
                map2_items = []

            map1 = { _key_str(k): v for k, v in map1_items }
            map2 = { _key_str(k): v for k, v in map2_items }

            merged_items = []

            # Preserve order: keys from first mapping, then from second
            for k in map1:
                if k in map2:
                    merged_sub = _merge_values(map1[k], map2[k])
                    merged_items.append((k, merged_sub))
                else:
                    merged_items.append((k, map1[k]))

            for k in map2:
                if k not in map1:
                    merged_items.append((k, map2[k]))

            # Construct a new mapping node with the same class and tag as the first one
            new_node = v1.__class__(tag=v1.tag, value=merged_items)
            return new_node
        else:
            # For non-mapping values, or if one side is mapping and the other is not,
            # the second value wins
            return v2

    # Main aggregation
    merged_dict = {}
    key_nodes = {}
    for key_node, val_node in nodes:
        k = _key_str(key_node)
        if k in merged_dict:
            merged_dict[k] = _merge_values(merged_dict[k], val_node)
        else:
            merged_dict[k] = val_node
            key_nodes[k] = key_node

    # Preserve the order of the first appearance of each key
    result = [(key_nodes[k], merged_dict[k]) for k in merged_dict]
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    deep merge any node values corresponding to duplicate keys and return the result.
    If there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def merge_mapping_nodes(node_a, node_b):
        """In-place merge of two MappingNode objects."""
        a_pairs = node_a.value
        for key_b, val_b in node_b.value:
            found = False
            for idx, (key_a, val_a) in enumerate(a_pairs):
                if key_a.value == key_b.value:
                    found = True
                    if isinstance(val_a, MappingNode) and isinstance(val_b, MappingNode):
                        merge_mapping_nodes(val_a, val_b)
                    else:
                        a_pairs[idx] = (key_a, val_b)
                    break
            if not found:
                a_pairs.append((key_b, val_b))
        return node_a

    merged = []
    key_index = {}
    for key_node, value_node in nodes:
        if not hasattr(key_node, 'value'):
            raise TypeError('Key node does not have a value attribute')
        k = key_node.value
        if k in key_index:
            idx = key_index[k]
            existing_key, existing_value = merged[idx]
            if isinstance(existing_value, MappingNode) and isinstance(value_node, MappingNode):
                merged_node = merge_mapping_nodes(existing_value, value_node)
                merged[idx] = (existing_key, merged_node)
            else:
                merged[idx] = (existing_key, value_node)
        else:
            merged.append((key_node, value_node))
            key_index[k] = len(merged) - 1
    return merged

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples
    in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result.
    If there are colliding keys with non-MappingNode values (e.g., integers or strings),
    the last of the values wins.
    """
    def is_mapping(node):
        """Return True if node looks like a MappingNode."""
        return hasattr(node, "value") and hasattr(node, "tag") and isinstance(node.value, list)

    def merge_pair_lists(old_pairs, new_pairs, tag):
        """
        Merge two lists of (key_node, value_node) pairs preserving the order
        of the first appearance of each key. Both lists are expected to be
        the ``value`` attribute of MappingNodes.
        """
        merged_dict = {}
        order = []

        for k_node, v_node in old_pairs:
            key_id = (k_node.tag, k_node.value)
            merged_dict[key_id] = (k_node, v_node)
            order.append(key_id)

        for k_node, v_node in new_pairs:
            key_id = (k_node.tag, k_node.value)
            if key_id in merged_dict:
                existing_k, existing_v = merged_dict[key_id]
                if is_mapping(existing_v) and is_mapping(v_node):
                    merged_v = merge_mapping(existing_v, v_node)
                    merged_dict[key_id] = (existing_k, merged_v)
                else:
                    merged_dict[key_id] = (existing_k, v_node)
            else:
                merged_dict[key_id] = (k_node, v_node)
                order.append(key_id)

        return [merged_dict[k] for k in order]

    def merge_mapping(existing, new):
        """Return a new MappingNode that deep merges *existing* and *new*."""
        merged_pairs = merge_pair_lists(existing.value, new.value, existing.tag)
        # Preserve the same class as the inputs
        return type(existing)(tag=existing.tag, value=merged_pairs)

    result_map = {}
    order = []

    for key_node, val_node in nodes:
        # Use the key's tag + value as the unique identifier for duplicate detection.
        key_id = (key_node.tag, key_node.value)

        if key_id in result_map:
            _, existing_val = result_map[key_id]
            if is_mapping(existing_val) and is_mapping(val_node):
                merged_val = merge_mapping(existing_val, val_node)
                result_map[key_id] = (key_node, merged_val)
            else:
                # For non-mapping values, keep the last one.
                result_map[key_id] = (key_node, val_node)
        else:
            result_map[key_id] = (key_node, val_node)
            order.append(key_id)

    # Return a list preserving the original order of first appearance.
    return [result_map[key_id] for key_id in order]

