def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Guard against None or unlikely types
    if parser is None:
        return ""

    # Extract actions; argparse stores them in a protected attribute.
    # Use getattr with fallback to empty list if attribute missing.
    actions = getattr(parser, "_actions", [])
    if not isinstance(actions, list):
        return ""

    flags = []
    for action in actions:
        # Every action has `option_strings`; simple positional arguments have an empty list.
        option_strings = getattr(action, "option_strings", [])
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser cannot be None")
    # argparse.ArgumentParser may not have a _actions attribute directly; but it's internal
    try:
        actions = parser._actions  # pylint: disable=protected-access
    except AttributeError as err:
        raise TypeError("Provided object does not appear to be an ArgumentParser") from err
    flags = []
    for action in actions:
        # action.option_strings is a list like ['-f', '--file']; may be empty for positional args
        if getattr(action, 'option_strings', None):
            flags.extend(action.option_strings)
    # Ensure consistent order and remove duplicates while keeping first occurrence
    seen = set()
    unique_flags = []
    for flag in flags:
        if flag not in seen:
            seen.add(flag)
            unique_flags.append(flag)
    return ' '.join(unique_flags) if unique_flags else ''

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    # Ensure input is a flat iterable of argument strings
    if not unparsed_arguments:
        args_list = []
    else:
        # If a single iterable argument is provided, use it directly
        if len(unparsed_arguments) == 1 and isinstance(unparsed_arguments[0], (list, tuple)):
            args_list = list(unparsed_arguments[0])
        else:
            args_list = list(unparsed_arguments)

    parser = argparse.ArgumentParser()
    # Prepare subparsers but do not add any named subparsers at this point
    subparsers = parser.add_subparsers(dest='subparser_name', required=False)

    try:
        # Parse the known arguments; unknown arguments will raise an error
        parsed_namespace = parser.parse_args(args_list)
    except argparse.ArgumentError as e:
        # If argparse complains due to ambiguous or invalid args, return an empty dict
        return {}
    except SystemExit:
        # If argparse tries to exit (e.g., due to -h), also return an empty dict
        return {}

    result = {'global': parsed_namespace}
    if hasattr(parsed_namespace, 'subparser_name') and parsed_namespace.subparser_name:
        # Include the subparser name if present in the parsed namespace
        result[parsed_namespace.subparser_name] = parsed_namespace

    return result

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    try:
        import argparse
        import sys
    except Exception as exc:
        raise RuntimeError(f"Required modules could not be imported: {exc}") from exc

    parser = argparse.ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subparser_name')
    # Add a dummy subparser so that argparse accepts commands without a subparser
    if sys.version_info[0] == 2:
        subparsers.add_parser('__dummy__')
    try:
        namespace, _ = parser.parse_known_args(list(unparsed_arguments))
    except Exception as exc:
        raise RuntimeError(f"Argument parsing failed: {exc}") from exc

    result: dict[str, argparse.Namespace] = {}
    key = getattr(namespace, 'subparser_name', None) or 'global'
    if key == '__dummy__':
        key = 'global'
    result[key] = namespace
    return result

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    parser = argparse.ArgumentParser(add_help=False)
    # Subparsers are usually added elsewhere; we simply parse what we have.
    # parse_known_args will safely ignore arguments not understood by this base parser
    try:
        parsed, _ = parser.parse_known_args(unparsed_arguments)
    except Exception:
        # In case of any parsing error, return empty dict
        return {}
    # Try to detect a subparser name if it was set by a subparser via set_defaults
    subparser_name = None
    for attr in ('subparser_name', 'command', 'subcommand', 'sub_parser', 'sub'):
        if hasattr(parsed, attr):
            subparser_name = getattr(parsed, attr)
            break
    key = subparser_name if subparser_name else 'global'
    return {key: parsed}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Validate inputs
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("'unparsed_arguments' must be a list or tuple")
    if not isinstance(subparsers, dict):
        raise TypeError("'subparsers' must be a dict mapping names to ArgumentParser instances")

    parsed_results = {}
    remaining_sets = []

    # Helper for an empty namespace if parsing fails
    class _DummyNamespace:
        pass

    for name, parser in subparsers.items():
        try:
            ns, rem = parser.parse_known_args(unparsed_arguments)
        except SystemExit:
            # Parser failed (e.g., missing required args); treat as if it parsed nothing
            ns = _DummyNamespace()
            rem = list(unparsed_arguments)
        parsed_results[name] = ns
        remaining_sets.append(set(rem))

    if remaining_sets:
        # Intersection gives arguments not claimed by any subparser
        common_remaining = remaining_sets[0]
        for s in remaining_sets[1:]:
            common_remaining &= s
        final_remaining = [arg for arg in unparsed_arguments if arg in common_remaining]
    else:
        final_remaining = list(unparsed_arguments)

    return parsed_results, final_remaining

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def _is_mapping_node(node):
        return hasattr(node, 'tag') and hasattr(node, 'value') and isinstance(node.value, list)

    def _merge_pair_lists(first, second):
        merged = {}
        for key, val in first + second:
            kstr = getattr(key, 'value', None)
            if kstr in merged:
                existing_key, existing_val = merged[kstr]
                # Merge mapping nodes recursively; otherwise, later value wins
                if _is_mapping_node(existing_val) and _is_mapping_node(val):
                    merged_val = _merge_pair_lists(existing_val.value, val.value)
                    existing_val.value = merged_val
                    merged[kstr] = (existing_key, existing_val)
                else:
                    merged[kstr] = (existing_key, val)
            else:
                merged[kstr] = (key, val)
        return list(merged.values())

    result_map = {}
    for key, val in nodes:
        kstr = getattr(key, 'value', None)
        if kstr in result_map:
            existing_key, existing_val = result_map[kstr]
            if _is_mapping_node(existing_val) and _is_mapping_node(val):
                # Merge the mapping node values
                merged_val = _merge_pair_lists(existing_val.value, val.value)
                existing_val.value = merged_val
                result_map[kstr] = (existing_key, existing_val)
            else:
                result_map[kstr] = (key, val)
        else:
            result_map[kstr] = (key, val)

    return list(result_map.values())

def deep_merge_nodes(nodes):
    '''
    Deep merge node values corresponding to duplicate keys in a list of
    (ScalarNode, value) tuples. MappingNode values are merged recursively.
    The last non‑MappingNode value wins when duplicates collide.
    '''
    def is_mapping(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    def merge_mapping_nodes(map1, map2):
        # map1 and map2 are MappingNode instances.
        existing = {}
        order = []
        # combine both sequences of key/value pairs
        for key_node, val in map1.value + map2.value:
            key = key_node.value
            if key not in existing:
                existing[key] = (key_node, val)
                order.append(key)
            else:
                _, existing_val = existing[key]
                if is_mapping(val) and is_mapping(existing_val):
                    merged_val = merge_mapping_nodes(existing_val, val)
                    existing[key] = (key_node, merged_val)
                else:
                    # last wins
                    existing[key] = (key_node, val)
        merged_pairs = [existing[k] for k in order]
        return type(map1)(map1.tag, merged_pairs)

    merged = {}
    order = []

    for key_node, val_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, val_node)
            order.append(key)
        else:
            _, existing_val = merged[key]
            if is_mapping(val_node) and is_mapping(existing_val):
                merged_val = merge_mapping_nodes(existing_val, val_node)
                merged[key] = (key_node, merged_val)
            else:
                # last wins
                merged[key] = (key_node, val_node)

    return [(merged[k][0], merged[k][1]) for k in order]

