    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    if parser is None:
        return ''
    # Ensure the parser is an ArgumentParser instance
    try:
        from argparse import ArgumentParser
    except Exception:
        ArgumentParser = None
    if ArgumentParser and not isinstance(parser, ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    if not hasattr(parser, "_actions"):
        raise AttributeError("The provided parser object lacks _actions attribute")
    flags = set()
    for action in parser._actions:
        # action.option_strings is a list of strings like ['-a', '--arg']
        flags.update(action.option_strings)
    return ' '.join(sorted(flags))

def parser_flags(parser):
