def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest="subcommand", required=False)

    # Parse global arguments (those that belong to the main parser)
    try:
        global_args, remaining = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        raise ValueError(f"Error parsing global arguments: {exc}") from exc

    result = {"global": global_args}

    # If there are remaining arguments, attempt to parse them with the appropriate subparser
    if remaining:
        # The first remaining token should be the subparser name
        subparser_name = remaining[0]

        # Retrieve the subparser associated with this name
        subparser = subparsers.choices.get(subparser_name)
        if subparser:
            try:
                sub_args, _ = subparser.parse_known_args(remaining)
                result[subparser_name] = sub_args
            except Exception as exc:
                raise ValueError(f"Error parsing subparser '{subparser_name}': {exc}") from exc
    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed
    namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")

    parsed_namespaces = {}
    claimed = set()

    for name, parser in subparsers.items():
        if parser is None:
            continue
        try:
            namespace, unknown = parser.parse_known_args(list(unparsed_arguments))
        except Exception:
            # If a parser fails to parse, skip it but leave the arguments untouched
            continue
        parsed_namespaces[name] = namespace
        # Arguments that this parser claimed are those not in the unknown list
        claimed.update(set(unparsed_arguments) - set(unknown))

    # Remaining arguments are those that were not claimed by any subparser
    remaining = [arg for arg in unparsed_arguments if arg not in claimed]

    return parsed_namespaces, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments.
    This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Ensure inputs are iterable
    if unparsed_arguments is None:
        arguments = []
    else:
        arguments = list(unparsed_arguments)

    if not isinstance(subparsers, dict):
        raise ValueError("subparsers must be a dictionary mapping name to ArgumentParser")

    parsed_namespaces = {}
    claimed_union = set()

    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(arguments)
        except Exception as exc:
            raise ValueError(f"Error parsing arguments for subparser '{name}': {exc}") from exc

        parsed_namespaces[name] = namespace
        # Tokens that this parser did not recognise
        unknown_set = set(unknown)
        # Tokens that this parser recognised
        recognised = [tok for tok in arguments if tok not in unknown_set]
        claimed_union.update(recognised)

    remaining = [tok for tok in arguments if tok not in claimed_union]
    return parsed_namespaces, remaining

def make_parsers():
    '''Build a top-level parser and its subparsers and return them as a tuple.'''
    try:
        parser = argparse.ArgumentParser(description='Top-level parser')
        subparsers = parser.add_subparsers(dest='command')
    except Exception as e:
        raise RuntimeError(f"Failed to build parsers: {e}") from e
    return parser, subparsers

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types and values
    if response is None:
        response = []
    if not isinstance(response, (list, tuple)):
        raise TypeError("'response' must be a list or tuple")
    if not isinstance(max_results, int):
        raise TypeError("'max_results' must be an integer")
    if max_results <= 0:
        raise ValueError("'max_results' must be greater than zero")

    def _generator():
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]

    return _generator()

