        try:
            from urllib.parse import quote
            encoded = quote(str(value), safe='')
        except Exception:
            encoded = str(value)
        return encoded

    # Perform the substitution
    return re.sub(pattern, _sub, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        # nothing to replace
        return url

    # Perform replacements for each key in url_args
    result = url
    for key, value in url_args.items():
        # Only proceed if the key is truthy
        if key is None:
            continue

        # Prepare string representation of the value
        try:
            replacement = str(value)
        except Exception:
            replacement = ''

        # Replace placeholders of the form {key} and :key
        placeholder_braces = f'{{{key}}}'
        placeholder_colon = f':{key}'

        if placeholder_braces in result:
            result = result.replace(placeholder_braces, replacement)
        if placeholder_colon in result:
            result = result.replace(placeholder_colon, replacement)

    return result

