def vertex3tuple(self, vertices):
        '''
        return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

            polygon with vertices ABCD
            Will return
            DAB, ABC, BCD, CDA -> returns 3tuples
            #A    B    C    D  -> of vertices
        '''
        try:
            verts = list(vertices)
        except TypeError:
            raise ValueError('vertices must be an iterable')
        n = len(verts)
        if n < 3:
            raise ValueError('At least three vertices required to form 3-tuples')
        result = []
        for i in range(n):
            result.append((verts[i-1], verts[i], verts[(i+1)%n]))
        return result

def int_to_string(number: int, alphabet: list, padding=None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation of the alphabet
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of single-character strings.")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two unique characters.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters.")
    if any(not isinstance(c, str) or len(c) != 1 for c in alphabet):
        raise ValueError("each element of alphabet must be a single-character string.")

    base = len(alphabet)

    # Validate padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None.")
        if padding < 0:
            raise ValueError("padding must be non-negative.")

    # Handle negative numbers: prepend '-' and convert the absolute value
    if number < 0:
        sign = '-'
        number = -number
    else:
        sign = ''

    # Special case for zero
    if number == 0:
        result = alphabet[0]
        if padding is not None:
            # Pad with leading zeros (alphabet[0])
            result = alphabet[0] * padding
        return sign + result

    # Convert number to string in the given base
    digits = []
    n = number
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base
    digits.reverse()

    result = ''.join(digits)

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return sign + result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
