        raise ValueError("alphabet must contain at least two distinct symbols for a base conversion")

    # Convert number to base using the alphabet
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            n, remainder = divmod(n, base)
            digits.append(alphabet[remainder])
        digits.reverse()  # Most significant digit first

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
        if len(digits) < padding:
            padding_needed = padding - len(digits)
            digits = [alphabet[0]] * padding_needed + digits

    return ''.join(digits)

