    # Recursive helper to walk through nested structures
    def _replace_in_structure(obj):
        if isinstance(obj, dict):
            for key, val in list(obj.items()):
                if key == register_value:
                    obj[key] = reg_num_str
                else:
                    _replace_in_structure(val)
        elif isinstance(obj, list) or isinstance(obj, tuple) or isinstance(obj, set):
            for item in obj:
                _replace_in_structure(item)
        # For other types nothing to do

    try:
        _replace_in_structure(flow_params)
    except Exception as exc:
        raise RuntimeError(f"Error while replacing register values: {exc}") from exc

    return flow_params

