def string_to_int(string: str, alphabet: list) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise TypeError("alphabet must be a list of single-character strings")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")

    base = len(alphabet)
    # Build reverse mapping: char -> digit value
    inverse_alphabet = {ch: idx for idx, ch in enumerate(alphabet)}

    result = 0
    exponent = 0
    for ch in reversed(string):
        if ch not in inverse_alphabet:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        result += inverse_alphabet[ch] * (base ** exponent)
        exponent += 1

    return result

def string_to_int(string: str, alphabet: list) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation of inputs
    if not isinstance(string, str):
        raise TypeError("string argument must be of type 'str'")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet argument must be a list of single-character strings")
    if not alphabet:
        raise ValueError("alphabet must not be empty")

    base = len(alphabet)
    # Ensure all alphabet entries are single-character strings
    for x in alphabet:
        if not isinstance(x, str) or len(x) != 1:
            raise ValueError("alphabet must contain only single-character strings")

    # Ensure no duplicate characters in alphabet
    if len(set(alphabet)) != base:
        raise ValueError("alphabet contains duplicate characters")

    # Build a mapping from character to its digit value
    digit_map = {char: idx for idx, char in enumerate(alphabet)}

    result = 0
    for pos, ch in enumerate(string):
        if ch not in digit_map:
            raise ValueError(f"Character '{ch}' at position {pos} not found in alphabet")
        result = result * base + digit_map[ch]

    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")
    # Build mapping from character to its digit value
    char_to_value = {c: i for i, c in enumerate(alphabet)}
    base = len(alphabet)
    number = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' not found in alphabet")
        number = number * base + char_to_value[ch]
