def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of unique characters")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct characters")
    if len(set(alphabet)) != base:
        raise ValueError("alphabet contains duplicate characters")

    # Build a mapping from character to its numeric value
    char_to_value = {char: idx for idx, char in enumerate(alphabet)}

    # Accumulate the numeric value
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        result = result * base + char_to_value[ch]

    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import tempfile
    import tarfile
    import os

    try:
        resp = requests.get(url, stream=True, timeout=30)
        resp.raise_for_status()
    except Exception as e:
        raise RuntimeError(f"Failed to download archive from {url}") from e

    try:
        if destination_path.exists():
            raise OSError(f"Destination path {destination_path} already exists")
        destination_path.mkdir(parents=True, exist_ok=False)
    except OSError as e:
        raise OSError(f"Could not create destination directory {destination_path}") from e

    tmp_file = None
    try:
        with tempfile.NamedTemporaryFile(suffix=".tar.gz", delete=False) as tmp:
            tmp_file = tmp.name
            for chunk in resp.iter_content(chunk_size=8192):
                if chunk:
                    tmp.write(chunk)
    except Exception as e:
        raise RuntimeError("Failed to write temporary archive file") from e

    try:
        with tarfile.open(tmp_file, mode="r:gz") as tar:
            tar.extractall(path=str(destination_path))
    except Exception as e:
        raise RuntimeError("Failed to extract archive") from e
    finally:
        if tmp_file and os.path.exists(tmp_file):
            os.remove(tmp_file)

    return destination_path

