    try:
        # Only process strings
        if not isinstance(name, str):
            return name

        # If the string has at least two characters and starts/ends with matching quotes
        if len(name) >= 2:
            # Handle double quotes
            if name.startswith('"') and name.endswith('"'):
                # Unescape escaped double quotes and backslashes
                return name[1:-1].replace('\\"', '"').replace('\\\\', '\\')
            # Handle single quotes
            if name.startswith("'") and name.endswith("'"):
                return name[1:-1].replace("\\'", "'").replace('\\\\', '\\')
            # Handle angle brackets
            if name.startswith('<') and name.endswith('>'):
                return name[1:-1]

        # Return the original string if no surrounding quotes are found
        return name
    except Exception:
        # In case of any unexpected errors, return the original input
        return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    Parameters
    ----------
    s : str or bytes
        Input command line.
    platform : str or int, optional
        'this' = auto from current platform;
        1 = POSIX;
        0 = Windows/CMD
        (other values reserved)

    Returns
    -------
    list[str]
        List of arguments.
    """
    # Ensure string
    if isinstance(s, bytes):
        try:
            s = s.decode(sys.getdefaultencoding())
        except Exception:
            s = s.decode(errors='replace')
    if not isinstance(s, str):
        raise TypeError(f"Input must be str or bytes, got {type(s).__name__}")

    if s == '':
        return []

    # Resolve platform
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    elif isinstance(platform, str):
        # allow '1' '0'
        if platform.isdigit():
            platform = int(platform)
    elif not isinstance(platform, int):
        raise TypeError(f"Platform must be int or 'this', got {type(platform).__name__}")

    # POSIX: delegate to shlex (fast enough for most cases)
    if platform == 1:
        try:
            return shlex.split(s, posix=True)
        except Exception as e:
            raise ValueError(f"Failed to split POSIX command: {e}") from e

    # Windows/CMD: simple regex-based split (does not fully emulate cmd.exe rules)
    if platform == 0:
        # Pattern: capture quoted segments or non-whitespace segments
        pattern = r'''(?:"([^"]*)"|([^\s"]+))'''
        args = []
        for match in re.finditer(pattern, s):
            quoted, unquoted = match.groups()
            if quoted is not None:
                args.append(quoted)
            elif unquoted is not None:
                args.append(unquoted)
        # Handle isolated quotes or unclosed quote: fallback split on whitespace
        if not args and re.search(r'"|\'', s):
            # naive fallback: remove surrounding quotes
            tokens = shlex.split(s, posix=False)
            return tokens
        return args

    # Reserved / unknown platform
    raise ValueError(f"Unsupported platform indicator: {platform}")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, (str, bytes)):
        raise TypeError("Input must be a string or bytes")
    if isinstance(s, bytes):
        s = s.decode('utf-8', 'replace')
    # Determine parsing mode
    if platform == 'this':
        try:
            import sys
            posix = not sys.platform.startswith('win')
        except Exception:
            posix = True
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError("Unsupported platform value: %r" % platform)

    tokens = []
    i = 0
    n = len(s)
    while i < n:
        # skip whitespace
        while i < n and s[i].isspace():
            i += 1
        if i >= n:
            break
        ch = s[i]
        # quoted string
        if posix and ch in ('"', "'"):
            quote = ch
            i += 1
            start = i
            buf = []
            while i < n:
                if s[i] == quote:
                    break
                if s[i] == '\\' and posix:
                    i += 1
                    if i < n:
                        buf.append(s[i])
                else:
                    buf.append(s[i])
                i += 1
            tokens.append(''.join(buf))
            i += 1  # skip closing quote
        elif not posix and ch == '"':
            # Windows style
            i += 1
            buf = []
            while i < n:
                if s[i] == '"':
                    break
                if s[i] == '\\' and i + 1 < n:
                    i += 1
                    buf.append(s[i])
                else:
                    buf.append(s[i])
                i += 1
            tokens.append(''.join(buf))
            i += 1
        else:
            # unquoted word
            start = i
            while i < n and not s[i].isspace():
                i += 1
            tokens.append(s[start:i])
    return tokens

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex

    # Validate and prepare input string
    if not isinstance(s, (str, bytes)):
        raise TypeError("Input must be a string or bytes")
    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except Exception as e:
            raise ValueError(f"Bytes could not be decoded: {e}") from e

    # Resolve platform specification
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    elif platform not in (0, 1):
        raise ValueError("platform must be 1 (POSIX), 0 (Windows), or 'this'")

    # POSIX splitting using shlex for correctness
    if platform == 1:
        try:
            return shlex.split(s, posix=True)
        except ValueError as e:
            raise ValueError(f"POSIX split failed: {e}") from e

    # Windows/CMD style splitting using a regex
    # This handles simple cases: words separated by whitespace, quoted
    # arguments preserved as a single token. It does not interpret
    # escape sequences as the Windows shell would, but covers typical usage.
    pattern = r'''(?:(?:"([^"]*)")|([^"\s]+))'''
    matches = re.findall(pattern, s)
    args = []
    for quoted, unquoted in matches:
        if quoted:
            args.append(quoted)
        else:
            args.append(unquoted)
    return args

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys

    if not isinstance(s, (str, bytes)):
        raise TypeError("s must be a string or bytes")

    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except UnicodeDecodeError as exc:
            raise ValueError("bytes object cannot be decoded as utf-8") from exc

    # Resolve platform value
    if platform == 'this':
        platform = 1 if not sys.platform.startswith('win') else 0
    else:
        try:
            platform = int(platform)
        except (TypeError, ValueError):
            raise ValueError("platform must be 'this', 0 (Windows), or 1 (POSIX)")

    if s == '':
        return []

    try:
        if platform == 1:  # POSIX
            posix_pat = re.compile(r'''
                "([^"\\]*(?:\\.[^"\\]*)*)"   |   # double quoted
                '([^'\\]*(?:\\.[^'\\]*)*)'   |   # single quoted
                ([^\s]+)                       # unquoted
            ''', re.VERBOSE)
            tokens = []
            for m in posix_pat.finditer(s):
                dbl, smb, unq = m.groups()
                if dbl is not None:
                    token = dbl.replace(r'\"', '"').replace(r'\n', '\n').replace(r'\t', '\t').replace(r'\r', '\r')
                    tokens.append(token)
                elif smb is not None:
                    token = smb.replace(r"\'", "'").replace(r'\n', '\n').replace(r'\t', '\t').replace(r'\r', '\r')
                    tokens.append(token)
                else:
                    tokens.append(unq)
            return tokens

        elif platform == 0:  # Windows
            win_pat = re.compile(r'''
                "([^"\\]*(?:\\.[^"\\]*)*)"     |   # quoted
                ([^\s"]+)                     # unquoted
            ''', re.VERBOSE)
            tokens = []
            for m in win_pat.finditer(s):
                quoted, unq = m.groups()
                if quoted is not None:
                    # In Windows, \\\" is a literal \" inside quotes; for simplicity we only unescape \" and \\
                    token = quoted.replace(r'\"', '"').replace(r'\\', '\\')
                    tokens.append(token)
                else:
                    tokens.append(unq)
            return tokens
        else:
            raise ValueError("Unsupported platform specifier")
    except Exception:
        # Fallback to shlex
        import shlex
        if platform == 1:
            return shlex.split(s, posix=True)
        else:
            return shlex.split(s, posix=False)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Resolve tmp_path string
    tmp_dir_root = str(tmp_path)

    # Create a unique temporary directory for extraction
    try:
        tmp_dir = subprocess.check_output(
            ["mktemp", "-d", "--tmpdir", tmp_dir_root],
            text=True
        ).strip()
    except subprocess.SubprocessError as exc:
        raise OSError(f"Failed to create temporary directory in {tmp_dir_root}") from exc

    # Prepare extraction command based on archive type
    archive_lower = archive_path.lower()
    if archive_lower.endswith((".tar.gz", ".tgz")):
        extract_cmd = ["tar", "-xzf", archive_path, "-C", tmp_dir]
    elif archive_lower.endswith((".tar.bz2", ".tbz2")):
        extract_cmd = ["tar", "-xjf", archive_path, "-C", tmp_dir]
    elif archive_lower.endswith(".zip"):
        extract_cmd = ["unzip", "-qq", archive_path, "-d", tmp_dir]
    else:
        # Unsupported archive type
        # Attempt to remove the created temp directory
        subprocess.run(["rm", "-rf", tmp_dir], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        raise ValueError(f"Unsupported archive type for {archive_path}")

    # Perform extraction
    try:
        subprocess.run(extract_cmd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError as exc:
        # Clean up on failure
        subprocess.run(["rm", "-rf", tmp_dir], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        raise RuntimeError(f"Extraction failed for {archive_path}") from exc

    # Determine the final repository path
    if filename:
        repo_path = f"{tmp_dir.rstrip('/')}/{filename}"
    else:
        # If only one top-level entry exists, use it as the repo root
        try:
            contents = subprocess.check_output(
                ["ls", "-A", tmp_dir], text=True
            ).splitlines()
        except subprocess.SubprocessError:
            # Fallback to the temp dir if listing fails
            contents = []

        if len(contents) == 1 and not contents[0].startswith('.'):
            # Assume single entry is the repo root
            repo_path = f"{tmp_dir.rstrip('/')}/{contents[0]}"
        else:
            repo_path = tmp_dir

    return f"file://{repo_path}"

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '-i', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            universal_newlines=True,
        )
    except subprocess.CalledProcessError:
        return ''
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = str(frequency).strip()
    if not freq_str:
        return None
    if freq_str.lower() == "always":
        return None

    # Normalize spaces and unit
    m = re.fullmatch(r'(?i)^\s*(-?\d+(\.\d+)?)\s+(\w+)\s*$', freq_str)
    if not m:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")

    value_str, _, unit = m.group(1, 2, 3)
    try:
        value = int(value_str)
    except ValueError:
        # support floats but timedelta only takes ints for full units
        try:
            value = float(value_str)
        except ValueError:
            raise ValueError(f"Invalid numeric value in frequency: '{value_str}'")

    # Map unit to timedelta arguments
    unit = unit.lower()
    if unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=value)
    if unit in ('minute', 'minutes', 'min', 'mins', 'm'):
        return datetime.timedelta(minutes=value)
    if unit in ('hour', 'hours', 'h'):
        return datetime.timedelta(hours=value)
    if unit in ('day', 'days', 'd'):
        return datetime.timedelta(days=value)
    if unit in ('week', 'weeks', 'w'):
        return datetime.timedelta(weeks=value)
    if unit in ('month', 'months', 'mth', 'mths'):
        # Approximate a month as 30 days
        return datetime.timedelta(days=30 * value)

    raise ValueError(f"Unrecognized time unit '{unit}' in frequency: '{frequency}'")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = str(frequency).strip()
    if not freq:
        raise ValueError("Empty frequency string")
    if freq.lower() == "always":
        return None
    import re
    m = re.match(r'^\s*(\d+)\s*([a-zA-Z]+)\s*$', freq)
    if not m:
        raise ValueError(f"Unable to parse frequency: {frequency!r}")
    number_str, unit_str = m.groups()
    try:
        number = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {number_str!r}")
    unit_map = {
        'days': 'days', 'day': 'days',
        'weeks': 'weeks', 'week': 'weeks',
        'hours': 'hours', 'hour': 'hours',
        'minutes': 'minutes', 'minute': 'minutes',
        'seconds': 'seconds', 'second': 'seconds',
        'milliseconds': 'milliseconds', 'millisecond': 'milliseconds',
        'microseconds': 'microseconds', 'microsecond': 'microseconds',
    }
    unit_key = unit_str.lower()
    if unit_key not in unit_map:
        raise ValueError(f"Unsupported time unit: {unit_str!r}")
    args = {unit_map[unit_key]: number}
    return datetime.timedelta(**args)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle empty or sentinel values
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == "always":
        return None

    if not isinstance(frequency, str):
        raise TypeError(f"Frequency must be a string or None, got {type(frequency).__name__}")

    parts = frequency.strip().lower().split()
    if len(parts) != 2:
        raise ValueError(f"Unable to parse frequency '{frequency}'. Expected '<number> <unit>' format.")

    number_str, unit = parts
    try:
        # Accept integers or floating-point numbers
        if '.' in number_str:
            value = float(number_str)
        else:
            value = int(number_str)
    except ValueError as exc:
        raise ValueError(f"Invalid number '{number_str}' in frequency '{frequency}'.") from exc

    unit_mapping = {
        "day": "days",
        "days": "days",
        "hour": "hours",
        "hours": "hours",
        "minute": "minutes",
        "minutes": "minutes",
        "second": "seconds",
        "seconds": "seconds",
        "week": "weeks",
        "weeks": "weeks",
    }

    kwarg = unit_mapping.get(unit)
    if kwarg is None:
        raise ValueError(f"Unrecognized unit '{unit}' in frequency '{frequency}'.")

    # Construct the timedelta
    return datetime.timedelta(**{kwarg: value})

