def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Normalise the input string
    if not isinstance(host, str):
        return False
    host_str = host.strip()

    # Direct check for the common hostname
    if host_str.lower() == "localhost":
        return True

    try:
        # Resolve host to addresses
        infos = socket.getaddrinfo(host_str, None)
    except socket.gaierror:
        # If resolution fails, try to interpret the host as an IP address directly
        infos = []
        # Try IPv4
        try:
            parts = host_str.split('.')
            if len(parts) == 4 and all(part.isdigit() and 0 <= int(part) <= 255 for part in parts):
                # We'll use it as a single IPv4 address
                infos.append((socket.AF_INET, None, None, None, (host_str, 0)))
        except Exception:
            pass
        # Try IPv6
        if ':' in host_str:
            # Use the host itself (no port)
            try:
                infos.append((socket.AF_INET6, None, None, None, (host_str, 0, 0, 0)))
            except Exception:
                pass

    for family, socktype, proto, canonname, sockaddr in infos:
        addr = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4: check if first octet is 127
            first_octet = addr.split('.')[0]
            if first_octet == '127':
                return True
        elif family == socket.AF_INET6:
            # IPv6: check if it represents the loopback address
            # Standard representations: "::1", "0:0:0:0:0:0:0:1"
            if addr == '::1' or addr == '0:0:0:0:0:0:0:1':
                return True
            # Some IPv6 representations may include leading zeros or omitted sections
            # Normalize by splitting on ":" and checking the last 4 hex digits
            try:
                # Expand into 8 blocks
                parts = addr.split(':')
                # Remove empty strings caused by leading/trailing "::"
                if '' in parts:
                    # Count how many blocks are missing
                    missing = 8 - (len(parts) - parts.count(''))
                    # Build full list
                    expanded = []
                    i = 0
                    while i < len(parts):
                        if parts[i] == '':
                            # insert missing zeros
                            expanded.extend(['0'] * (missing + 1))
                            i += 1
                        else:
                            expanded.append(parts[i])
                            i += 1
                    parts = expanded
                # After expansion, check if the last block is "1" and all others are "0"
                if parts and parts[-1].lstrip('0') == '1' and all(part.lstrip('0') == '0' for part in parts[:-1]):
                    return True
            except Exception:
                pass
    return False

