def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform
    all path fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if isinstance(find_paths, str):
        raise TypeError("find_paths must be an iterable of strings, not a single string")
    if not hasattr(find_paths, "__iter__"):
        raise TypeError(f"find_paths should be an iterable, got {type(find_paths)}")

    result = []
    for path in find_paths:
        if not isinstance(path, str):
            try:
                path = str(path)
            except Exception as exc:
                raise TypeError(f"Could not convert element {path!r} to string: {exc}") from exc

        # Treat as an existing pattern if it already contains a colon
        # or if it contains glob metacharacters.
        if ":" in path or any(c in path for c in "*?[]"):
            result.append(path)
        else:
            result.append(f"sh:**/*{path}*/**")

    return result

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all
    path fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if not isinstance(find_paths, (list, tuple)):
        raise TypeError(f"find_paths must be a list or tuple of strings, got {type(find_paths)}")
    result = []
    for path in find_paths:
        if not isinstance(path, str):
            raise TypeError(f"Each element in find_paths must be a string, got {type(path)}")
        if not path:
            raise ValueError("Path fragment cannot be an empty string")
        # If the path already contains a glob meta character or a directive prefix, leave it untouched
        if ':' in path or any(ch in path for ch in '*?['):
            result.append(path)
        else:
            result.append(f'sh:**/*{path}*/**')
    return result

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    if not isinstance(config_filename, str):
        raise ValueError('config_filename must be a string representing a file path')
    # Expand user and normalize path
    config_path = os.path.expanduser(config_filename)
    # If file exists and we are not allowed to overwrite, do nothing
    if os.path.isfile(config_path) and not overwrite:
        return
    # Ensure the containing directory exists
    directory = os.path.dirname(config_path)
    if directory and not os.path.isdir(directory):
        try:
            os.makedirs(directory, exist_ok=True)
        except OSError as e:
            # If the directory cannot be created and does not already exist, re-raise
            if not os.path.isdir(directory):
                raise
    # Prepare YAML content to write
    if isinstance(rendered_config, str):
        content = rendered_config
    else:
        try:
            import yaml
        except ImportError as e:
            raise ImportError('yaml module is required to dump configuration content') from e
        content = yaml.dump(rendered_config, default_flow_style=False, width=float('inf'))
    # Write to file
    try:
        with open(config_path, 'w', encoding='utf-8') as f:
            f.write(content)
    except OSError as e:
        raise OSError(f'Failed to write configuration to {config_path}') from e
    # Set file permissions
    try:
        os.chmod(config_path, mode)
    except OSError as e:
        # If permissions can't be set, ignore silently or log
        pass
    return config_path

