def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    # Return None immediately if pattern is None
    if pattern is None:
        return None

    # Handle string input: strip whitespace if requested and compile
    if isinstance(pattern, str):
        pstr = pattern.strip() if strip else pattern
        try:
            return re.compile(pstr)
        except re.error as exc:
            raise ValueError(f"Invalid regular expression string: {pstr!r}") from exc

    # Handle already compiled regex objects
    try:
        # In Python 3.7+, re.Pattern is defined
        if isinstance(pattern, re.Pattern):
            return pattern
    except AttributeError:
        pass  # re.Pattern might not exist, fall back to checking for 'pattern' attribute

    # Fallback: if the object has a `.pattern` attribute that is a string,
    # attempt to compile that string.
    if hasattr(pattern, 'pattern') and isinstance(pattern.pattern, str):
        try:
            return re.compile(pattern.pattern)
        except re.error as exc:
            raise ValueError(f"Invalid regular expression from object's pattern: {pattern.pattern!r}") from exc

    # If none of the above, raise a clear error
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd_list = [commands]
    else:
        try:
            cmd_list = list(commands)
        except Exception as exc:
            raise TypeError("commands must be a string or a sequence") from exc

    if args is not None:
        if isinstance(args, str):
            args_list = [args]
        else:
            try:
                args_list = list(args)
            except Exception as exc:
                raise TypeError("args must be a string or a sequence") from exc
        cmd_list.extend(args_list)

    if not cmd_list:
        raise ValueError("No command specified")

    # Execute and capture output
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    if verbose:
        try:
            # Use shlex to avoid unsafe printing for arguments containing spaces
            import shlex
            printable = shlex.join(cmd_list)
        except AttributeError:
            # shlex.join not available pre-Python 3.8
            printable = " ".join(cmd_list)
        print(f"Running command: {printable}")

    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            env=env,
            text=True,
            check=False,
        )
        if result.returncode != 0:
            # Include stdout and stderr in the error for debugging
            raise subprocess.CalledProcessError(
                result.returncode,
                cmd_list,
                output=result.stdout,
                stderr=result.stderr,
            )
        return result.stdout
    except Exception as exc:
        # Re-raise to preserve stack trace, but wrap Beney our errors nicely
        raise RuntimeError(f"Failed to run command {cmd_list!r}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
