def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalise command list
    if isinstance(commands, (list, tuple)):
        base_cmd = list(commands)
    elif isinstance(commands, str):
        base_cmd = [commands]
    else:
        raise ValueError("commands must be a list, tuple, or string")
    # Normalise arguments
    if args is None:
        arg_list = []
    elif isinstance(args, (list, tuple)):
        arg_list = list(args)
    elif isinstance(args, str):
        arg_list = [args]
    else:
        raise ValueError("args must be a list, tuple, string, or None")
    # Construct full command
    full_cmd = base_cmd + arg_list
    if not full_cmd:
        raise ValueError("No command to run")
    # Verbose output
    if verbose:
        try:
            # Attempt to reconstruct a shell style command string
            cmd_str = " ".join(full_cmd)
        except Exception:
            cmd_str = str(full_cmd)
        print(f"Running command: {cmd_str}")
    # Execute command
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as exc:
        # Attach stdout and stderr (if captured) to the exception for debugging
        exc.stdout = exc.stdout if hasattr(exc, "stdout") else None
        exc.stderr = exc.stderr if hasattr(exc, "stderr") else None
        raise
    return result

