def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    try:
        # Build a mapping of child to its parents and collect all nodes seen
        child_to_parents = {}
        all_nodes = set()
        for child, parent in graph.subject_objects(predicate=prop):
            all_nodes.update((child, parent))
            child_to_parents.setdefault(child, set()).add(parent)
    except Exception as exc:
        # If the graph does not support the expected interface or prop is invalid
        raise ValueError(f"Unable to process graph with prop {prop!r}: {exc}") from exc

    # If a set of roots was supplied, just filter it to valid nodes seen in the graph
    if roots is not None:
        try:
            provided = set(roots)
        except Exception as exc:
            raise ValueError(f"Provided roots argument is not iterable: {exc}") from exc
        # Keep only nodes that actually appear in the graph
        return provided & all_nodes

    # Otherwise compute roots: nodes that never appear as a child
    return {node for node in all_nodes if node not in child_to_parents}

