def _dump_string(obj, dumper=None):
    """
    Dump to a py2-unicode or py3-string
    """
    # Default to the safe dumper to avoid implicit tags
    if dumper is None:
        dumper = yaml.SafeDumper
    # Use yaml.safe_dump by default, fallback to yaml.dump if needed
    try:
        dump_func = yaml.safe_dump
        # safe_dump may not accept Dumper keyword in some yaml versions
        if 'Dumper' in dump_func.__code__.co_varnames:
            res = dump_func(obj, default_flow_style=False, allow_unicode=True, Dumper=dumper)
        else:
            res = dump_func(obj, default_flow_style=False, allow_unicode=True)
    except Exception:
        # Fallback to yaml.dump
        res = yaml.dump(obj, Dumper=dumper, default_flow_style=False, allow_unicode=True)

    # Ensure the output is a unicode string on Python 2
    if sys.version_info[0] < 3:
        if not isinstance(res, type(u'')):
            try:
                res = unicode(res, 'utf-8')
            except Exception:
                # If conversion fails, fall back to the original result
                pass
    return res

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Determine which dump function to use
    dump_func = getattr(yaml, "safe_dump", getattr(yaml, "dump"))
    # Prepare keyword arguments
    kwargs = {}
    if dumper is not None:
        kwargs["Dumper"] = dumper
    # Attempt to dump, handling possible argument errors
    try:
        result = dump_func(obj, **kwargs)
    except Exception:
        try:
            result = dump_func(obj)
        except Exception:
            # Fallback: if dump_func fails, return an empty string
            return ""
    # Ensure the result is a string (unicode on py2, str on py3)
    if result is None:
        return ""
    if isinstance(result, bytes):
        try:
            return result.decode("utf-8")
        except Exception:
            return result.decode("latin1", errors="ignore")
    return result

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        dump_str = yaml.safe_dump(obj, default_flow_style=False)
    except Exception as exc:
        raise RuntimeError(f"YAML dump failed: {exc}") from exc

    if dumper:
        # If a custom dumper is provided, use it to override the default dump.
        # The custom dumper is expected to return a string.
        try:
            dump_str = dumper(obj)
        except Exception as exc:
            raise RuntimeError(f"Custom dumper failed: {exc}") from exc

    # Convert byte strings produced by Py2's yaml to unicode.
    try:
        dump_str = dump_str.decode("utf-8")
    except AttributeError:
        # In Py3, the result is already a unicode string and has no decode().
        pass

    return dump_str

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Ensure dtype is a numpy dtype
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype {dtype!r}") from exc

    # Normalize the shape to a tuple
    if isinstance(shape, int):
        shape = (shape,)
    elif isinstance(shape, (list, tuple)):
        shape = tuple(shape)
    else:
        raise TypeError(
            f"Shape must be an int or a tuple/list of ints, got {type(shape).__name__}"
        )

    # Validate that all dimensions are non‑negative integers
    if any(not isinstance(dim, int) or dim < 0 for dim in shape):
        raise ValueError(f"All shape dimensions must be non‑negative integers, got {shape}")

    try:
        arr = np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise ValueError(
            f"Could not allocate array with shape {shape} and dtype {dtype}"
        ) from exc

    return arr

