def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError(f"Input x must be array-like: {e}")

    mu = 0.2
    sigma = 0.1

    if sigma <= 0:
        raise ValueError("sigma must be positive")

    coef = 1.0 / (sigma * np.sqrt(2 * np.pi))
    return coef * np.exp(-0.5 * ((x_arr - mu) / sigma) ** 2)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import json

    results = {}
    error_records = []

    # Use a local logger to create LogRecord objects
    _logger = logging.getLogger('config_loader')

    # Helper to create a LogRecord for an error
    def _make_error(filename, message):
        return _logger.makeRecord(
            name=_logger.name,
            level=logging.ERROR,
            fn=filename,
            lno=0,
            msg=message,
            args=(),
            exc_info=None,
            extra={}
        )

    # Helper to resolve environment variables in strings recursively
    def _resolve_env_in_value(value):
        import re
        if isinstance(value, str):
            # Replace ${VAR} with environment variable
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env_in_value(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env_in_value(v) for v in value]
        else:
            return value

    for fname in config_filenames:
        if not os.path.isfile(fname):
            error_records.append(_make_error(fname, f"Configuration file not found: {fname}"))
            continue
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            # Determine parser by file extension
            _, ext = os.path.splitext(fname.lower())
            if ext in {'.yaml', '.yml'}:
                try:
                    import yaml
                except Exception as e:
                    error_records.append(_make_error(fname, f"YAML parser not available: {e}"))
                    continue
                cfg = yaml.safe_load(raw)
            elif ext == '.toml':
                try:
                    import toml
                except Exception as e:
                    error_records.append(_make_error(fname, f"TOML parser not available: {e}"))
                    continue
                cfg = toml.loads(raw)
            elif ext == '.json':
                try:
                    cfg = json.loads(raw)
                except json.JSONDecodeError as e:
                    error_records.append(_make_error(fname, f"JSON decode error: {e}"))
                    continue
            else:
                # Default to JSON for unknown extensions
                try:
                    cfg = json.loads(raw)
                except json.JSONDecodeError:
                    error_records.append(_make_error(fname, f"Unrecognized file type and failed JSON parsing for {fname}"))
                    continue

            if not isinstance(cfg, dict):
                error_records.append(_make_error(fname, f"Configuration is not a dictionary: got {type(cfg).__name__}"))
                continue

            if resolve_env:
                cfg = _resolve_env_in_value(cfg)

            if overrides and isinstance(overrides, dict):
                # Simple overlay of overrides onto cfg
                cfg.update(overrides)

            results[fname] = cfg
        except Exception as exc:
            error_records.append(_make_error(fname, f"Unexpected error during loading: {exc}"))
    return results, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import logging, json, os

    configurations = {}
    error_records = []

    def _make_error_record(msg, filename):
        return logging.LogRecord(
            name="load_configurations",
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=msg,
            args=None,
            exc_info=None
        )

    def _expand_env(value):
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_expand_env(v) for v in value]
        if isinstance(value, str):
            return os.path.expandvars(value)
        return value

    for filename in config_filenames:
        # Skip if filename is falsy
        if not filename:
            continue
        if not os.path.isfile(filename):
            error_records.append(_make_error_record(
                f"Configuration file does not exist: {filename}", filename))
            continue

        try:
            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()
        except Exception as exc:
            error_records.append(_make_error_record(
                f"Failed to read file {filename}: {exc}", filename))
            continue

        config = None
        _, ext = os.path.splitext(filename.lower())
        try:
            if ext in {'.json'}:
                config = json.loads(raw)
            elif ext in {'.yaml', '.yml'}:
                try:
                    import yaml
                except ImportError:
                    error_records.append(_make_error_record(
                        f"PyYAML is required to parse {filename} but is not installed.", filename))
                    continue
                config = yaml.safe_load(raw)
            elif ext == '.toml':
                try:
                    import toml
                except ImportError:
                    error_records.append(_make_error_record(
                        f"toml module is required to parse {filename} but is not installed.", filename))
                    continue
                config = toml.loads(raw)
            else:
                error_records.append(_make_error_record(
                    f"Unsupported file extension {ext} for file {filename}", filename))
                continue
        except Exception as exc:
            error_records.append(_make_error_record(
                f"Error parsing {filename}: {exc}", filename))
            continue

        # Validate that the result is a dictionary
        if not isinstance(config, dict):
            error_records.append(_make_error_record(
                f"Parsed configuration from {filename} is not a dictionary", filename))
            continue

        # Apply environment variable resolution
        if resolve_env:
            try:
                config = _expand_env(config)
            except Exception as exc:
                error_records.append(_make_error_record(
                    f"Error expanding environment variables in {filename}: {exc}", filename))
                continue

        # Apply overrides
        if overrides and isinstance(overrides, dict):
            # Simple shallow merge: override keys at top level
            merged = config.copy()
            merged.update(overrides)
            config = merged

        configurations[filename] = config

    return configurations, error_records

