        try:
            path = Path(filename)
            if not path.is_file():
                raise FileNotFoundError(f"File not found: {filename}")

            data = path.read_text(encoding='utf-8')
        except Exception as exc:
            errmsg = f"Failed to read file {filename}: {exc}"
            error_records.append(_make_error_record(errmsg, filename))
            continue

        ext = path.suffix.lower()
        parser = parsers.get(ext)

        if parser is None:
            # Try default sequence: json -> yaml -> toml
            parsed_obj = None
            for fallback_ext, fallback_parser in parsers.items():
                try:
                    parsed_obj = fallback_parser(data)
                    break
                except Exception:
                    continue
            if parsed_obj is None:
                errmsg = f"Unsupported or invalid file format for {filename}"
                error_records.append(_make_error_record(errmsg, filename))
                continue
        else:
            try:
                parsed_obj = parser(data)
            except Exception as exc:
                errmsg = f"Error parsing {filename}: {exc}"
                error_records.append(_make_error_record(errmsg, filename))
                continue

        if not isinstance(parsed_obj, dict):
            errmsg = f"Configuration file {filename} does not contain a top-level dictionary."
            error_records.append(_make_error_record(errmsg, filename))
            continue

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            # Shallow merge: overrides overwrite existing keys
            parsed_obj.update(overrides)

        # Resolve environment variables if requested
        if resolve_env:
            parsed_obj = _resolve_env_vars(parsed_obj)

        parsed_configs[filename] = parsed_obj

    return parsed_configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import configparser
    from logging import LogRecord

    # Optional imports for YAML and TOML if available
    yaml = None
    toml = None
    try:
        import yaml as _yaml
        yaml = _yaml
    except Exception:
        yaml = None
    try:
        import toml as _toml
        toml = _toml
    except Exception:
        toml = None

    parsed_configs = {}
    error_records = []

    def _create_error_record(message, exc=None):
        return LogRecord(name=__name__, level=40, pathname='', lineno=0,
                         msg=message, args=(), exc_info=exc)

    for fname in config_filenames:
        if not os.path.isfile(fname):
            error_records.append(_create_error_record(f"Configuration file not found: {fname}"))
            continue
        _, ext = os.path.splitext(fname)
        ext = ext.lower()
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
            config = None
            if ext in ('.json',):
                config = json.loads(content)
            elif ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise RuntimeError("yaml module not available")
                config = yaml.safe_load(content)
            elif ext in ('.toml',):
                if toml is None:
                    raise RuntimeError("toml module not available")
                config = toml.loads(content)
            elif ext in ('.ini',):
                parser = configparser.ConfigParser()
                parser.read_string(content)
                # Convert to dict
                config = {s: dict(parser.items(s)) for s in parser.sections()}
            else:
                # Unknown extension: try JSON first
                try:
                    config = json.loads(content)
                except Exception:
                    raise ValueError(f"Unsupported configuration file format: {fname}")
            # Apply overrides if provided
            if overrides:
                if isinstance(config, dict):
                    config.update(overrides)
                else:
                    # If config is not a dict (e.g., list), skip overrides
                    pass
            # Resolve environment variables if requested
            if resolve_env and isinstance(config, dict):
                def _resolve_dict(d):
                    for k, v in d.items():
                        if isinstance(v, str):
                            d[k] = os.path.expandvars(v)
                        elif isinstance(v, dict):
                            _resolve_dict(v)
                _resolve_dict(config)
            parsed_configs[fname] = config
        except Exception as exc:
            msg = f"Error parsing configuration file {fname}: {exc}"
            error_records.append(_create_error_record(msg, exc_info=(type(exc), exc, exc.__traceback__)))
    return parsed_configs, error_records

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        handlers = {}
        # Inspect class attributes for nested handler classes
        for name, obj in vars(cls).items():
            if isinstance(obj, type):
                # Look for a special attribute indicating protocol version
                version = getattr(obj, "_protocol_version", None)
                if (
                    isinstance(version, tuple)
                    and len(version) == 2
                    and all(isinstance(v, int) for v in version)
                ):
                    handlers[version] = obj

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple of two integers")
            # Return only the handler for the requested version if present
            return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}
        return handlers

def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Ensure a mapping of handlers is available on the class
        handlers = getattr(cls, "_bolt_protocol_handlers", {})
        if not isinstance(handlers, dict):
            raise RuntimeError(
                f"{cls.__name__} does not define a proper '_bolt_protocol_handlers' mapping."
            )

        if protocol_version is None:
            # Return a copy to prevent accidental mutation
            return dict(handlers)

        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )

        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    :raise ValueError: if protocol_version tuple does not contain two ints
    """
    # Validate protocol_version
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version)!r}"
            )
        if len(protocol_version) != 2:
            raise ValueError(
                f"protocol_version tuple must contain two elements (major, minor), "
                f"got {len(protocol_version)} elements"
            )
        if not all(isinstance(v, int) for v in protocol_version):
            raise ValueError(
                f"elements of protocol_version tuple must be integers, "
                f"got {protocol_version}"
            )

    # Try to find an existing mapping of handlers
    handlers = None
    # Common attribute names that might store the mapping
    for attr_name in ("PROTOCOL_HANDLERS", "_protocol_handlers"):
        handlers = getattr(cls, attr_name, None)
        if isinstance(handlers, dict):
            break
    else:
        # Attempt to discover handler classes defined on the class
        handlers = {}
        for name, obj in cls.__dict__.items():
            # Only consider attributes that look like handlers
            if name.lower().endswith("_handler"):
                # Classes for handlers are typically subclassed from a base handler
                # We just check for the presence of a protocol_version attribute
                pv = getattr(obj, "protocol_version", None)
                if isinstance(pv, tuple) and len(pv) == 2:
                    handlers[pv] = obj

    if not isinstance(handlers, dict):
        # No handlers found; return empty mapping
        handlers = {}

    # Filter based on the provided protocol_version
    if protocol_version is None:
        return dict(handlers)
    else:
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Validate input
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )
        if len(protocol_version) != 2 or not all(
            isinstance(v, int) for v in protocol_version
        ):
            raise TypeError(
                f"protocol_version must be a tuple of two integers, got {protocol_version}"
            )

    # Gather all inner classes that are considered protocol handlers.
    # A common pattern is to attach a PROTOCOL attribute containing the
    # version tuple. Allow fallback to a '__protocol__' attribute.
    handlers = {}
    for attr_name, attr_value in vars(cls).items():
        if isinstance(attr_value, type):
            # Prefer PROTOCOL attribute
            version = None
            if hasattr(attr_value, "PROTOCOL"):
                version = getattr(attr_value, "PROTOCOL")
            elif hasattr(attr_value, "__protocol__"):
                version = getattr(attr_value, "__protocol__")
            # Ensure that the version is a tuple of two integers
            if (
                isinstance(version, tuple)
                and len(version) == 2
                and all(isinstance(v, int) for v in version)
            ):
                handlers[version] = attr_value

    # If a specific protocol_version is requested, filter the result
    if protocol_version is not None:
        return (
            {protocol_version: handlers[protocol_version]}
            if protocol_version in handlers
            else {}
        )
    return handlers

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        :returns: a :class:`Bookmarks` instance
        :raises ValueError: if ``values`` is ``None`` or not iterable
        :raises TypeError: if any element in ``values`` is not a string
        """
        if values is None:
            raise ValueError("values must not be None")
        if not hasattr(values, "__iter__") or isinstance(values, (bytes, bytearray)):
            raise ValueError("values must be an iterable of strings")

        bookmarks = []
        for raw in values:
            if not isinstance(raw, str):
                raise TypeError(
                    f"Each value must be a string, got {type(raw).__name__}"
                )
            # Assuming there is a Bookmark class with a ``from_raw`` classmethod.
            # If such a method does not exist, fallback to a simple constructor.
            try:
                bookmark = Bookmark.from_raw(raw)
            except AttributeError:
                bookmark = Bookmark(raw)
            bookmarks.append(bookmark)

        return cls(bookmarks)

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values must not be None")
    try:
        iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")
    bookmarks = []
    for raw in values:
        if not isinstance(raw, str):
            raise TypeError(f"Each raw bookmark must be a string, got {type(raw).__name__}")
        # Attempt to use an inner Bookmark constructor if available;
        # otherwise store the raw string directly.
        if hasattr(cls, "Bookmark") and callable(getattr(cls, "Bookmark")):
            try:
                bookmark_obj = cls.Bookmark(raw)
            except Exception:
                bookmark_obj = raw
        else:
            bookmark_obj = raw
        bookmarks.append(bookmark_obj)
    return cls(bookmarks)

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        from collections.abc import Iterable
        if values is None:
            raise TypeError("values must be an iterable of strings")
        if not isinstance(values, Iterable):
            raise TypeError(f"values must be an iterable, got {type(values).__name__}")
        bookmarks = []
        for raw in values:
            if raw is None:
                raise ValueError("raw bookmark value cannot be None")
            if not isinstance(raw, str):
                raise TypeError(f"expected string bookmark, got {type(raw).__name__}")
            try:
                bookmark = Bookmark.from_raw_value(raw)
            except Exception as exc:
