def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :raises TypeError: if ``values`` is not iterable or contains non-string items
    :raises ValueError: if any bookmark contains non-ASCII characters
    :returns: A ``Bookmarks`` instance containing the provided bookmarks
    """
    if values is None:
        raise ValueError("The 'values' argument cannot be None")

    bookmarks = []
    try:
        iterator = iter(values)
    except TypeError as exc:
        raise TypeError("The 'values' argument must be an iterable") from exc

    for idx, value in enumerate(iterator):
        if not isinstance(value, str):
            raise TypeError(
                f"All bookmark values must be strings, got {type(value).__name__} at index {idx}"
            )
        try:
            value.encode("ascii")
        except UnicodeEncodeError as exc:
            raise ValueError(
                f"Bookmark at index {idx} contains non-ASCII characters: {value!r}"
            ) from exc
        bookmarks.append(value.strip())

    # Assume the class constructor accepts a list of bookmark strings
    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Determine type name of the original object
    seq_type = type(seq).__name__
    if seq is None:
        return (None, seq_type)
    # If seq is a string or bytes, return it directly
    if isinstance(seq, (str, bytes)):
        return (seq, seq_type)
    # If seq is an iterable (but not a string/bytes), materialize it
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        try:
            if bufsize is not None:
                seq_list = []
                for i, item in enumerate(seq):
                    if i >= bufsize:
                        break
                    seq_list.append(item)
            else:
                seq_list = list(seq)
            return (seq_list, seq_type)
        except TypeError:
            # Fall back if conversion fails
            pass
    # Fallback: treat the input as a single scalar element
    return ([seq], seq_type)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""
    # Helper to determine if an object behaves like a sequence (but not a string)
    def _is_seq(o):
        # Strings and bytes are iterables but should not be treated as sequences here
        try:
            if isinstance(o, (str, bytes)):
                return False
            # Try to iterate over the object
            iter(o)
            return True
        except TypeError:
            return False

    # If seq is already a plain sequence type (list, tuple, range, bytearray),
    # return it unchanged.
    if isinstance(seq, (list, tuple, range, bytearray)):
        return seq, type(seq).__name__

    # If seq is a string or bytes, return it unchanged.
    if isinstance(seq, (str, bytes)):
        return seq, type(seq).__name__

    # If seq is an iterable but not a string/bytes, materialize it into a list.
    if _is_seq(seq):
        try:
            seq_list = list(seq)
        except Exception as exc:
            # Propagate error if sequence cannot be materialized
            raise TypeError(f"Unable to convert sequence to list: {exc}") from exc
        return seq_list, type(seq).__name__

    # Otherwise, treat seq as a scalar value.
    return seq, type(seq).__name__

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Handle string and bytes as atomic sequence types
    if isinstance(seq, (str, bytes)):
        return (seq, type(seq).__name__)

    # Handle list or tuple directly
    if isinstance(seq, (list, tuple)):
        return (list(seq), type(seq).__name__)

    # Try to read from file-like objects
    if hasattr(seq, "read"):
        try:
            data = seq.read() if bufsize is None else seq.read(bufsize)
        except Exception:
            # Fallback to reading whole file if partial read fails
            data = seq.read()
        return (data, type(data).__name__)

    # For generic iterables (generators, sets, etc.)
    try:
        # Attempt to convert into a string representation
        parts = []
        for item in seq:
            parts.append(str(item))
        joined = "".join(parts)
        return (joined, "iterable")
    except TypeError:
        # If seq is not iterable, return it as-is
        return (seq, type(seq).__name__)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Handle None explicitly
    if seq is None:
        return (None, None)

    # Helper to check iterable but ignore string/bytes
    def _is_iterable(obj):
        try:
            iter(obj)
        except TypeError:
            return False
        return True

    # If seq is an actual sequence type (list, tuple, set, dict) return as is
    if isinstance(seq, (list, tuple, set, dict)):
        return (seq, type(seq).__name__)

    # Strings, bytes and bytearray are also iterable but should be taken as scalars
    if isinstance(seq, (str, bytes, bytearray)):
        return (seq, type(seq).__name__)

    # For generic iterables/generators, materialize into a list
    if _is_iterable(seq):
        try:
            iterator = iter(seq)
        except TypeError:
            # Some iterables may raise if exhausted, fallback to original value
            return (seq, type(seq).__name__)

        if bufsize:
            # Buffer specific size
            seq_list = []
            chunk = []
            count = 0
            for item in iterator:
                chunk.append(item)
                count += 1
                if count >= bufsize:
                    seq_list.extend(chunk)
                    chunk = []
                    count = 0
            if chunk:
                seq_list.extend(chunk)
            return (seq_list, type(seq).__name__)
        else:
            # Full materialization
            return (list(iterator), type(seq).__name__)

    # If not iterable, just return the original value with its type
    return (seq, type(seq).__name__)

def scale(self, other=None):
    """Get or set the scale of the graph.
    If *other* is ``None``, return the scale of this graph.
    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.
    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Access current scale
    current_scale = getattr(self, 'scale', None)

    if other is None:
        return current_scale

    # Validate numeric
    if not isinstance(other, (int, float)):
        raise TypeError("Scale value must be numeric")

    # Check for unknown or zero scale
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    factor = other / current_scale

    # Determine the last coordinate
    last_coord = None
    # Prefer explicit field list
    if hasattr(self, 'fields') and isinstance(self.fields, (list, tuple)):
        if len(self.fields) == 0:
            raise AttributeError("Graph has no coordinate fields")
        last_coord = self.fields[-1]
    # Fall back to numpy array column index
    elif hasattr(self, 'data') and isinstance(self.data, np.ndarray):
        if self.data.ndim < 2:
            raise AttributeError("Graph data is not 2-dimensional")
        last_coord = self.data.shape[1] - 1
    else:
        raise AttributeError("Graph does not contain coordinate information")

    # Scale the last coordinate
    try:
        if isinstance(last_coord, str):
            # keyed data dictionary
            if hasattr(self, 'data') and isinstance(self.data, dict):
                if last_coord not in self.data:
                    raise KeyError(f"Coordinate '{last_coord}' not found in data")
                self.data[last_coord] = self.data[last_coord] * factor
            else:
                raise AttributeError("Graph data is not a dict for keyed access")
        else:
            # numeric index for numpy array
            if hasattr(self, 'data') and isinstance(self.data, np.ndarray):
                self.data[:, last_coord] = self.data[:, last_coord] * factor
            else:
                raise AttributeError("Graph data is not a numpy array for index access")
    except Exception as exc:
        raise RuntimeError(f"Failed to scale coordinate '{last_coord}': {exc}") from exc

    # Scale associated errors if present
    try:
        if hasattr(self, 'errors'):
            if isinstance(last_coord, str) and isinstance(self.errors, dict):
                if last_coord in self.errors:
                    self.errors[last_coord] = self.errors[last_coord] * factor
            elif not isinstance(last_coord, str) and isinstance(self.errors, np.ndarray):
                self.errors[:, last_coord] = self.errors[:, last_coord] * factor
    except Exception:
        # Errors scaling failure should not stop the main scaling
        pass

    # Update stored scale
    setattr(self, 'scale', other)

    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Helper class to wrap graph data
    class _SimpleGraph:
        def __init__(self, data):
            self._data = data

        def __getitem__(self, key):
            return self._data[key]

        def __repr__(self):
            return f"<SimpleGraph fields={list(self._data.keys())}>"

    # ---- Validate input ----
    # Histogram should expose edges and values (or content)
    try:
        edges = getattr(hist, "edges")
    except AttributeError:
        raise TypeError("histogram object must have an 'edges' attribute")

    try:
        values = getattr(hist, "values")
    except AttributeError:
        try:
            values = getattr(hist, "content")
        except AttributeError:
            raise TypeError("histogram object must have a 'values' or 'content' attribute")

    if not isinstance(edges, (list, tuple)):
        raise TypeError("'edges' attribute must be a list or tuple of bin boundaries")
    if not isinstance(values, (list, tuple)):
        raise TypeError("'values' attribute must be a list or tuple of bin contents")

    n_bins = len(values)
    if len(edges) != n_bins + 1:
        raise ValueError("Number of edges must be one more than number of values")

    # ---- Build coordinates ----
    coords = []
    for i in range(n_bins):
        left = float(edges[i])
        right = float(edges[i + 1])
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        elif get_coordinate == "middle":
            coord = (left + right) / 2.0
        else:
            raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
        coords.append(coord)

    # ---- Apply make_value ----
    if make_value is None:
        # Default: bin content is the value
        result_values = values
    else:
        # make_value could return a tuple or a scalar
        result_values = []
        for v in values:
            try:
                rv = make_value(v)
            except Exception as err:
                raise ValueError(f"make_value raised an exception for bin value {v!r}: {err}") from err
            result_values.append(rv)

    # ---- Assemble graph data ----
    graph_data = {}
    if len(field_names) == 0:
        raise ValueError("field_names must have at least one entry")

    # First field is always the coordinate
    graph_data[field_names[0]] = coords

    # Interpret result_values
    if isinstance(result_values[0], (tuple, list)):
        # Multiple output values per bin
        n_out = len(result_values[0])
        if len(field_names) - 1 != n_out:
            raise ValueError(
                "Number of outputs from make_value does not match "
                f"number of non‑coordinate field_names ({len(field_names)-1})"
            )
        for idx, name in enumerate(field_names[1:]):
            graph_data[name] = [rv[idx] for rv in result_values]
    else:
        # Single output value per bin
        if len(field_names) != 2:
            raise ValueError(
                "For single output value from make_value, field_names must have two entries"
            )
        graph_data[field_names[1]] = result_values

    # ---- Return graph ----
    return _SimpleGraph(graph_data)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                   field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # ------------------------------------------------------------------
    # Helper to extract counts and bin edges from various histogram
    # representations.
    # ------------------------------------------------------------------
    def _extract_counts_edges(h):
        # Standard numpy.histogram output (counts, edges)
        if isinstance(h, (list, tuple)) and len(h) == 2:
            counts, edges = h
            counts = np.asarray(counts)
            edges = np.asarray(edges)
            return counts, edges
        # numpy histogram object with counts/edges attributes
        if hasattr(h, "counts") and hasattr(h, "edges"):
            return np.asarray(h.counts), np.asarray(h.edges)
        # pandas Series histogram? Use .values and .index
        if hasattr(h, "values") and hasattr(h, "index"):
            return np.asarray(h.values), np.asarray(h.index)
        # Default: try to interpret as 1‑D array of counts, with linspace
        try:
            counts = np.asarray(h, dtype=float)
            if counts.ndim != 1:
                raise ValueError
            return counts, None
        except Exception:
            raise TypeError(
                "Unsupported histogram format; expected (counts, edges) "
                "tuple or object with 'counts' and 'edges' attributes."
            )

    # ------------------------------------------------------------------
    # Resolve maker and coordinate selection
    # ------------------------------------------------------------------
    if make_value is None:
        make_value = lambda v: v

    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError(
            "get_coordinate must be one of 'left', 'right', or 'middle'"
        )

    # ------------------------------------------------------------------
    # Extract counts and edges
    # ------------------------------------------------------------------
    try:
        import numpy as np
    except ImportError:
        raise ImportError("numpy is required for hist_to_graph")

    counts, edges = _extract_counts_edges(hist)

    # ------------------------------------------------------------------
    # Compute coordinates based on edges
    # ------------------------------------------------------------------
    if edges is not None:
        if edges.ndim != 1:
            raise ValueError("Edges array must be 1‑dimensional")
        if len(edges) != counts.shape[0] + 1:
            raise ValueError("Length of edges must be len(counts) + 1")
        if get_coordinate == "left":
            coords = edges[:-1]
        elif get_coordinate == "right":
            coords = edges[1:]
        else:  # middle
            coords = (edges[:-1] + edges[1:]) / 2.0
    else:
        # No edges provided; use integer bin indices
        coords = np.arange(counts.shape[0])

    # ------------------------------------------------------------------
    # Apply the make_value function to each count entry
    # ------------------------------------------------------------------
    processed = []
    for val in counts:
        try:
            proc_val = make_value(val)
        except Exception as exc:
            raise ValueError(
                f"make_value function failed for value {val!r}: {exc}"
            ) from exc
        processed.append(proc_val)

    # ------------------------------------------------------------------
    # Validate field_names against processed values
    # ------------------------------------------------------------------
    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a list or tuple of names")
    num_values = len(field_names) - 1  # exclude coordinate field
    for idx, val in enumerate(processed):
        if isinstance(val, (tuple, list)):
            if len(val) != num_values:
                raise ValueError(
                    f"make_value returned a sequence of length {len(val)} "
                    f"but expected {num_values} according to field_names"
                )
        else:
            if num_values != 1:
                raise ValueError(
                    f"make_value returned a single value but field_names "
                    f"expect {num_values} additional fields"
                )

    # ------------------------------------------------------------------
    # Assemble the graph as a list of tuples
    # ------------------------------------------------------------------
    graph_rows = []
    for coord, val in zip(coords, processed):
        if isinstance(val, (tuple, list)):
            row = tuple([coord] + list(val))
        else:
            row = (coord, val)
        graph_rows.append(row)

    # ------------------------------------------------------------------
    # Attach scale if requested
    # ------------------------------------------------------------------
    if scale is True:
        # Try to use histogram scale if present
        if hasattr(hist, "scale"):
            scaled_graph = {"scale": getattr(hist, "scale"), "data": graph_rows}
        else:
            scaled_graph = {"scale": None, "data": graph_rows}
        return scaled_graph
    elif scale is not None:
        # For custom scale, embed it
        return {"scale": scale, "data": graph_rows}

    return graph_rows

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    if make_value is None:
        make_value = lambda bin_: bin_

    # Locate edges and bin contents inside the histogram object.
    edges = getattr(hist, "edges", None)
    if edges is None:
        edges = getattr(hist, "bins", None)
    if edges is None:
        raise ValueError("Histogram object has no 'edges' or 'bins' attribute")

    values = getattr(hist, "values", None)
    if values is None:
        values = getattr(hist, "contents", None)
    if values is None:
        values = getattr(hist, "data", None)
    if values is None:
        raise ValueError("Histogram object has no 'values', 'contents' or 'data' attribute")

    try:
        edges = list(edges)
        values = list(values)
    except TypeError:
        raise ValueError("Histogram edges and values must be sequences")

    if len(edges) != len(values) + 1:
        raise ValueError("Edges length must be one greater than values length")

    # Determine coordinates for each bin.
    if get_coordinate == "left":
        coords = edges[:-1]
    elif get_coordinate == "right":
        coords = edges[1:]
    elif get_coordinate == "middle":
        coords = [(l + r) / 2 for l, r in zip(edges[:-1], edges[1:])]
    else:
        raise ValueError(f"Unrecognized get_coordinate option: {get_coordinate}")

    result = []
    for coord, bin_content in zip(coords, values):
        try:
            val = make_value(bin_content)
        except Exception as exc:
            raise ValueError(f"make_value function raised an exception: {exc}") from exc

        # Ensure val is a sequence if multiple fields are expected.
        if isinstance(val, (list, tuple)):
            val_list = list(val)
        else:
            val_list = [val]

        if len(val_list) != len(field_names) - 1:
            raise ValueError(f"Expected {len(field_names)-1} values from make_value, got {len(val_list)}")

        point = {}
        point[field_names[0]] = coord
        for name, v in zip(field_names[1:], val_list):
            point[name] = v
        result.append(point)

    # Attach scale if requested and available.
    if scale is not None:
        if scale is True:
            scale_obj = getattr(hist, "scale", None)
            if scale_obj is not None:
                result_scale = scale_obj
            else:
                raise ValueError("Histogram object has no 'scale' attribute")
        else:
            result_scale = scale
        # Represent the scale as a key in each point dictionary
        for p in result:
            p["scale"] = result_scale

    return result

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Provide consistency check
    if not tentative:
        try:
            provides = iface.providedBy(candidate)
        except Exception:
            provides = False
        if not provides:
            errors.append(
                Invalid(
                    f"{candidate!r} does not declare that it provides {iface!r}"
                )
            )

    # Helper to compare signatures
    def _sig_match(iface_sig, cand_sig):
        return iface_sig.parameters == cand_sig.parameters

    # 2.-4. Check each name declared in the interface
    for name in iface.names():
        iface_attr = getattr(iface, name, None)
        cand_attr = getattr(candidate, name, None)

        if callable(iface_attr):
            # Must be a method
            if cand_attr is None:
                errors.append(
                    Invalid(
                        f"{candidate!r} does not provide method {name!r} required by {iface!r}"
                    )
                )
                continue
            # Signature check
            try:
                iface_sig = inspect.signature(iface_attr)
                cand_sig = inspect.signature(cand_attr)
                if not _sig_match(iface_sig, cand_sig):
                    errors.append(
                        Invalid(
                            f"Signature mismatch for {name!r} in {candidate!r}: "
                            f"expected {iface_sig} got {cand_sig}"
                        )
                    )
            except Exception:
                # If we cannot introspect signatures, skip the check
                pass
        else:
            # Ensuring the attribute is present (non-callable)
            if cand_attr is None:
                errors.append(
                    Invalid(
                        f"{candidate!r} does not provide attribute {name!r} required by {iface!r}"
                    )
                )

    # 5. Raise aggregated errors if any
    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            message = "\n".join(str(e) for e in errors)
            raise Invalid(message)

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    try:
        import inspect
    except Exception as exc:
        raise ValueError("inspect module not available") from exc

    from zope.interface import Invalid

    errors = []

    # Check that candidate claims to provide the interface if not tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate {candidate!r} does not claim to provide {iface!r}")
        except Exception:
            errors.append(f"Unable to evaluate providedBy for {candidate!r}")

    # Helper to compare signatures
    def signatures_match(sig1, sig2):
        params1 = list(sig1.parameters.values())
        params2 = list(sig2.parameters.values())
        if len(params1) != len(params2):
            return False
        for p1, p2 in zip(params1, params2):
            if p1.kind != p2.kind or p1.name != p2.name:
                return False
            # If interface has default value, candidate must provide same default
            if p1.default is not inspect.Parameter.empty and p1.default != p2.default:
                return False
            # If interface has no default, candidate must also have no default
            if p1.default is inspect.Parameter.empty and p2.default is not inspect.Parameter.empty:
                return False
        return True

    # Iterate over interface names
    for name in iface:
        # Skip deprecated special names that don't require presence
        if name.startswith('_'):
            continue
        iface_value = getattr(iface, name, None)
        if iface_value is None:
            continue
        try:
            cand_value = getattr(candidate, name, None)
        except Exception:
            cand_value = None
        if cand_value is None:
            errors.append(f"Candidate missing required attribute/method '{name}'")
            continue

        # If interface defines a method, check for callability and signature
        is_method = False
        # Interface methods are typically zope.interface._api.Method instances
        # or plain callables; we treat any callable on interface as method.
        try:
            iface_sig = iface_value.__signature__
        except AttributeError:
            iface_sig = None
        if iface_sig is None and callable(iface_value):
            try:
                iface_sig = inspect.signature(iface_value)
            except Exception:
                iface_sig = None
        if iface_sig is not None:
            is_method = True

        if is_method:
            if not callable(cand_value):
                errors.append(f"Attribute '{name}' should be callable")
                continue
            try:
                cand_sig = inspect.signature(cand_value)
            except Exception:
                cand_sig = None
            if cand_sig is None:
                errors.append(f"Could not determine signature of candidate method '{name}'")
            else:
                if not signatures_match(iface_sig, cand_sig):
                    errors.append(
                        f"Signature mismatch for method '{name}': "
                        f"expected {iface_sig}, got {cand_sig}"
                    )
        # For attributes, no signature check - only presence is checked above

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple interface validation errors: " + "; ".join(errors))
    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it ``implements`` the interface, or the candidate itself declares that it ``provides`` the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface.exceptions import Invalid
    import inspect

    errors = []

    # 1. Check that the candidate declares that it provides the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    Invalid(
                        f"{candidate!r} does not provide {iface!r}"
                    )
                )
        except Exception as exc:
            errors.append(
                Invalid(
                    f"Error checking providedBy for {candidate!r}: {exc}"
                )
            )

    # 2 & 3. Verify required names (methods/attributes) exist
    for name in iface.names():
        if not hasattr(candidate, name):
            errors.append(
                Invalid(
                    f"{candidate!r} is missing required attribute {name!r}"
                )
            )
            continue

        # If it's a method in the interface, check signature
        iface_attr = getattr(iface, name, None)
        can_attr = getattr(candidate, name, None)

        # Skip built‑in descriptors that skip signature checking
        if inspect.isroutine(can_attr) and inspect.isroutine(iface_attr):
            try:
                iface_sig = inspect.signature(iface_attr)
                can_sig = inspect.signature(can_attr)
            except (ValueError, TypeError):
                # If we can’t introspect the signature, skip checking
                continue

            # Count required parameters (excluding *args/**kwargs)
            def required_params(sig):
                count = 0
                for p in sig.parameters.values():
                    if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
                        continue
                    if p.default is p.empty:
                        count += 1
                return count

            req_iface = required_params(iface_sig)
            req_can = required_params(can_sig)

            if req_can < req_iface:
                errors.append(
                    Invalid(
                        f"Method {name!r} in {candidate!r} does not have enough "
                        f"required parameters: interface requires {req_iface}, "
                        f"candidate has {req_can}"
                    )
                )
            # Optional: ensure parameter names match where possible
            else:
                iface_params = [
                    p.name for p in iface_sig.parameters.values()
                    if p.kind in (p.POSITIONAL_OR_KEYWORD, p.KEYWORD_ONLY)
                ]
                can_params = [
                    p.name for p in can_sig.parameters.values()
                    if p.kind in (p.POSITIONAL_OR_KEYWORD, p.KEYWORD_ONLY)
                ]
                # Compare the order of required parameters
                iface_req_order = iface_params[:req_iface]
                can_req_order = can_params[:req_can]
                if iface_req_order != can_req_order[:len(iface_req_order)]:
                    errors.append(
                        Invalid(
                            f"Method {name!r} in {candidate!r} has mismatched "
                            f"parameter order or names: interface {iface_req_order}, "
                            f"candidate {can_req_order}"
                        )
                    )

    # Handle errors according to specification
    if errors:
        if len(errors) == 1:
            # raise the single error as before
            raise errors[0]
        # multiple errors; consolidate into one Invalid
        msg = "; ".join(str(e) for e in errors)
        raise Invalid(msg)

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    The function checks whether *candidate* is a subclass of *iface* if both are
    type objects.  If that is not the case, the function compares the public
    attribute names of *iface* with those of *candidate* (or its class) and
    ensures that the candidate implements all required attributes.  The
    *tentative* flag turns the verification into a non‑exceptional check:
    when ``tentative=True`` the function simply returns ``False`` if the check
    fails instead of raising an ``AttributeError``.
    """
    if iface is None or candidate is None:
        raise ValueError('iface and candidate must not be None')
    # Resolve the class of the candidate
    target_cls = candidate if isinstance(candidate, type) else candidate.__class__
    # First, try a straightforward subclass test
    try:
        if issubclass(target_cls, iface):
            return True
    except TypeError:
        # Either iface or target_cls is not a class – fall back to attribute check
        pass
    # Gather the public members of the interface
    required_attrs = [
        name
        for name in dir(iface)
        if not name.startswith("_")
        and name not in {"__doc__", "__module__", "__dict__", "__weakref__"}
    ]
    missing = [name for name in required_attrs if not hasattr(target_cls, name)]
    if missing:
        if tentative:
            return False
        raise AttributeError(
            f"Candidate {candidate!r} does not provide required attributes "
            f"for iface {iface!r}: {missing}"
        )
    # If the interface defines callables, ensure they are also callables
    for name in required_attrs:
        interface_member = getattr(iface, name)
        candidate_member = getattr(target_cls, name)
        if callable(interface_member) and not callable(candidate_member):
            if tentative:
                return False
            raise TypeError(
                f"Candidate {candidate!r} attribute '{name}' must be callable "
                f"to satisfy iface {iface!r}"
            )
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if iface is None or candidate is None:
        raise ValueError("iface and candidate must not be None")

    # Determine class of candidate
    if isinstance(candidate, type):
        cand_cls = candidate
    else:
        cand_cls = type(candidate)

    # If candidate is a subclass of iface, we are good.
    try:
        if issubclass(cand_cls, iface):
            return True
    except TypeError:
        # One of them is not a class; we'll continue with attribute checks
        pass

    # Build list of required members from iface
    required = []
    for name in dir(iface):
        # Skip private or built‑in attributes
        if name.startswith('_'):
            continue
        required.append(name)

    missing = []
    for name in required:
        iface_attr = getattr(iface, name, None)
        cand_attr = getattr(cand_cls, name, None)

        if cand_attr is None:
            missing.append(name)
            continue

        # If iface defines a callable, cand must also provide a callable
        if callable(iface_attr) and not callable(cand_attr):
            missing.append(name)

    if missing:
        msg = (
            f"Candidate '{cand_cls.__name__}' does not provide required "
            f"members of interface '{iface.__name__}': {', '.join(missing)}"
        )
        if tentative:
            return False
        raise TypeError(msg)

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    try:
        if not isinstance(iface, type):
            raise TypeError('iface must be a class or type')
        if isinstance(candidate, type):
            ok = issubclass(candidate, iface)
        else:
            ok = isinstance(candidate, iface)
        if not ok:
            if tentative:
                return False
            raise TypeError(f'Candidate {candidate!r} does not provide interface {iface!r}')
        return True
    except Exception:
        if tentative:
            return False
        raise

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # Validate explicit metaclass
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit __metaclass__ {explicit_mc!r} is not a type")
    # If no bases and no explicit metaclass, default to type
    if not bases:
        return explicit_mc or type
    # Validate base classes and collect their metaclasses
    base_metas = []
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a type")
        base_metas.append(base.__class__)
    # Build candidate list: explicit then base metas
    candidates = []
    if explicit_mc:
        candidates.append(explicit_mc)
    candidates.extend(base_metas)
    # Remove duplicates while preserving order
    seen = set()
    metas = []
    for m in candidates:
        if m not in seen:
            seen.add(m)
            metas.append(m)
    # Determine the most derived compatible metaclass
    for mc in metas:
        if all(issubclass(mc, other) or mc is other for other in metas):
            return mc
    # No compatible metaclass found
    raise TypeError(f"metaclass conflict: {', '.join(m.__name__ for m in metas)} during class creation")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # collect candidate metaclasses: explicit first, then each base's metaclass
    metas = []
    if explicit_mc is not None:
        metas.append(explicit_mc)
    metas.extend(type(b) for b in bases)

    # If no candidates, the default metaclass is 'type'
    if not metas:
        return type

    # Determine the most derived common metaclass
    # start with the first candidate
    resolved = metas[0]
    for meta in metas[1:]:
        # Ensure both are types
        if not (isinstance(resolved, type) and isinstance(meta, type)):
            raise TypeError(
                "metaclass conflict: '{}' is not a subclass of '{}'".format(
                    meta, resolved
                )
            )
        if issubclass(meta, resolved):
            resolved = meta
        elif not issubclass(resolved, meta):
            # No compatible metaclass found
            raise TypeError(
                "metaclass conflict: '{}' is not a subclass of '{}'".format(
                    meta, resolved
                )
            )
    return resolved

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    def _is_subclass(cls, hyp):
        try:
            return issubclass(cls, hyp)
        except TypeError:
            return False

    # Gather metaclasses of the bases
    base_meta_list = [type(b) for b in bases if b is not None]

    # If an explicit metaclass was supplied, verify it against the bases
    if explicit_mc is not None:
        # Explicit metaclass should be a class
        if not isinstance(explicit_mc, type):
            raise TypeError(f"__metaclass__ must be a class, got {type(explicit_mc)!r}")

        for bm in base_meta_list:
            if bm is None:
                continue
            if not _is_subclass(explicit_mc, bm):
                raise TypeError(
                    f"__metaclass__ conflict: {explicit_mc.__name__} is not a subclass "
                    f"of base metaclass {bm.__name__}"
                )
        return explicit_mc

    # No explicit metaclass – compute the common metaclass
    if not base_meta_list:
        return type  # default metaclass when no bases are provided

    # Find a metaclass that is a subclass of all others
    common_meta = base_meta_list[0]
    for m in base_meta_list[1:]:
        if _is_subclass(m, common_meta):
            common_meta = m
        elif not _is_subclass(common_meta, m):
            raise TypeError(
                f"metaclass conflict: metaclasses {common_meta.__name__} and "
                f"{m.__name__} are incompatible"
            )

    return common_meta

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # Check for key existence first to decide whether to raise or return default
    try:
        if default is __marker:
            value = self[key]
            del self[key]
            return value
        else:
            if key in self:
                value = self[key]
                del self[key]
                return value
            else:
                return default
    except KeyError:
        # Propagate KeyError if default not provided
        if default is __marker:
            raise
        # If custom default is provided, return it
        return default
    except Exception:
        # For any other exception (e.g., unhashable key), propagate it
        raise

