def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # Obtain the list of values for the 'in' operator. Try a few common attribute names.
    values = None
    for attr in ("_in", "_in_values", "in_values", "in"):
        if hasattr(self, attr):
            values = getattr(self, attr)
            break

    # If no values or empty, return a pattern that matches nothing.
    if not values:
        return re.compile('(?!)')

    # Ensure all values are strings and escape regex metacharacters.
    try:
        escaped_values = [re.escape(str(v)) for v in values]
    except Exception as exc:
        # If any error occurs, fall back to a non-matching pattern.
        return re.compile('(?!)')

    # Build a regex that matches any one of the values, anchored.
    pattern_str = r'^(?:' + '|'.join(escaped_values) + r')$'

    try:
        return re.compile(pattern_str)
    except re.error:
        # If the compiled pattern fails, return a non-matching pattern.
        return re.compile('(?!)')

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # Compile a regex that matches an 'in' clause of the form
    # in(value1, value2, ...) with optional whitespace.
    # The captured group will contain the comma-separated values.
    pattern_str = r'\bin\s*\(\s*([^)]+?)\s*\)'
    try:
        return re.compile(pattern_str, re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in-parameter regex: {exc}") from exc

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # The pattern matches expressions like "in(value1,value2, ... )".
    # It captures the comma-separated items inside the parentheses as a
    # named group 'values', ignores surrounding whitespace, and is
    # case‑insensitive to accommodate different capitalisations of "in".
    regex_str = r'\bin\s*\((?P<values>[^()]*)\)'
    try:
        return re.compile(regex_str, flags=re.IGNORECASE)
    except re.error as exc:
        raise RuntimeError(f"Failed to compile in-style regex: {exc}") from exc

