def parse(self, timestr, default=None,
          ignoretz=False, tzinfos=None, **kwargs):
    """
    Parse the date/time string into a :class:`datetime.datetime` object.
    """
    import datetime

    # Helper to merge datetime fields with a default
    def _merge_with_default(dt, default_dt):
        result = default_dt.replace(
            year=dt.year,
            month=dt.month,
            day=dt.day,
            hour=dt.hour,
            minute=dt.minute,
            second=dt.second,
            microsecond=dt.microsecond,
        )
        if dt.tzinfo is not None:
            result = result.replace(tzinfo=dt.tzinfo)
        return result

    # If the input is already a datetime instance
    if isinstance(timestr, datetime.datetime):
        if default is not None and isinstance(default, datetime.datetime):
            return _merge_with_default(timestr, default)
        return timestr

    # Timestring must be a string now
    if not isinstance(timestr, str):
        raise TypeError("timestr must be a str or datetime instance")

    s = timestr.strip()

    # If no string value, return default
    if not s:
        return default

    # 1. Try ISO format parsing (Python 3.7+)
    try:
        # fromisoformat accepts 'YYYY-MM-DDTHH:MM:SS' with optional offset
        # It also accepts plain 'YYYY-MM-DD' and 'HH:MM:SS' but we handle these separately.
        if 'T' not in s and ' ' in s:
            # replace space between date and time with 'T' for iso parsing
            iso_candidate = s.replace(' ', 'T')
        else:
            iso_candidate = s
        dt = datetime.datetime.fromisoformat(iso_candidate)
        if ignoretz:
            dt = dt.replace(tzinfo=None)
        else:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except Exception:
        pass

    # 2. Fallback: try a small set of common patterns
    common_patterns = [
        "%Y-%m-%d %H:%M:%S.%f",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
        "%H:%M:%S.%f",
        "%H:%M:%S",
        "%H:%M",
    ]

    last_err = None
    for pattern in common_patterns:
        try:
            dt = datetime.datetime.strptime(s, pattern)
            if ignoretz:
                dt = dt.replace(tzinfo=None)
            else:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception as e:
            last_err = e

    # 3. Try parsing with tzinfos if provided and not ignored
    if not ignoretz and tzinfos is not None:
        # Very limited support: look for a trailing token that might
        # be a key in tzinfos
        parts = s.split()
        tz_token = parts[-1] if parts else None
        if tz_token in tzinfos:
            offset = tzinfos[tz_token]
            if isinstance(offset, int):
                tzinfo = datetime.timezone(datetime.timedelta(seconds=offset))
            else:
                tzinfo = offset
            # remove tz token and parse the rest
            try:
                content = ' '.join(parts[:-1])
                dt = datetime.datetime.fromisoformat(content.replace(' ', 'T'))
                dt = dt.replace(tzinfo=tzinfo)
                if ignoretz:
                    dt = dt.replace(tzinfo=None)
                return dt
            except Exception as e:
                last_err = e

    # 4. If we reach here, parsing failed
    raise ValueError(f"Could not parse date string: {timestr}") from last_err

def default_tzinfo(dt, tzinfo):
    """Sets the ``tzinfo`` parameter on naive datetimes only

    This is useful for example when you are provided a datetime that may have
    either an implicit or explicit time zone, such as when parsing a time zone
    string.
    """
    # dt must be a datetime-like object with a tzinfo attribute
    if dt is None:
        return None
    if not hasattr(dt, "tzinfo"):
        raise TypeError("dt must be a datetime instance with a tzinfo attribute")
    # If dt is naive, apply the provided tzinfo
    if dt.tzinfo is None:
        try:
            return dt.replace(tzinfo=tzinfo)
        except Exception:
            # In case replace is not available (e.g., unexpected type), return original.
            return dt
    # dt is already timezone aware; leave unchanged
    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Ensure required attributes exist
    body = getattr(request, "body", None)
    if body is None:
        return False

    # Normalise body to string
    if isinstance(body, bytes):
        try:
            body = body.decode("utf-8")
        except Exception:
            try:
                body = body.decode("latin-1")
            except Exception:
                body = ""

    # Attempt to parse as JSON
    try:
        import json
        data = json.loads(body)
        if isinstance(data, dict) and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Attempt to parse as XML
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(body)
        # The tag used for a public Diaspora message (legacy)
        if root.tag == "magicEnvelope":
            return True
    except Exception:
        pass

    return False

