def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if not request:
            return False

        # Extract path from common request attribute names
        path = None
        if hasattr(request, "path"):
            path = request.path
        elif hasattr(request, "PATH_INFO"):
            path = request.PATH_INFO
        elif hasattr(request, "META"):
            path = request.META.get("PATH_INFO")

        if not path or not path.startswith("/_matrix"):
            return False

        # Gather headers from typical locations
        headers = getattr(request, "headers", None)
        if headers is None:
            # Django/Werkzeug style
            meta = getattr(request, "META", {})
            if meta:
                headers = {}
                for k, v in meta.items():
                    # Convert META keys to canonical header names
                    if k.startswith("HTTP_"):
                        header_name = k[5:].replace("_", "-").title()
                        headers[header_name] = v
                    elif k in ("CONTENT_TYPE", "CONTENT_LENGTH"):
                        headers[k.replace("_", "-")] = v

        if not headers:
            return False

        # Must contain Matrix auth token header
        auth_token = (
            headers.get("X-Matrix-Access-Token")
            or headers.get("x-matrix-access-token")
            or headers.get("X-Matrix-Authorization")
            or headers.get("x-matrix-authorization")
        )
        if not auth_token:
            return False

        # Basic sanity check on content type
        content_type = headers.get("Content-Type") or headers.get("content-type")
        if content_type and "application/json" not in content_type.lower():
            return False

        return True
    except Exception:
        # In case any attribute access throws, we consider it not a Matrix request
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    Returns an ISO‑8601 UTC string (e.g. ``YYYY-MM-DDTHH:MM:SSZ``).
    """
    import datetime
    if dt is None:
        return None
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime instance")
    # If the datetime has no tzinfo assume UTC
    if dt.tzinfo is None:
        dt_utc = dt
    else:
        dt_utc = dt.astimezone(datetime.timezone.utc)
    return dt_utc.strftime('%Y-%m-%dT%H:%M:%SZ')

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    # Regex to find tags of form "# <TAG>" or "# TAG:" or "# TAG"
    tag_pattern = re.compile(r'#\s*(?:<(?P<tag1>\w+)>|(?P<tag2>\w+)\s*:?)')

    tags: Set[str] = set()
    in_code: bool = False
    # Preserve line endings
    lines = text.splitlines(True)
    new_lines: List[str] = []

    for line in lines:
        # Toggle code block state when encountering a line that starts an entry
        if line.lstrip().startswith('```'):
            in_code = not in_code
            new_lines.append(line)
            continue

        # If we are not inside a code block, find tags
        if not in_code:
            for m in tag_pattern.finditer(line):
                tag = m.group('tag1') or m.group('tag2')
                if tag:
                    tags.add(tag)

        # If a replacer is provided, replace tags accordingly
        if replacer is not None:
            def repl_func(match):
                tag = match.group('tag1') or match.group('tag2')
                if tag is None:
                    return match.group(0)
                try:
                    new_tag = str(replacer(tag))
                except Exception:
                    new_tag = tag
                return '# ' + new_tag

            line = tag_pattern.sub(repl_func, line)

        new_lines.append(line)

    return tags, ''.join(new_lines)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    try:
        # Ensure input is a string
        if not isinstance(text, str):
            text = str(text)

        # Regular expression to find URLs (http://, https://, or www.)
        url_pattern = re.compile(r'\b((?:https?://|www\.)[^\s<]+?)\b')

        def replace_match(m):
            url = m.group(1)
            # Ensure URLs starting with 'www.' have a scheme
            if url.startswith('www.'):
                href = 'http://' + url
            else:
                href = url
            # Attributes to add to every link
            attrs = 'target="_blank" rel="noopener noreferrer"'
            return f'<a href="{href}" {attrs}>{url}</a>'

        return url_pattern.sub(replace_match, text)
    except Exception:
        # In case of any unexpected error, return the original text
        return text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    # Pattern matches http/https URLs, excluding trailing punctuation.
    url_pattern = re.compile(r'(?P<url>https?://[^\s\'")]+)', re.IGNORECASE)

    def _replace(match):
        url = match.group('url')
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    try:
        return url_pattern.sub(_replace, text)
    except Exception:
        # In case of unexpected input, return the original text unchanged.
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
        if scheme not in ('http', 'https', 'ftp', 'ftps'):
            return None
        headers = {'Host': netloc}
        # create a HEAD request, use method='HEAD' when available
        if hasattr(request, 'Request'):
            req = request.Request(url, method='HEAD', headers=headers)
        else:  # fallback for older urllib2 style
            req = request.Request(url, headers=headers)
            req.type = 'HEAD'
        resp = urlopen(req)
        try:
            # status code can be in resp.status or resp.getcode()
            if hasattr(resp, 'status'):
                status = resp.status
            elif hasattr(resp, 'getcode'):
                status = resp.getcode()
            else:
                status = None
            if status and status >= 400 and scheme not in ('ftp', 'ftps'):
                return None
            content_type = resp.info().get('content-type')
            return content_type
        finally:
            resp.close()
    except Exception:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError
        from urllib.parse import urlparse
    except Exception:
        # urllib may not be available or import failed
        return None

    # Basic input validation
    if not isinstance(url, str) or not url:
        return None

    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        # Only HTTP/HTTPS schemes are supported for HEAD requests
        return None

    # Build a HEAD request
    # The `method` argument is available in Python 3.3+
    try:
        req = Request(url, method="HEAD")
    except TypeError:
        # Fallback for older Python versions
        req = Request(url)
        req.get_method = lambda: "HEAD"

    try:
        resp = urlopen(req, timeout=10)
    except HTTPError as e:
        # HTTPError is a subclass of URLError and contains a response
        resp = e
    except URLError:
        return None
    except Exception:
        return None

    try:
        # Retrieve the Content-Type header; may be None if absent
        content_type = resp.headers.get("Content-Type")
        # Normalise to lowercase if present
        if isinstance(content_type, str):
            return content_type.lower()
        return content_type
    finally:
        # Ensure the response is closed to free resources
        try:
            resp.close()
        except Exception:
            pass

