def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try parsing as JSON first
    import json
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass
    # Fallback to XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        ns = {"xrd": "http://docs.oasis-open.org/wsfed/xrd/1.0"}
        root = ET.fromstring(document)
        result = {}
        subject = root.find('xrd:Subject', ns)
        if subject is not None and subject.text:
            result["subject"] = subject.text
        for link in root.findall('xrd:Link', ns):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            if rel and href:
                # If multiple links have same rel, keep the first
                result.setdefault(rel, href)
        return result
    except Exception:
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result = {}
    if not document:
        return None

    # First try JSON
    try:
        data = json.loads(document)
        if isinstance(data, dict) and "links" in data:
            for link in data["links"]:
                if not isinstance(link, dict):
                    continue
                rel = link.get("rel")
                if rel == "hcard":
                    href = link.get("href")
                    if href:
                        result["hcard_url"] = href
                        return result
                # In some implementations the hcard link might use the
                # "rel" value "self". Capture that as well.
                if rel == "self":
                    href = link.get("href")
                    if href:
                        result["hcard_url"] = href
                        return result
    except Exception:
        pass  # Fall back to XRD parsing

    # Try XRD (XML) format
    try:
        root = ET.fromstring(document)
        # The XRD standard uses namespace; ignore the namespace part
        for link in root.findall(".//{*}Link"):
            try:
                rel = link.attrib.get("rel")
                if rel in ("hcard", "self"):
                    href = link.attrib.get("href")
                    if href:
                        result["hcard_url"] = href
                        return result
            except Exception:
                continue
    except Exception:
        pass

    return None

