        if isinstance(obj, dict) and "links" in obj and isinstance(obj["links"], list):
            for link in obj["links"]:
                if not isinstance(link, dict):
                    continue
                rel = link.get("rel", "")
                if "hcard" in rel:
                    href = link.get("href") or link.get("template")
                    if href:
                        result["hcard_url"] = href
    except Exception:
        # Fallback to XML/XRD interpretation
        try:
            from xml.etree import ElementTree as ET
            # Parse with namespace-insensitive search
            root = ET.fromstring(document)
            # Build namespace mapping
            namespaces = {
                "xrd": root.tag.split('}')[0].strip('{'),
            }
            # Collect all Link elements regardless of namespace
            for link in root.iter():
                if link.tag.lower().endswith("link"):
                    attrs = link.attrib
                    rel = attrs.get("rel", "")
                    if "hcard" in rel:
                        href = attrs.get("href") or attrs.get("template")
                        if href:
                            result["hcard_url"] = href
        except Exception:
            # Unable to parse, return empty dict
            pass
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return {}
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            return {}
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        links = data.get("links", [])
        if not isinstance(aliases, list):
            aliases = [aliases]
        if not isinstance(links, list):
            links = [links]
        # Identify hcard URL if present
        hcard_url = None
        for link in links:
            if not isinstance(link, dict):
                continue
            rel = link.get("rel") or ""
            href = link.get("href")
            if href and ("hcard" in rel or "hcard" in href.lower()):
                hcard_url = href
                break
        return {
            "subject": subject,
            "aliases": aliases,
            "links": links,
            "hcard_url": hcard_url,
        }
    except (json.JSONDecodeError, TypeError):
        # Fallback to XRD (XML)
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            subject = None
            aliases = []
            links = []
            for elem in root.iter():
                tag = elem.tag
                if tag.endswith("Subject") and subject is None:
                    subject = elem.text
                elif tag.endswith("Alias"):
                    aliases.append(elem.text)
                elif tag.endswith("Link"):
                    href = elem.attrib.get("href")
                    rel = elem.attrib.get("rel")
                    ltype = elem.attrib.get("type")
                    if href:
                        links.append({"rel": rel, "href": href, "type": ltype})
            # Find hcard URL
            hcard_url = None
            for l in links:
                rel = l.get("rel") or ""
                href = l.get("href")
                if href and ("hcard" in rel or "hcard" in href.lower()):
                    hcard_url = href
                    break
            return {
                "subject": subject,
                "aliases": aliases,
                "links": links,
                "hcard_url": hcard_url,
            }
        except Exception:
            # Any parsing failure results in an empty dict
            return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split('@')[1]
    except (IndexError, AttributeError):
        return None
    try:
        resource = quote(handle)
        url = f"https://{host}/.well-known/webfinger?resource={resource}"
        with closing(urlopen(url)) as page:
            content = page.read()
            if isinstance(content, bytes):
                return content.decode('utf-8', errors='replace')
            return content
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    if not isinstance(handle, str) or "@" not in handle:
        return None
    host = handle.split("@", 1)[1]
    try:
        import urllib.request
        import urllib.parse
        url = (
            f"https://{host}/.well-known/webfinger?"
            f"resource=acct:{urllib.parse.quote(handle)}"
        )
        with urllib.request.urlopen(url) as resp:
            if getattr(resp, "status", 200) != 200:
                return None
            data = resp.read()
            # Decode assuming UTF-8, replace errors to avoid exceptions
            return data.decode("utf-8", errors="replace")
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except Exception:
        # handle does not contain a host part
        return None

    # Build the webfinger URL for the given handle
    url = "https://%s/.well-known/webfinger?resource=acct:%s" % (host, handle)

    try:
        # Make the request and read the response
        with urllib2.urlopen(url) as response:
            # Decode the response to a string (ignore errors if any)
            return response.read().decode("utf-8", errors="ignore")
    except Exception:
        # Any error (network, HTTP, etc.) results in None
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Validate handle format and extract host
    try:
        _, host = handle.rsplit("@", 1)
    except Exception:
        return None
    # Construct the webfinger URL
    try:
        resource = "acct:%s" % handle
        # Use urllib.quote to encode the resource parameter
        url = "https://%s/.well-known/webfinger?resource=%s" % (
            host,
            urllib.quote(resource),
        )
    except Exception:
        return None
    # Perform the HTTP GET request safely
    try:
        with closing(urllib2.urlopen(url)) as response:
            content = response.read()
            if isinstance(content, bytes):
                return content.decode("utf-8", errors="replace")
            return content
    except Exception:
        return None

