def dict_insert(dic, val, key, *keys):
    """
    insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("The first argument must be a dictionary")

    # Determine the full chain of keys.  If *keys is empty and ``key`` is an
    # iterable that is not a string, treat it as the key sequence.
    if not keys and isinstance(key, (list, tuple)) and not isinstance(key, str):
        key_chain = list(key)
    else:
        key_chain = [key] + list(keys)

    if not key_chain:
        raise ValueError("At least one key must be provided")

    current = dic
    for k in key_chain[:-1]:
        if not isinstance(current, dict):
            raise TypeError(f"Expected a dict at key '{k}', but got {type(current).__name__}")
        if k not in current:
            current[k] = {}
        elif not isinstance(current[k], dict):
            raise TypeError(f"Expected a dict at key '{k}', but got {type(current[k]).__name__}")
        current = current[k]

    # Set the final value
    if not isinstance(current, dict):
        raise TypeError(f"Expected a dict at final key, but got {type(current).__name__}")
    current[key_chain[-1]] = val
    return dic

def list_of_file_names(settings_dirs, spec_option=None):
    """Return a sorted list of fully-qualified file names from the given
    settings directory or directories, optionally filtering by a glob
    pattern or file extension.

    Parameters
    ----------
    settings_dirs : Union[str, Iterable[str]]
        One or more directories to search for files.
    spec_option : str, optional
        A glob pattern (e.g., ``*.ini``) or file extension (e.g., ``.ini``)
        to filter the returned file names.  If ``None``, all files are
        returned.

    Returns
    -------
    list[str]
        Sorted list of full file paths that match the ``spec_option``
        (if provided).  Returns an empty list if the directory cannot be
        accessed or if no matching files are found.
    """
    import os
    import fnmatch

    # Normalise ``settings_dirs`` to an iterable of paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            dirs = []

    matched_files = []
    for directory in dirs:
        if not isinstance(directory, (str, bytes)):
            continue  # skip invalid entries
        try:
            for name in os.listdir(directory):
                if spec_option is None:
                    matched = True
                else:
                    matched = fnmatch.fnmatch(name, spec_option)
                if matched:
                    full_path = os.path.join(directory, name)
                    if os.path.isfile(full_path):
                        matched_files.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(matched_files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    # Ensure settings_dirs is an iterable of directories
    if not isinstance(settings_dirs, (list, tuple, set)):
        settings_dirs = [settings_dirs]
    files = []
    for directory in settings_dirs:
        try:
            for entry in os.listdir(directory):
                full_path = os.path.join(directory, entry)
                if not os.path.isfile(full_path):
                    continue
                if spec_option is None:
                    files.append(full_path)
                else:
                    try:
                        # Try glob-like matching first
                        if fnmatch.fnmatch(entry, spec_option):
                            files.append(full_path)
                        else:
                            # If not matched by glob, try regex
                            if re.search(spec_option, entry):
                                files.append(full_path)
                    except re.error:
                        # If spec_option is not a valid regex, fall back to strict equality
                        if entry == spec_option:
                            files.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return sorted(files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Normalize input to a list of directory paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            # If settings_dirs is not iterable, treat it as a single path
            dirs = [settings_dirs]

    # Prepare pattern(s) for filtering.  If spec_option is a string, it can
    # be used directly as a glob pattern; if it is iterable, join into a list.
    patterns = []
    if spec_option is None:
        patterns.append("*")
    elif isinstance(spec_option, str):
        patterns.append(spec_option)
    else:
        try:
            for pat in spec_option:
                patterns.append(str(pat))
        except Exception:
            patterns.append("*")

    matched_files = []
    for directory in dirs:
        if not isinstance(directory, (str, bytes)):
            continue
        try:
            entries = os.listdir(directory)
        except OSError:
            continue
        for entry in entries:
            if any(fnmatch.fnmatch(entry, pat) for pat in patterns):
                full_path = os.path.join(directory, entry)
                # Only include regular files, ignore directories
                if os.path.isfile(full_path):
                    matched_files.append(os.path.abspath(full_path))
    return sorted(matched_files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """    
    try:
        # Ensure we work with a list of directories
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)
        result = []
        # Normalise spec_option to string; if empty, match all files
        spec = str(spec_option).strip() if spec_option else ''
        for d in dirs:
            d_path = os.path.abspath(d)
            if not os.path.isdir(d_path):
                continue
            try:
                for fname in os.listdir(d_path):
                    if spec and not fname.endswith(spec):
                        continue
                    result.append(os.path.join(d_path, fname))
            except OSError:
                # Skip directories that can't be listed
                continue
        return sorted(result)
    except Exception:
        # Any unexpected error results in an empty list rather than a crash
        return []

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize settings_dirs to a list
        if isinstance(settings_dirs, str):
            directories = [settings_dirs]
        else:
            directories = list(settings_dirs)

        file_list = []
        for directory in directories:
            if not os.path.isdir(directory):
                continue
            try:
                entries = os.listdir(directory)
            except OSError:
                continue
            for fname in entries:
                # Skip if spec_option is provided and does not match
                if spec_option:
                    # Multiple patterns
                    if isinstance(spec_option, (list, tuple)):
                        if not any(fnmatch.fnmatch(fname, pat) for pat in spec_option):
                            continue
                    else:
                        if not fnmatch.fnmatch(fname, spec_option):
                            continue
                file_list.append(os.path.join(directory, fname))
        return sorted(file_list)
    except Exception:
        return []

