def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    This helper expands nested ``include`` directives that specify other
    section definitions.  The ``include`` key may contain:

        * a single string – name of the section in ``parser_dict`` to merge
        * a list of strings – merge each section
        * a dict mapping names to file paths – load the JSON/YAML file and merge

    The function is safe against circular includes and missing sections.
    It returns a new dictionary with all includes resolved.

    Parameters
    ----------
    parser_dict : dict
        The original parser dictionary that may contain ``include`` directives.

    Returns
    -------
    dict
        A new dictionary with ``include`` directives expanded.
    """
    import json
    import yaml
    from collections import deque

    def _load_from_path(path):
        """Try to load a JSON or YAML file from *path*."""
        try:
            with open(path, "r", encoding="utf-8") as f:
                if path.lower().endswith(".json"):
                    return json.load(f)
                if path.lower().endswith((".yaml", ".yml")):
                    return yaml.safe_load(f)
        except Exception:
            pass
        return None

    # Deep copy is not strictly required as we avoid mutation of the input.
    result = {}
    seen = set()          # keep track of already expanded sections
    work = deque([(None, parser_dict)])  # (current key prefix, section dict)

    while work:
        prefix, section = work.popleft()
        for key, value in section.items():
            if key == "include":
                # Normalize to a list of things to include
                includes = value
                if isinstance(includes, (str, int, float)):
                    includes = [includes]
                elif isinstance(includes, dict):
                    includes = list(includes.values())
                elif not isinstance(includes, (list, tuple)):
                    continue

                for inc in includes:
                    # If inc is a string pointing to a file, load it
                    if isinstance(inc, str) and (inc.endswith(".json") or inc.endswith((".yml", ".yaml"))):
                        inc_dict = _load_from_path(inc)
                        if inc_dict is None:
                            continue
                    else:
                        inc_dict = parser_dict.get(inc)

                    if not isinstance(inc_dict, dict):
                        continue

                    inc_key = f"{prefix}.{inc}" if prefix else inc
                    if inc_key in seen:
                        # Skip circular references
                        continue
                    seen.add(inc_key)
                    work.append((inc_key, inc_dict))
                continue

            # For normal key-value pairs, merge directly
            if isinstance(value, dict) and isinstance(result.get(key), dict):
                # Merge sub-dicts
                merged = result[key].copy()
                merged.update(value)
                result[key] = merged
            else:
                result[key] = value

    return result

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    visited = set()

    def _resolve(value):
        """Recursively resolve includes in a value which may be dict or list."""
        if isinstance(value, dict):
            # Resolve any nested includes first
            if 'include' in value:
                include_key = value['include']
                if include_key in visited:
                    raise RuntimeError(f"Circular include detected for '{include_key}'")
                if include_key not in parser_dict:
                    raise KeyError(f"Include key '{include_key}' not found in parser_dict")
                visited.add(include_key)
                included = _resolve(parser_dict[include_key])
                visited.remove(include_key)
                # Merge included dict with remaining keys from value
                merged = dict(included)
                for k, v in value.items():
                    if k != 'include':
                        merged[k] = _resolve(v)
                return merged
            # No direct include; recurse into dictionary
            return {k: _resolve(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve(v) for v in value]
        # Primitive value: return as-is
        return value

    # Resolve includes for each top‑level key
    resolved = {}
    for key, val in parser_dict.items():
        resolved[key] = _resolve(val)
    return resolved

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        def merge(dest, src):
            for k, v in src.items():
                if (
                    k in dest
                    and isinstance(dest[k], dict)
                    and isinstance(v, dict)
                ):
                    merge(dest[k], v)
                else:
                    dest[k] = v

        resolved = {}
        visited = set()

        def process(name):
            if name in visited:
                return
            visited.add(name)
            if name not in parser_dict:
                return
            entry = parser_dict[name]
            if not isinstance(entry, dict):
                return
            includes = entry.pop("include", None)
            if includes:
                if isinstance(includes, str):
                    includes = [includes]
                for inc_name in includes:
                    process(inc_name)
            merge(resolved, entry)

        for pname in list(parser_dict.keys()):
            process(pname)

        return resolved

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    visited = set()

    def _resolve(name, parser):
        if not isinstance(parser, dict):
            return
        include = parser.get('include')
        if not include:
            return
        # Normalize to a list
        if isinstance(include, (str, bytes)):
            include_list = [include]
        elif isinstance(include, (list, tuple)):
            include_list = include
        else:
            raise TypeError(f"Invalid include type for parser '{name}': {type(include).__name__}")

        for inc_name in include_list:
            ifinc_parser = parser_dict.get(inc_name)
            if ifinc_parser is None:
                raise KeyError(f"Included parser '{inc_name}' not found for '{name}'")
            if inc_name == name:
                raise ValueError(f"Parser '{name}' includes itself")
            if inc_name in visited:
                raise ValueError(f"Circular include detected: {inc_name} already visited while resolving '{name}'")
            visited.add(inc_name)
            # Recursively resolve nested includes in the included parser
            _resolve(inc_name, ifinc_parser)
            # Merge into current parser
            for k, v in ifinc_parser.items():
                if k == 'include':
                    continue
                if k in parser and isinstance(parser[k], dict) and isinstance(v, dict):
                    # Merge nested dictionaries
                    parser[k].update(v)
                else:
                    parser[k] = v
            visited.discard(inc_name)

        # Remove the include directive after processing
        parser.pop('include')

    for pname, pdict in parser_dict.items():
        _resolve(pname, pdict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # pull defaults from the spec object, if present
    if hasattr(self, "spec"):
        spec_obj = getattr(self, "spec")
        try:
            # try to use the spec object's attributes as defaults
            defaults.update(vars(spec_obj))
        except Exception:
            # if vars() fails or spec_obj has no __dict__, ignore
            pass
    # update with defaults defined on individual arguments/options
    if hasattr(self, "args"):
        for arg in getattr(self, "args"):
            # Argument objects are expected to have a `name` and optional `default` attribute
            try:
                name = getattr(arg, "name", None)
                if not name:
                    continue
                if hasattr(arg, "default"):
                    defaults[name] = arg.default
            except Exception:
                # If any unexpected attribute errors occur, skip this argument
                continue
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Helper to extract defaults from an iterable of arguments
    def _extract_from_args(arg_iter):
        for arg in arg_iter:
            try:
                # Skip non-option objects silently
                if not hasattr(arg, "name"):
                    continue
                # Use NoDefault sentinel if defined
                default_val = getattr(arg, "default", None)
                if default_val is not None and default_val is not getattr(arg, "NoDefault", default_val):
                    defaults[arg.name] = default_val
                # Recurse into nested dict options if a scheme is attached
                if hasattr(arg, "scheme") and arg.scheme:
                    nested = arg.scheme.get_spec_defaults()
                    if nested:
                        defaults[arg.name] = nested
            except Exception:
                # Continue with other arguments if an individual arg causes an error
                continue

    try:
        # Primary spec arguments
        arg_iter = getattr(self, "args", ())
        _extract_from_args(arg_iter)
    except Exception:
        # If getattr fails, silently ignore and rely on other sources
        pass

    try:
        # Fallback or additional defaults from a class-level "_default_spec" if present
        default_spec = getattr(self, "_default_spec", None)
        if default_spec:
            _extract_from_args(getattr(default_spec, "args", ()))
    except Exception:
        pass

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        for arg in getattr(self, "args", []):
            # Ensure the argument is a valid option instance
            if not hasattr(arg, "name"):
                continue

            value = None

            # 1. Primary source: self.spec
            if hasattr(self, "spec"):
                try:
                    value = getattr(self.spec, arg.name)
                except AttributeError:
                    value = None

            # 2. Secondary source: self._default_spec (if spec was not set)
            if value is None and hasattr(self, "_default_spec"):
                try:
                    value = getattr(self._default_spec, arg.name)
                except AttributeError:
                    value = None

            # 3. Fallback: default provided by the option itself
            if value is None:
                # If the option defines a default and it's not a sentinel value
                if hasattr(arg, "default") and not isinstance(arg.default, NoDefault):
                    value = arg.default

            # 4. Nested schemes (e.g., DictOption) – recurse if present
            if value is None and isinstance(arg, DictOption) and getattr(arg, "scheme", None):
                try:
                    nested = arg.scheme.get_spec_defaults()
                    if nested:
                        value = nested
                except Exception:
                    # In case nested resolution fails, skip it gracefully
                    value = None

            if value is not None:
                defaults[arg.name] = value
    except Exception as exc:
        # Provide a clear error if the resolution process fails unexpectedly
        raise errors.InvalidSpecError("Failed to resolve spec defaults") from exc

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}

    # Merge values from the primary spec
    spec = getattr(self, "spec", None)
    if spec is not None:
        try:
            for key, value in spec.items():
                defaults[key] = value
        except Exception:
            # If spec is not mapping-like, ignore
            pass

    # Merge values from the default spec (used in override_spec)
    dspec = getattr(self, "_default_spec", None)
    if dspec is not None:
        try:
            for key, value in dspec.items():
                defaults.setdefault(key, value)
        except Exception:
            pass

    # Fill in remaining defaults from the argument definitions
    for arg in getattr(self, "args", []):
        if not isinstance(arg, _BaseOpt):
            continue
        name = arg.name
        if name in defaults:
            continue
        # Use explicitly set default, if available
        if not isinstance(arg.default, NoDefault):
            defaults[name] = arg.default
        # Handle nested dictionary options
        elif isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            try:
                nested_defaults = arg.scheme.build_defaults()
                if nested_defaults:
                    defaults[name] = nested_defaults
            except Exception:
                pass

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Iterate over spec containers: primary spec and fallback default_spec
    for container in (getattr(self, 'spec', None), getattr(self, '_default_spec', None)):
        if container is None:
            continue
        try:
            if isinstance(container, dict):
                items = container.items()
            elif hasattr(container, "__dict__"):
                items = container.__dict__.items()
            else:
                # Attempt to convert to dict if possible
                items = dict(container).items()
        except Exception:
            continue
        for key, value in items:
            if not key.startswith("_") and value is not None:
                defaults[key] = value
    return defaults

