def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Verify that the incoming arguments are dictionaries
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve any deprecated argument mapping that the class may define.
    # The expected format is {old_arg_name: new_arg_name, ...}
    deprecated_map = getattr(self, "deprecated_args", {})
    if not isinstance(deprecated_map, dict) or not deprecated_map:
        # If no deprecated args are defined, nothing to do.
        return

    # Combine the arguments with command‑line taking precedence over the answer file.
    combined_args = {}
    combined_args.update(answer_file_args)
    combined_args.update(cli_args)

    # Track which deprecated arguments were found, grouped by the new argument name.
    found_deprecations = {}
    for old_arg, new_arg in deprecated_map.items():
        if old_arg in combined_args:
            found_deprecations.setdefault(new_arg, []).append(old_arg)

    # If we found any uses of deprecated arguments, report them.
    if found_deprecations:
        print("Deprecated arguments usage detected:")
        for new_arg, old_args in found_deprecations.items():
            old_list = ", ".join(old_args)
            print(f"  {old_list} -> {new_arg}")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Try to use a per-instance mapping if it exists
    if hasattr(self, "_command_options"):
        try:
            return list(self._command_options.get(command_name, []))
        except Exception:
            # Ignore errors and fall back to the default mapping below
            pass

    # Default mapping for known commands
    default_options = {
        "main": [
            {"name": "-h", "help": "Show help information"},
            {"name": "-v", "help": "Show version information"},
        ],
        "virsh": [
            {"name": "--connect", "help": "Specify the hypervisor connection URI"},
            {"name": "--domain", "help": "Target domain name or ID"},
        ],
