def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # The implementation is intentionally tolerant: if the command
    # specification cannot be found or does not expose a standard
    # ``options`` attribute, we return an empty list instead of
    # raising an exception. This keeps the method safe from misuse
    # of the public API while still fulfilling its contract.

    # Guard against a falsy command name – an explicit empty list
    # signals that there are no options to fetch.
    if not command_name:
        return []

    # Attempt to walk through the typical structures used in many CLI
    # frameworks. Most tools expose a mapping of command names to
    # objects that provide an ``options`` attribute or a
    # ``get_options`` method; if those are missing we fall back to
    # inspecting the attributes of the returned object.
    cmd_spec = None
    try:
        # Common storage pattern: an attribute ``self.commands`` is a dict
        if hasattr(self, "commands") and isinstance(self.commands, dict):
            cmd_spec = self.commands[command_name]
        # Another pattern: a method ``get_command`` that returns an object
        elif hasattr(self, "get_command") and callable(self.get_command):
            cmd_spec = self.get_command(command_name)
    except (KeyError, TypeError, AttributeError):
        # If the lookup fails, we simply return an empty list.
        return []

    # If we cannot find a spec, don't raise.
    if cmd_spec is None:
        return []

    # Prefer a direct ``options`` attribute.
    if hasattr(cmd_spec, "options") and isinstance(cmd_spec.options, (list, tuple)):
        return list(cmd_spec.options)

    # If the spec provides a method to fetch options, use it.
    if hasattr(cmd_spec, "get_options") and callable(cmd_spec.get_options):
        result = cmd_spec.get_options()
        if isinstance(result, (list, tuple)):
            return list(result)

    # Fallback: look for common attribute names.
    for possible in ("opts", "flags", "arguments"):
        if hasattr(cmd_spec, possible):
            attr = getattr(cmd_spec, possible)
            if isinstance(attr, (list, tuple)):
                return list(attr)

    # Final resort: introspect attributes starting with ``opt_`` or
    # ending with ``_option``.  This only works for simple, flat
    # specifications.
    discovered = []
    for attr_name in dir(cmd_spec):
        if attr_name.startswith("opt_") or attr_name.endswith("_option"):
            attr_val = getattr(cmd_spec, attr_name)
            if isinstance(attr_val, (list, tuple)):
                discovered.extend(attr_val)
            else:
                discovered.append(attr_val)
    return discovered

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name.strip():
        raise ValueError("command_name must be a non-empty string")

    parser = None

    # Try to locate the parser via a naming convention
    try:
        parser = getattr(self, f"{command_name}_parser", None)
    except Exception:
        parser = None

    # Fallback to a registry dictionary if defined
    if parser is None:
        try:
            registry = getattr(self, "command_parsers", {})
            parser = registry.get(command_name, None)
        except Exception:
            parser = None

    # If we couldn't find a parser, return an empty list
    if parser is None:
        return []

    # Extract option specifications
    try:
        # For argparse parsers, options are stored in _actions
        if hasattr(parser, "_actions"):
            return list(parser._actions)
        # For other parser types, they might expose a method or attribute
        if hasattr(parser, "get_option_list"):
            return list(parser.get_option_list())
        if hasattr(parser, "options"):
            return list(parser.options)
    except Exception:
        # In case of any error, return an empty list
        return []

    # Default fallback if nothing matched
    return []

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if command_name is None:
        raise ValueError("command_name cannot be None")
    if not isinstance(command_name, str):
        raise TypeError(f"command_name expected to be a string, got {type(command_name).__name__}")

    cleaned_name = command_name.strip().lower()
    if not cleaned_name:
        return []

    # Attempt to fetch the options mapping from the instance
    options_map = getattr(self, "_command_options", None)
    if options_map is None:
        # If the attribute does not exist, try alternate naming
        options_map = getattr(self, "command_options", None)
    if options_map is None or not isinstance(options_map, (dict, object)):
        # If we cannot determine the mapping, return empty list
        return []

    # If the mapping is a dict, fetch directly; otherwise, try attribute access
    try:
        if isinstance(options_map, dict):
            specs = options_map.get(cleaned_name, [])
        else:
            # Some implementations may expose a method to retrieve options by name
            try:
                # Try method named get_options_for
                method = getattr(options_map, "get_options_for", None)
                if callable(method):
                    specs = method(cleaned_name)
                else:
                    # Fallback to attribute
                    specs = getattr(options_map, cleaned_name, [])
            except Exception:
                specs = []
    except Exception:
        specs = []

    # Ensure the result is a list
    if not isinstance(specs, list):
        try:
            specs = list(specs)
        except Exception:
            specs = []

    return specs

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Retrieve the command-specific options dictionary.
    try:
        command_opts = self._option_spec.get(command_name)
    except AttributeError:
        raise AttributeError("The object has no '_option_spec' attribute")
    if command_opts is None:
        raise KeyError(f"Command '{command_name}' not found in option specifications")

    # Retrieve the specific argument specification.
    spec = command_opts.get(argument_name)
    if spec is None:
        raise KeyError(
            f"Option '{argument_name}' not found for command '{command_name}'"
        )

    return spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Attempt to retrieve the specification from the most common attribute names.
    # The exact attribute name may vary depending on the implementation.
    # We try several possibilities and raise a clear error if all fail.

    # 1. Check for a direct mapping: self._command_option_spec[cmd][opt]
    if hasattr(self, "_command_option_spec"):
        spec_map = getattr(self, "_command_option_spec")
        try:
            return spec_map[command_name][argument_name]
        except (KeyError, TypeError):
            pass

    # 2. Check for a nested spec under a "commands" dict
    if hasattr(self, "commands"):
        commands = getattr(self, "commands")
        try:
            cmd_specs = commands[command_name]
            # cmd_specs may have an "options" or "args" sub-dict
            if isinstance(cmd_specs, dict):
                for key in ("options", "args", "arguments"):
                    if key in cmd_specs:
                        return cmd_specs[key].get(argument_name)
        except (KeyError, TypeError):
            pass

    # 3. Check for a flat dictionary: self._specifications[cmd_opt]
    if hasattr(self, "_specifications"):
        flat_specs = getattr(self, "_specifications")
        try:
            # Try composite key
            composite_key = f"{command_name}:{argument_name}"
            if composite_key in flat_specs:
                return flat_specs[composite_key]
            # Try separate keys if stored as nested dict
            return flat_specs.get(command_name, {}).get(argument_name)
        except (KeyError, TypeError):
            pass

    # If all attempts fail, raise a helpful exception.
    raise KeyError(
        f"Option specification for command '{command_name}' and "
        f"argument '{argument_name}' could not be found."
    )

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Retrieve the command specifications dictionary
    try:
        command_specs = getattr(self, "_command_specs", {})
    except Exception:
        # If the attribute is missing or not accessible, return None
        return None

    # Get the spec for the requested command
    cmd_spec = command_specs.get(command_name)
    if cmd_spec is None:
        # Command not found
        return None

    # If no specific argument requested, return the whole command spec
    if argument_name == "":
        return cmd_spec

    # Return the spec for the specific argument, or None if it doesn't exist
    return cmd_spec.get(argument_name) if isinstance(cmd_spec, dict) else None

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Retrieve the container that holds all option specifications.
    # The implementation tries a few common attribute names to be tolerant
    # of different designs.
    spec_container = None
    for attr in ("_option_specs", "option_specs", "specs", "commands"):
        if hasattr(self, attr):
            spec_container = getattr(self, attr)
            break

    if spec_container is None:
        raise AttributeError(
            "Instance does not have a recognised attribute for option specs"
        )

    # The container should be a mapping: command_name -> {argument_name: spec}
    try:
        command_spec = spec_container[command_name]
    except (TypeError, KeyError):
        raise KeyError(f"Command '{command_name}' not found in option specifications")

    try:
        arg_spec = command_spec[argument_name]
    except (TypeError, KeyError):
        raise KeyError(
            f"Argument '{argument_name}' not found for command '{command_name}'"
        )

    return arg_spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Ensure args is a list-like structure
    if args is None:
        return []
    if isinstance(args, str):
        args = [args]
    # Use a predefined set of silent argument identifiers if available
    silent_set = getattr(self, "SILENT_ARGS", None)
    if silent_set is None:
        return []
    # Normalize potential sets/lists/tuples to a set for efficient lookup
    if not isinstance(silent_set, (set, list, tuple)):
        silent_set = {silent_set}
    else:
        silent_set = set(silent_set)
    return [arg for arg in args if arg in silent_set]

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Handle None or empty input
    if not args:
        return []

    # Attempt to convert argparse.Namespace to dict
    try:
        args_dict = vars(args)
    except Exception:
        args_dict = None

    silent = []
    seen = set()

    def _add(name):
        if name and name not in seen:
            seen.add(name)
            silent.append(name)

    # Process dict-like structure
    if isinstance(args_dict, dict):
        for key in args_dict:
            if isinstance(key, str):
                if key.startswith("--"):
                    _add(key[2:].split('=')[0])
                elif key.startswith("-"):
                    _add(key[1:])
    # Process list or tuple of strings
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, str):
                if item.startswith("--"):
                    _add(item[2:].split('=')[0])
                elif item.startswith("-"):
                    _add(item[1:])
    else:
        # Unsupported type: try to iterate as a sequence of strings
        try:
            for item in args:
                if isinstance(item, str):
                    if item.startswith("--"):
                        _add(item[2:].split('=')[0])
                    elif item.startswith("-"):
                        _add(item[1:])
        except Exception:
            pass

    return silent

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, silienced argument names
        """
        # defensive check: args should be an iterable of strings
        if args is None:
            return []
        try:
            iter(args)
        except TypeError as exc:
            raise TypeError("args must be an iterable") from exc

        silent = []
        for item in args:
            # preserve only string arguments that are options (start with '-')
            if isinstance(item, str) and item.startswith("-"):
                silent.append(item)
            # allow tuples of (option, value) where first element is option
            elif isinstance(item, (tuple, list)) and len(item) == 2:
                opt, _ = item
                if isinstance(opt, str) and opt.startswith("-"):
                    silent.append(opt)
        return silent

def validate_requires_args(self, args):
        """Check if all the required arguments have been provided."""
        # Determine the list of required argument names.
        try:
            required = self.required_args
        except AttributeError:
            raise AttributeError("Instance does not have a 'required_args' attribute.")
        if not isinstance(required, (list, tuple, set)):
            raise TypeError("'required_args' must be a sequence of argument names.")

        # The args argument should be a mapping of names to values.
        if not isinstance(args, dict):
            raise TypeError("'args' must be a dictionary mapping argument names to values.")

        # Identify any missing or unset required arguments.
        missing = [name for name in required if name not in args or args[name] is None]
        if missing:
            raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
        return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Get the list or set of required argument names.
    required = getattr(self, "required", None)
    if required is None:
        # If nothing is defined, nothing to validate.
        return
    # If required is a function, call it to get the iterable.
    if callable(required):
        required = required()
    # Normalize to a list.
    try:
        required_list = list(required)
    except TypeError:
        raise TypeError(
            "self.required must be an iterable or callable returning an iterable."
        )
    # Assume args is a mapping (e.g., dict). If it is a list/tuple,
    # treat it as positional arguments and skip positional checks.
    if not isinstance(args, (dict,)):
        # Nothing to validate against a mapping.
        return
    missing = []
    for name in required_list:
        if name not in args or args[name] is None:
            missing.append(name)
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")
    # Return True to indicate successful validation.
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required_names = []

        # Helper to evaluate a single condition
        def _eval_condition(condition):
            try:
                # If condition is a mapping, look up by command_name
                if isinstance(condition, dict):
                    # Expect mapping: command_name -> bool or callable
                    val = condition.get(command_name, False)
                    if callable(val):
                        return bool(val(args))
                    return bool(val)

                # If condition is callable, call it with args
                if callable(condition):
                    return bool(condition(args))

                # If condition is a string, interpret as Python expression
                if isinstance(condition, str):
                    # Create environment with args and command_name
                    env = {'command_name': command_name}
                    if isinstance(args, dict):
                        env.update(args)
                    return bool(eval(condition, {}, env))

                # Fallback: interpret truthiness directly
                return bool(condition)
            except Exception:
                # On any error, treat condition as not met
                return False

        for opt in options_spec:
            # Extract the option name
            name = None
            if isinstance(opt, dict):
                name = opt.get('name')
                condition = opt.get('required_when')
            else:
                name = getattr(opt, 'name', None)
                condition = getattr(opt, 'required_when', None)

            if not name or condition is None:
                continue

            if _eval_condition(condition):
                required_names.append(name)

        return required_names

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []

    # Normalize args to a dictionary if required
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}

    for opt in options_spec:
        if not isinstance(opt, dict):
            continue  # skip invalid spec entries

        cond = opt.get("required_when")
        if cond is None:
            continue

        # Determine option name; prefer 'name', fallback to 'dest' or 'arg'
        opt_name = opt.get("name") or opt.get("dest") or opt.get("arg")
        if not opt_name:
            # cannot determine option name; skip
            continue

        satisfied = False
        try:
            if callable(cond):
                # try both signatures: (command_name, args) or (args)
                try:
                    satisfied = bool(cond(command_name, args))
                except TypeError:
                    satisfied = bool(cond(args))
            elif isinstance(cond, (list, tuple)):
                # list/tuple expected as conditions: (key, value)
                satisfied = True
                for item in cond:
                    if not isinstance(item, (list, tuple)) or len(item) != 2:
                        continue
                    key, expected = item
                    if args.get(key) != expected:
                        satisfied = False
                        break
            elif isinstance(cond, dict):
                satisfied = all(args.get(k) == v for k, v in cond.items())
            else:
                # any truthy value marks condition satisfied
                satisfied = bool(cond)
        except Exception:
            satisfied = False

        if satisfied:
            required.append(opt_name)

    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.
    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for opt in options_spec:
        if not isinstance(opt, dict):
            continue
        cond = opt.get('required_when')
        if cond is None:
            continue
        name = opt.get('name') or opt.get('arg')
        if not name:
            continue
        try:
            if callable(cond):
                if cond(command_name, args):
                    required.append(name)
            else:
                # Interpret simple string conditions
                # e.g., "opt1,opt2=1,opt3=val"
                if isinstance(cond, str):
                    if not isinstance(args, dict):
                        # cannot evaluate string condition without dict args
                        continue
                    all_met = True
                    for part in [c.strip() for c in cond.split(',') if c.strip()]:
                        if '=' in part:
                            key, val = part.split('=', 1)
                            if args.get(key) != val:
                                all_met = False
                                break
                        else:
                            if part not in args:
                                all_met = False
                                break
                    if all_met:
                        required.append(name)
        except Exception:
            # Ignore errors from condition evaluation
            pass
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Expect options to be dictionaries. Skip otherwise.
        if not isinstance(opt, dict):
            continue
        cond = opt.get("required_when")
        if cond is None:
            continue

        try:
            # If the condition is callable, try to call it with args
            # and optionally command_name.
            if callable(cond):
                try:
                    result = cond(args, command_name=command_name)
                except TypeError:
                    result = cond(args)
            else:
                # Non-callable conditions are interpreted as truthy/falsy.
                result = bool(cond)
        except Exception:
            # If the condition raises, treat it as not satisfied.
            result = False

        if result:
            # Prefer the 'arg' key, fall back to 'name', and if none, skip.
            key = opt.get("arg") or opt.get("name")
            if key:
                required.append(key)
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Normalise the representation of received arguments for easy lookup
    try:
        # if args is a dict-like object
        args_lookup = set(args.keys())
    except AttributeError:
        # otherwise assume it is an iterable of positional values
        args_lookup = set(args)

    required = []
    for opt in options_spec:
        # Determine the identifier of the option; fall back to any key that likely
        # identifies the option.
        opt_name = opt.get("name") or opt.get("arg") or opt.get("id")
        if not opt_name:
            continue

        cond = opt.get("required_when")
        if not cond:
            continue

        matched = False
        # Direct command name list
        if isinstance(cond, (list, tuple, set)):
            if command_name in cond:
                matched = True
            else:
                # some specs might list conditions as tuples (command, extra)
                for item in cond:
                    if isinstance(item, (tuple, list)):
                        if command_name == item[0]:
                            matched = True
                            break
        # Callable condition
        elif callable(cond):
            try:
                if cond(command_name, args):
                    matched = True
            except Exception:
                # ignore any errors in user-provided callable
                matched = False
        # Dict-based condition
        elif isinstance(cond, dict):
            cmd = cond.get("command")
            if cmd and command_name == cmd:
                # further filter by args presence
                arg_cond = cond.get("args")
                if arg_cond:
                    # ensure iterable
                    if not isinstance(arg_cond, (list, tuple, set)):
                        arg_cond = [arg_cond]
                    if any(a in args_lookup for a in arg_cond):
                        matched = True
                else:
                    matched = True
        # Truthy single value
        elif cond:
            matched = True

        if matched and opt_name not in required:
            required.append(opt_name)

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # No arguments to validate
    if not args:
        return

    # Acquire argument specifications from the parsed YAML if available
    arg_specs = {}
    try:
        arg_specs = self.parsed_yaml.get('args', {})
    except AttributeError:
        # Safe guard if parsed_yaml or args key not present
        pass

    # Normalize args into a list of (name, value) tuples
    items = []
    if isinstance(args, dict):
        items = list(args.items())
    elif isinstance(args, list):
        for element in args:
            if isinstance(element, dict):
                items.extend(element.items())
    else:
        # Unsupported type: ignore validation
        return

    for arg_name, value in items:
        # Skip arguments without a value
        if value is None:
            continue

        # Retrieve max_length constraint if defined
        spec = arg_specs.get(arg_name, {})
        maxlen = spec.get('max_length')
        if maxlen is None:
            continue

        # Ensure maxlen is a non-negative integer
        if not isinstance(maxlen, int) or maxlen < 0:
            raise ValueError(
                f"Invalid max_length for argument '{arg_name}': {maxlen}"
            )

        # Measure the length of the value as a string
        try:
            length = len(str(value))
        except Exception:
            # If conversion to string fails, skip the check
            continue

        if length > maxlen:
            raise ValueError(
                f"Argument '{arg_name}' exceeds maximum length of {maxlen} characters (got {length})."
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve configuration for each argument from parsed YAML if available
    arg_configs = getattr(self, 'parsed_yaml', {}).get('args', {})
    if not isinstance(arg_configs, dict):
        return  # nothing to validate

    for arg_name, value in args.items():
        # Get length constraint for this argument if it exists
        config = arg_configs.get(arg_name, {})
        expected_len = config.get('length')

        # Skip if no length constraint defined
        if expected_len is None:
            continue

        # Skip validation for None values
        if value is None:
            continue

        # Determine the actual length; skip if object has no length
        try:
            actual_len = len(value)
        except TypeError:
            continue

        # Verify that expected_len is a non-negative integer
        if not isinstance(expected_len, Integral):
            raise TypeError(
                f"Expected length for argument '{arg_name}' must be an int (got {type(expected_len).__name__})"
            )
        if expected_len < 0:
            raise ValueError(
                f"Expected length for argument '{arg_name}' must be non-negative (got {expected_len})"
            )

        if actual_len > expected_len:
            raise ValueError(
                f"Argument '{arg_name}' value is too long: {actual_len} exceeds allowed length {expected_len}"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a dict or a list of single-key dicts
    if args is None:
        return
    if isinstance(args, dict):
        arg_items = list(args.items())
        arg_map = args
    elif isinstance(args, list):
        arg_items = []
        for item in args:
            if not isinstance(item, dict) or len(item) != 1:
                raise TypeError(
                    "Each list element must be a single‑key dict representing an argument"
                )
            arg_items.append(list(item.items())[0])
        arg_map = {name: value for name, value in arg_items}
    else:
        raise TypeError("Argument must be a dict or a list of single‑key dicts")

    # Retrieve argument definitions from the parsed specification.
    # The attribute may be named differently; we try common names.
    arg_specs = getattr(self, "arg_specs", {})
    if not isinstance(arg_specs, dict):
        # Fallback: try to locate arguments spec inside parsed YAML
        arg_specs = getattr(self, "parsed_yaml", {}).get("args", {})
        if not isinstance(arg_specs, dict):
            # Nothing to validate against
            return

    # Helper to extract maximum length spec from an argument's definition.
    def _max_length_from_spec(spec):
        if not isinstance(spec, dict):
            return None
        # Common keys that may contain length information.
        for key in ("max", "max_length", "length"):
            if key in spec:
                value = spec[key]
                if isinstance(value, int) and value >= 0:
                    return value
                break
        return None

    # Validate each provided argument against its maximum length.
    for name, value in arg_items:
        spec = arg_specs.get(name)
        if spec is None:
            continue
        max_len = _max_length_from_spec(spec)
        if max_len is None:
            continue
        # Skip validation for None or non‑sequenced values.
        if value is None:
            continue
        try:
            current_len = len(value)
        except Exception:
            continue  # Value is not length‑measurable; ignore in this check
        if current_len > max_len:
            raise ValueError(
                f"Argument '{name}' exceeds maximum length of {max_len} "
                f"(got {current_len})"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure we have a mapping of argument specifications
    arg_specs = getattr(self, "parsed_yaml", {}).get("args", {})
    if not isinstance(arg_specs, dict):
        raise TypeError(
            "argument specifications must be a dict (got %s)" % type(arg_specs).__name__
        )

    if args is None:
        raise ValueError("args cannot be None")

    # If args is a list, we expect it to be a sequence of (name, value) tuples
    if isinstance(args, list):
        try:
            # Convert list of tuples into a dict for easier handling
            args = {name: value for name, value in args}
        except Exception as exc:
            raise TypeError(
                "args list must contain (name, value) pairs: %s" % exc
            )

    if not isinstance(args, dict):
        raise TypeError(
            "args must be a dict or list of (name, value) pairs (got %s)" % type(args).__name__
        )

    for arg_name, arg_value in args.items():
        spec = arg_specs.get(arg_name)
        if spec is None:
            # No length constraint for this argument; skip
            continue

        # Retrieve the expected length specification
        expected_len = spec.get("len")
        if expected_len is None:
            # Nothing to check
            continue

        # Determine the actual length of the value
        try:
            actual_len = len(arg_value)
        except Exception:
            # If the value has no length, skip validation
            continue

        # Handle different forms of expected length specification
        if isinstance(expected_len, (list, tuple)):
            if len(expected_len) != 2:
                raise ValueError(
                    f"length spec for argument '{arg_name}' must be a single int or a (min, max) tuple"
                )
            min_len, max_len = expected_len
            if not all(isinstance(x, (int, float)) for x in (min_len, max_len)):
                raise TypeError(
                    f"length bounds for argument '{arg_name}' must be numeric"
                )
            if actual_len < min_len or actual_len > max_len:
                raise ValueError(
                    f"length of argument '{arg_name}' is {actual_len}, but must be between "
                    f"{min_len} and {max_len}"
                )
        else:
            if not isinstance(expected_len, (int, float)):
                raise TypeError(
                    f"length spec for argument '{arg_name}' must be numeric (got {type(expected_len).__name__})"
                )
            if actual_len > expected_len:
                raise ValueError(
                    f"length of argument '{arg_name}' is {actual_len}, but must not exceed {expected_len}"
                )

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument name to value")

    # Try to retrieve the argument definitions that contain possible choices.
    # The concrete attribute name may vary; common patterns are 'arg_defs'
    # or 'choices'.
    arg_defs = getattr(self, 'arg_defs', {})
    choices_map = getattr(self, 'choices', {})

    # Merge definitions from both possible sources if they exist.
    if not arg_defs and choices_map:
        arg_defs = {name: {'choices': val} for name, val in choices_map.items()}

    for arg_name, arg_value in args.items():
        # Get the definition for this argument.
        definition = arg_defs.get(arg_name) if arg_defs else None

        # If the definition has a 'choices' entry, enforce it.
        if definition and 'choices' in definition:
            allowed = definition['choices']
            # Accept iterable values (for multi-valued options).
            if isinstance(arg_value, (list, tuple)):
                for val in arg_value:
                    if val not in allowed:
                        raise ValueError(
                            f"Invalid value for argument '{arg_name}': "
                            f"{val!r}. Must be one of {allowed!r}.")
            else:
                if arg_value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': "
                        f"{arg_value!r}. Must be one of {allowed!r}.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError("args must be a dict, got %s" % type(args).__name__)

    # Fetch choice definitions, default to empty dict if not present
    choice_defs = getattr(self, "choices", {})
    if not isinstance(choice_defs, dict):
        raise TypeError("self.choices must be a dict, got %s" % type(choice_defs).__name__)

    for name, value in args.items():
        if name in choice_defs:
            allowed = choice_defs[name]
            # Allow the allowed choices to be any iterable of valid values
            try:
                # Create a set for efficient membership checking
                allowed_set = set(allowed)
            except TypeError:
                # If allowed is not iterable, it is treated as a single valid value
                allowed_set = {allowed}

            if value not in allowed_set:
                raise ValueError(
                    f"Invalid value for '{name}': {value!r}. "
                    f"Must be one of {sorted(allowed_set)!r}."
                )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.
    The *args* argument should be an iterable of tuples, each containing
    (value, minimum, maximum) in that order.  Alternatively it can be a
    mapping where each item maps a key to a tuple of the same
    structure.  The method validates that *minimum* is not greater than
    *maximum* and that *value* is within [minimum, maximum].
    Any invalid input raises an exception.  If all arguments are valid,
    the original *args* object is returned unchanged.
    """
    # Allow mapping or iterable of tuples
    if isinstance(args, dict):
        items = args.items()
    else:
        items = enumerate(args)

    for key, item in items:
        try:
            value, minimum, maximum = item
        except Exception:
            raise TypeError(
                f"Argument {key!r} must be a tuple of (value, min, max); got {item!r}"
            )

        # Ensure minimum <= maximum
        try:
            if minimum > maximum:
                raise ValueError
        except TypeError:
            raise TypeError(
                f"Minimum and maximum for argument {key!r} must be comparable "
                f"types; got {minimum!r} and {maximum!r}"
            )

        # Ensure value is within bounds
        try:
            if not (minimum <= value <= maximum):
                raise ValueError
        except TypeError:
            raise TypeError(
                f"Value for argument {key!r} must be comparable with "
                f"its bounds; got {value!r}"
            )

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Expected to be a mapping of argument names
                 to values.
    :raises ValueError: If any argument's value is outside the allowed range.
    :raises TypeError: If ``args`` is not a mapping or if values are not comparable
                       to their min/max bounds.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    for name, value in args.items():
        # Skip arguments without explicit bounds on the instance
        min_attr = f"{name}_min"
        max_attr = f"{name}_max"
        if not hasattr(self, min_attr) or not hasattr(self, max_attr):
            continue

        min_val = getattr(self, min_attr)
        max_val = getattr(self, max_attr)

        # Validate that bounds themselves are sensible
        if min_val > max_val:
            raise ValueError(f"Invalid bounds for '{name}': min {min_val} > max {max_val}")

        try:
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument '{name}'={value} is out of range [{min_val}, {max_val}]"
                )
        except TypeError as exc:
            raise TypeError(
                f"Argument '{name}'={value} and its bounds must be comparable types"
            ) from exc

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.  ``args`` should be an iterable
    of either ``(value, min, max)`` tuples/lists or dictionaries with the
    keys ``'value'``, ``'min'`` and ``'max'``.
    :return: ``args`` if all values lie within their bounds.
    :raise TypeError, ValueError: If ``args`` is malformed or a value is
    outside its specified bounds.
    """
    # Ensure we have an iterable that's not a string/bytes
    if not hasattr(args, "__iter__") or isinstance(args, (str, bytes)):
        raise TypeError("args must be an iterable of arguments")

    # List to hold validated items if we need to return a new list
    validated = []

    for idx, item in enumerate(args):
        # Extract value, min and max from dict or tuple/list
        if isinstance(item, dict):
            try:
                value = item["value"]
                min_ = item["min"]
                max_ = item["max"]
            except KeyError as exc:
                raise KeyError(
                    f"Argument {idx} dictionary missing key {exc.args[0]}"
                )
        elif isinstance(item, (list, tuple)):
            if len(item) != 3:
                raise ValueError(
                    f"Argument {idx} must be a three-element tuple/list"
                )
            value, min_, max_ = item
        else:
            raise TypeError(
                f"Argument {idx} must be a dict or a three-element tuple/list"
            )

        # Convert to numeric types
        try:
            val = float(value)
            mn = float(min_)
            mx = float(max_)
        except (TypeError, ValueError):
            raise TypeError(
                f"All elements of argument {idx} must be convertible to float"
            )

        if mn > mx:
            raise ValueError(
                f"Argument {idx} has min ({mn}) greater than max ({mx})"
            )
        if not (mn <= val <= mx):
            raise ValueError(
                f"Argument {idx} value {val} not in range [{mn}, {mx}]"
            )

        validated.append(item)

    return validated

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raises AttributeError: If ``min_`` or ``max_`` attributes are missing.
    :raises TypeError: If any argument is not numeric.
    :raises ValueError: If any argument is outside the allowed range.
    :return: The original ``args`` if all checks pass.
    """
    # Ensure that min_ and max_ exist on the instance
    if not hasattr(self, "min_") or not hasattr(self, "max_"):
        raise AttributeError(
            "Instance must have 'min_' and 'max_' attributes before validation"
        )

    min_val = getattr(self, "min_")
    max_val = getattr(self, "max_")

    # Validate the relationship between min and max
    if (min_val is not None) and (max_val is not None) and (min_val > max_val):
        raise ValueError(
            f"Instance min_ ({min_val}) must be less than or equal to max_ ({max_val})"
        )

    # Attempt to iteratively validate each argument
    try:
        for idx, value in enumerate(args):
            # Ignore ``None`` values – they are considered unbounded
            if value is None:
                continue

            # Convert to float to check numeric status
            try:
                numeric = float(value)
            except Exception as exc:
                raise TypeError(
                    f"Argument at position {idx} ({value!r}) is not numeric"
                ) from exc

            # Minimum check
            if min_val is not None and numeric < min_val:
                raise ValueError(
                    f"Argument at position {idx} ({numeric}) is below the allowed minimum ({min_val})"
                )

            # Maximum check
            if max_val is not None and numeric > max_val:
                raise ValueError(
                    f"Argument at position {idx} ({numeric}) exceeds the allowed maximum ({max_val})"
                )
    except TypeError as init_exc:
        # Handle situation where ``args`` is not iterable
        raise TypeError(
            f"Invalid 'args' provided - expected an iterable of values, got {type(args)!r}"
        ) from init_exc

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is an iterable
    try:
        args = list(args)
    except TypeError as exc:
        raise TypeError("args must be an iterable of values") from exc

    # Determine global min and max constraints, if present
    min_val = getattr(self, "min_value", None)
    max_val = getattr(self, "max_value", None)

    if min_val is None and max_val is None:
        # No constraints to apply
        return args

    for idx, value in enumerate(args):
        # Skip None values
        if value is None:
            continue

        # Accept numeric types only
        if not isinstance(value, (int, float)):
            raise TypeError(
                f"Argument at position {idx} ({value!r}) is not numeric and cannot be compared to min/max values"
            )

        if min_val is not None and value < min_val:
            raise ValueError(
                f"Argument at position {idx} ({value!r}) is less than the minimum allowed ({min_val!r})"
            )
        if max_val is not None and value > max_val:
            raise ValueError(
                f"Argument at position {idx} ({value!r}) exceeds the maximum allowed ({max_val!r})"
            )

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non‑empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non‑empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non‑empty string")
    if spec_option is None:
        spec_option = {}
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary")

    # Resolve the constructor for the complex type
    type_ctor = None
    # First try built‑in types
    try:
        type_ctor = getattr(__builtins__, type_name)
    except AttributeError:
        pass

    # If not found, fall back to registered custom types
    if type_ctor is None:
        type_ctor = getattr(self, "get_type", lambda x: None)(type_name)
        if type_ctor is None:
            raise ValueError(f"Unknown complex type: {type_name}")

    # Create the complex type instance
    try:
        return type_ctor(subcommand, option_name, **spec_option)
    except Exception as exc:  # pragma: no cover
        raise ValueError(
            f"Error creating complex type '{type_name}' for option '{option_name}': {exc}"
        ) from exc

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Default to empty dicts if no arguments provided
    if not args:
        return {}, {}

    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary, got %r" % type(args).__name__)

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if not isinstance(key, str):
            raise TypeError("Argument keys must be strings, got %r" % type(key).__name__)

        # Detect control arguments by a 'control_' prefix.
        # Custom arguments are treated as nested arguments by default.
        if key.startswith('control_'):
            # Strip the prefix for the control arguments dictionary
            control_key = key[len('control_') :]
            control_args[control_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list or dict of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Normalise to a dict
    if args is None:
        return {}, {}
    if isinstance(args, dict):
        arg_dict = args.copy()
    elif isinstance(args, (list, tuple)):
        try:
            arg_dict = dict(args)
        except Exception:
            # fall back to empty if conversion fails
            return {}, {}
    else:
        # Unsupported type
        return {}, {}

    control_args = {}
    nested_args = {}

    # Define prefixes for control and custom arguments
    CONTROL_PREFIXES = ("control_", "ir_", "debug_", "verbose_", "silent_", "logging_")
    CUSTOM_PREFIX = "custom_"

    def flatten_dict(d, parent_key='', sep='_'):
        """
        Flatten a nested dictionary using underscore separators.
        """
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(flatten_dict(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    for key, value in list(arg_dict.items()):
        # Skip None values
        if value is None:
            continue

        # Handle custom arguments first, they override nested
        if isinstance(key, str) and key.startswith(CUSTOM_PREFIX):
            # Strip the custom prefix and treat as a nested key
            custom_key = key[len(CUSTOM_PREFIX) :]
            # Flatten if the custom value is a dict
            if isinstance(value, dict):
                flat_custom = flatten_dict(value)
                for ck, cv in flat_custom.items():
                    nested_args[f"{custom_key}_{ck}".replace("__", "_")] = cv
            else:
                nested_args[custom_key] = value
            # Remove from original to avoid duplicate
            arg_dict.pop(key, None)
            continue

    # After handling custom args, process remaining keys
    for key, value in arg_dict.items():
        if isinstance(key, str) and key.startswith(CONTROL_PREFIXES):
            control_args[key] = value
        else:
            # Normalize nested values if they are dicts
            if isinstance(value, dict):
                flat_nested = flatten_dict(value)
                for nk, nv in flat_nested.items():
                    nested_args[f"{key}_{nk}".replace("__", "_")] = nv
            else:
                nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalize args to an iterable of key/value pairs
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        # Expect list of two-element tuples/lists
        items = args
    else:
        raise ValueError("args must be a dict or list/tuple of key/value pairs")

    for item in items:
        # Skip invalid items
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            continue
        key, value = item
        if not isinstance(key, str):
            continue

        if key.startswith("control_"):
            control_key = key[len("control_") :]
            control_args[control_key] = value
        elif key.startswith("custom_"):
            # Custom args are treated as nested but override normal nested usage
            nested_key = key[len("custom_") :]
            nested_args[nested_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Determine control keys. Use an attribute if present,
    # otherwise fall back to keys prefixed with "control_".
    control_keys = getattr(self, "control_keys", None)
    if control_keys is None:
        control_keys = {k for k in args if isinstance(k, str) and k.startswith("control_")}
    elif not isinstance(control_keys, (set, list)):
        raise TypeError("self.control_keys must be a set or list of keys")

    control_args = {}
    nested_args = {}
    for key, value in args.items():
        if key in control_keys:
            control_args[key] = value
        elif isinstance(key, str) and key.startswith("custom_"):
            nested_key = key[len("custom_") :]
            nested_args[nested_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of dictionaries containing extra variables
    :returns: the updated vars_dict
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # Accept a single dictionary as extra_vars
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    elif not isinstance(extra_vars, (list, tuple)):
        raise ValueError("extra_vars must be a dict, list, or tuple")

    for item in extra_vars:
        if not isinstance(item, dict):
            raise ValueError("Each item in extra_vars must be a dictionary")
        vars_dict.update(item)

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if not extra_vars:
            return vars_dict
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
        elif isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                if isinstance(item, dict):
                    vars_dict.update(item)
                elif isinstance(item, str) and '=' in item:
                    key, _, value = item.partition('=')
                    vars_dict[key] = value
                else:
                    raise ValueError(f"Unsupported item type in extra_vars: {type(item)}")
        else:
            raise TypeError("extra_vars must be a dict or a list/tuple")
        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    # If no extra vars, return the original dictionary unchanged
    if extra_vars is None:
        return vars_dict

    # Merge when extra_vars is a dictionary
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    # Merge when extra_vars is a list of dicts or key=value strings
    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                key, sep, val = item.partition('=')
                if sep:  # only if the string contains '='
                    vars_dict[key] = val
    # If extra_vars is a single dict-like or string, attempt to merge directly
    elif isinstance(extra_vars, str):
        key, sep, val = extra_vars.partition('=')
        if sep:
            vars_dict[key] = val
    elif isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (``dict``, ``list`` of ``dict`` or ``str`` in ``key=value`` format)
    :return: Updated ``vars_dict``

    The function accepts ``extra_vars`` in several common shapes:
    * ``dict`` – merged directly into ``vars_dict`` (overriding existing keys).
    * ``list`` of ``dict`` – each dict is merged in order.
    * ``list`` of ``str`` – each string is parsed as ``key=value`` (comma separated) and merged.
    * ``str`` – parsed as ``key=value`` pairs separated by commas.
    """
    # Basic validation of the base dictionary.
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    # Nothing to merge.
    if extra_vars is None:
        return vars_dict

    def _apply_mapping(mapping):
        if not isinstance(mapping, dict):
            raise TypeError(f"Mapping must be a dict, got {type(mapping).__name__}")
        vars_dict.update(mapping)

    # Handle the various accepted forms of extra_vars.
    if isinstance(extra_vars, dict):
        _apply_mapping(extra_vars)

    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                _apply_mapping(item)
            elif isinstance(item, str):
                # Parse comma-separated key=value pairs.
                for pair in item.split(','):
                    if '=' in pair:
                        key, val = pair.split('=', 1)
                        vars_dict[key.strip()] = val.strip()
                    else:
                        raise ValueError(f"Invalid extra_var string '{pair}': missing '='")
            else:
                raise TypeError(f"Unsupported element type in extra_vars list: {type(item).__name__}")

    elif isinstance(extra_vars, str):
        # Parse top-level string as key=value pairs separated by commas.
        for pair in extra_vars.split(','):
            if '=' in pair:
                key, val = pair.split('=', 1)
                vars_dict[key.strip()] = val.strip()
            else:
                raise ValueError(f"Invalid extra_var string '{pair}': missing '='")

    else:
        raise TypeError(f"Unsupported type for extra_vars: {type(extra_vars).__name__}")

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments that need type conversion
    :returns: The converted values_dict (modified in place)
    """
    # Helper function to convert a single value
    def _convert_value(val):
        if isinstance(val, str):
            s = val.strip()
            # Boolean
            lowered = s.lower()
            if lowered in {"true", "false"}:
                return lowered == "true"
            # Integer
            try:
                if s.startswith("0x") or s.startswith("0X"):
                    return int(s, 16)
                return int(s)
            except ValueError:
                pass
            # Float
            try:
                return float(s)
            except ValueError:
                pass
            # List separated by commas
            if "," in s:
                return [_convert_value(item.strip()) for item in s.split(",")]
            return s
        # If it's already a list, convert each element
        if isinstance(val, list):
            return [_convert_value(item) for item in val]
        # Return the value unchanged for other types
        return val

    # Convert all values in the dict
    for key in list(values_dict.keys()):
        try:
            values_dict[key] = _convert_value(values_dict[key])
        except Exception:
            # If conversion fails, leave the original value
            pass

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    # If no values_dict or it's not a dict, nothing to do.
    if not isinstance(values_dict, dict):
        return

    # Retrieve a mapping of argument names to the desired types for this parser.
    # The mapping can be stored on the instance as '_parser_arg_types' or similar.
    # If not present, use an empty mapping which will skip conversion.
    type_mapping = getattr(self, "_parser_arg_types", {}).get(parser_name, {})

    for key, val in list(values_dict.items()):
        target_type = type_mapping.get(key)
        if target_type is None:
            continue  # No conversion desired for this argument.

        try:
            # Special handling for booleans represented as strings.
            if target_type is bool:
                if isinstance(val, str):
                    lowered = val.lower()
                    if lowered in ("true", "1", "yes", "on"):
                        casted = True
                    elif lowered in ("false", "0", "no", "off"):
                        casted = False
                    else:
                        casted = bool(val)
                else:
                    casted = bool(val)

            # For other types, attempt direct conversion.
            else:
                casted = target_type(val)

            values_dict[key] = casted

        except Exception:
            # If conversion fails, preserve the original value.
            continue

