        # The parser_name is currently unused, but kept for potential future use.
        for key, value in list(values_dict.items()):
            # Only attempt conversion on string values
            if isinstance(value, str):
                # Trim whitespace
                stripped = value.strip()
                lower_val = stripped.lower()

                # Boolean conversion
                if lower_val in ("true", "false"):
                    values_dict[key] = lower_val == "true"
