                        if '.' not in stripped and not stripped.lower().endswith('e'):
                            values_dict[key] = int(stripped)
                        else:
                            raise ValueError
                    continue
                except ValueError:
                    pass

                # Float conversion
                try:
                    values_dict[key] = float(stripped)
                    continue
                except ValueError:
                    pass

                # List conversion (comma separated)
                if "," in stripped:
                    items = [item.strip() for item in stripped.split(",")]
                    converted_items = []
                    for item in items:
                        l = item.lower()
                        try:
                            # Attempt boolean
                            if l in ("true", "false"):
                                converted_items.append(l == "true")
                            # Attempt integer
                            elif item.startswith(("0x", "0X")):
                                converted_items.append(int(item, 16))
                            else:
                                # Try int, fallback to float, else keep as string
                                try:
                                    converted_items.append(int(item))
                                except ValueError:
                                    try:
                                        converted_items.append(float(item))
                                    except ValueError:
                                        converted_items.append(item)
                        except Exception:
                            # If any unexpected error, keep original string
                            converted_items.append(item)
                    values_dict[key] = converted_items
                    continue

                # If none of the above, keep original string
        # The function mutates values_dict in place; return it for convenience.
        return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir or the plugin.json file itself.
    :return: A flatten dictionary contains the plugin's properties.
    """
    import json
    import os

    # Resolve the path: if a directory is given, look for plugin.json inside it;
    # otherwise assume the passed path is the spec file itself.
    spec_path = plugin_dir
    if os.path.isdir(plugin_dir):
        spec_path = os.path.join(plugin_dir, "plugin.json")

    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"Plugin spec not found: {spec_path}")

    try:
        with open(spec_path, "r", encoding="utf-8") as fp:
            spec = json.load(fp)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in {spec_path}: {exc}") from exc
    except OSError as exc:
        raise IOError(f"Could not read plugin spec {spec_path}: {exc}") from exc

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten_dict(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten_dict(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Determine candidate spec filenames
    candidate_files = ['spec.json', 'plugin.json', 'spec.yaml', 'plugin.yaml']
    spec_path = None

    if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
        return {}

    for fname in candidate_files:
        potential_path = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential_path):
            spec_path = potential_path
            break

    if spec_path is None:
        return {}

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith('.json'):
                data = json.load(f)
            else:
                # Attempt to parse as YAML
                try:
                    import yaml
                    data = yaml.safe_load(f)
                except Exception:
                    # Fallback to JSON if YAML parsing fails
                    f.seek(0)
                    data = json.load(f)
    except Exception:
        return {}

    if not isinstance(data, dict):
        return {}

    return _flatten_dict(data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from pathlib import Path
    import json

    # Resolve directory path
    dir_path = Path(plugin_dir)
    if not dir_path.is_dir():
        raise FileNotFoundError(f"Plugin directory not found: {plugin_dir}")

    # Search for common spec file names
    spec_file = None
    for filename in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = dir_path / filename
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load spec content
    try:
        with spec_file.open("r", encoding="utf-8") as f:
            if spec_file.suffix == ".json":
                spec_data = json.load(f)
            else:
                # Try YAML if available; otherwise fallback to JSON
                try:
                    import yaml  # type: ignore
                    spec_data = yaml.safe_load(f)
                except Exception:
                    f.seek(0)
                    spec_data = json.load(f)
    except Exception as exc:
        raise ValueError(f"Unable to load spec file {spec_file}: {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError(f"Spec file must contain a JSON/YAML object at top level, got {type(spec_data)}")

    # Flatten nested dicts/lists into dotted keys
    def _flatten(value, parent_key=""):
        items = {}
        if isinstance(value, dict):
            for k, v in value.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                items.update(_flatten(v, new_key))
        elif isinstance(value, list):
            for idx, elem in enumerate(value):
                new_key = f"{parent_key}.{idx}" if parent_key else str(idx)
                items.update(_flatten(elem, new_key))
        else:
            items[parent_key] = value
        return items

    return _flatten(spec_data)

