    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Validate directory
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Expected a directory path, got: {plugin_dir}")

    # Determine spec file (support yaml or json)
    spec_file = None
    for fname in ("plugin.yaml", "plugin.yml", "plugin.json", "spec.yaml", "spec.yml", "spec.json"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if not spec_file:
        raise FileNotFoundError("No plugin specification file found in the directory.")

    # Load spec
    try:
        if spec_file.endswith(('.yaml', '.yml')):
            with open(spec_file, 'r', encoding='utf-8') as f:
                spec = yaml.safe_load(f)
        else:
            with open(spec_file, 'r', encoding='utf-8') as f:
                spec = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load spec file '{spec_file}': {exc}") from exc

    if not isinstance(spec, dict):
        raise ValueError("Spec file must contain a top-level dictionary.")

    # Flatten nested dict
    def _flatten(obj, parent_key=''):
        flat = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                flat.update(_flatten(v, new_key))
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                new_key = f"{parent_key}[{idx}]" if parent_key else f"[{idx}]"
                flat.update(_flatten(item, new_key))
        else:
            flat[parent_key] = obj
        return flat

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    # Retrieve current value; if none, set it from the instance
    try:
        current = os.environ.get(env_var)
    except Exception:
        # If environment variables cannot be accessed for some reason, skip injection
        return
    if current is None:
        # Only set if the instance has a valid config_path attribute
        if hasattr(self, 'config_path') and self.config_path:
            os.environ[env_var] = str(self.config_path)  # Convert to string in case of Path
        else:
            # If no config_path is available, do not set anything
            pass

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Ensure the input is iterable of parsers
    if not root_subparsers:
        raise ValueError("root_subparsers must be provided and not empty")
    try:
        # Support both dict of name->parser and iterable of parsers
        if isinstance(root_subparsers, dict):
            parser_iter = root_subparsers.values()
        else:
            parser_iter = root_subparsers
        for parser in parser_iter:
            parser.add_argument(
                '--spec',
                '-s',
                dest='spec',
                help='Target spec to operate on',
                required=False
            )
    except Exception as exc:
        raise RuntimeError(f"Failed to extend CLI parsers: {exc}") from exc
    return None

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Attempt to add a 'spec' subcommand if the subparser supports it.
    try:
        # Paradoxical name - the spec command
        if hasattr(root_subparsers, "add_parser"):
            # Keep track of what we've added to avoid duplicates
            added = getattr(root_subparsers, "_added_spec_cmds", set())
            if "spec" not in added:
                spec_parser = root_subparsers.add_parser(
                    "spec", help="Specify a target spec to act upon"
                )
                spec_parser.add_argument(
                    "spec",
                    nargs="?",
                    default=None,
                    help="Target spec to operate on (e.g., path/to:target)",
                )
                added.add("spec")
                setattr(root_subparsers, "_added_spec_cmds", added)
        else:
            # Possibly a dictionary of already built subparsers
            for name, subparser in root_subparsers.items():
                # Avoid adding duplicate arguments
                try:
                    subparser.add_argument(
                        "--spec",
                        help="Target spec to operate on (e.g., path/to:target)",
                    )
                except Exception:
                    # ignore if this argument already exists
                    pass
    except Exception as exc:
        # Generic guard so the CLI doesn't crash on adding spec options
        raise RuntimeError(f"Failed to extend CLI with spec options: {exc}") from exc

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param root_subparsers: a collection (iterable of or mapping to) subparser objects to extend.
    """
    # Determine iterable of subparsers
    if isinstance(root_subparsers, dict):
        subparsers = root_subparsers.values()
    else:
        try:
            subparsers = iter(root_subparsers)
        except TypeError:
            raise TypeError("root_subparsers must be an iterable or mapping of subparsers")

    for sp in subparsers:
        # Guard against objects without add_argument
        if not hasattr(sp, 'add_argument'):
            raise AttributeError(f"Subparser object {sp!r} has no add_argument method")
        try:
            sp.add_argument(
                '--spec',
                help=('Specification to use, optionally include path and target name, '
                      'e.g., "path/to/file:target_name"'))
        except Exception as exc:
            # Log the issue in a way that tests can pick up, but do not crash
            # If the subparser is read-only or immutable, skip adding.
            continue
    return None

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    abspath = os.path.abspath(path)
    abroot = os.path.abspath(root)
    try:
        relative = os.path.relpath(abspath, abroot)
    except ValueError as exc:
        raise ValueError(f"Cannot strip root '{root}' from path '{path}': {exc}") from exc
    if relative == os.curdir:
        return ''
    if relative == os.pardir or relative.startswith(os.pardir + os.sep):
        raise ValueError(f"Root '{root}' is not a parent of path '{path}'")
    return relative

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os

    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")

    norm_root = os.path.normpath(os.path.abspath(root))
    norm_path = os.path.normpath(os.path.abspath(path))

    if not norm_path.startswith(norm_root):
        raise ValueError(
            f"Path '{path}' does not start with root '{root}'."
        )

    # Ensure that the match is a full path component
    if len(norm_path) > len(norm_root):
        next_char = norm_path[len(norm_root)]
        if next_char != os.sep:
            raise ValueError(
                f"Path '{path}' is not a subpath of root '{root}'."
            )

    # Strip the root
    stripped = norm_path[len(norm_root):]
    # Remove leading separator if present
    if stripped.startswith(os.sep):
        stripped = stripped[len(os.sep):]

    return stripped
